{
  "name": "Vista Accounting Pro",
  "description": "A comprehensive accounting system with automated transaction recording, multi-account ledgers, and real-time financial statements (Balance Sheet, Income Statement, Cash Flow, Trial Balance)."
}

export enum NaturalBalance {
  DEBIT = 'DR',
  CREDIT = 'CR'
}

export enum FinancialStatement {
  BALANCE_SHEET = 'Balance Sheet',
  INCOME_STATEMENT = 'Income Statement'
}

export enum AccountClassification {
  CURRENT_ASSET = 'Current Asset',
  LONG_TERM_ASSET = 'Long-Term Asset',
  CURRENT_LIABILITY = 'Current Liability',
  LONG_TERM_LIABILITY = 'Long-Term Liability',
  EQUITY = 'Equity',
  REVENUE = 'Revenue',
  COGS = 'Cost of Goods Sold',
  OPERATING_EXPENSE = 'Operating Expenses',
  OTHER_INCOME_EXPENSE = 'Other Income (Expenses)'
}

export interface Account {
  id: string;
  name: string;
  naturalBalance: NaturalBalance;
  financialStatement: FinancialStatement;
  classification: AccountClassification;
}

export interface JournalEntryLine {
  id: string;
  accountId: string;
  debit: number;
  credit: number;
  description: string;
}

export interface JournalEntry {
  id: number;
  date: string;
  method: string;
  lines: JournalEntryLine[];
}

export type TabType = 
  | 'Transaction Recorder' 
  | 'General Journal' 
  | 'Ledgers' 
  | 'BS' 
  | 'IS' 
  | 'CF' 
  | 'Trial Balance';

import { Account, NaturalBalance, FinancialStatement, AccountClassification } from './types';

export const INITIAL_ACCOUNTS: Account[] = [
  { id: '1', name: 'Cash', naturalBalance: NaturalBalance.DEBIT, financialStatement: FinancialStatement.BALANCE_SHEET, classification: AccountClassification.CURRENT_ASSET },
  { id: '2', name: 'Accounts Receivable', naturalBalance: NaturalBalance.DEBIT, financialStatement: FinancialStatement.BALANCE_SHEET, classification: AccountClassification.CURRENT_ASSET },
  { id: '3', name: 'Inventory', naturalBalance: NaturalBalance.DEBIT, financialStatement: FinancialStatement.BALANCE_SHEET, classification: AccountClassification.CURRENT_ASSET },
  { id: '4', name: 'Equipment', naturalBalance: NaturalBalance.DEBIT, financialStatement: FinancialStatement.BALANCE_SHEET, classification: AccountClassification.LONG_TERM_ASSET },
  { id: '5', name: 'Credit Cards', naturalBalance: NaturalBalance.CREDIT, financialStatement: FinancialStatement.BALANCE_SHEET, classification: AccountClassification.CURRENT_LIABILITY },
  { id: '6', name: 'Benson, Contributions', naturalBalance: NaturalBalance.CREDIT, financialStatement: FinancialStatement.BALANCE_SHEET, classification: AccountClassification.EQUITY },
  { id: '7', name: 'Revenue', naturalBalance: NaturalBalance.CREDIT, financialStatement: FinancialStatement.INCOME_STATEMENT, classification: AccountClassification.REVENUE },
  { id: '8', name: 'Cost of Goods Sold', naturalBalance: NaturalBalance.DEBIT, financialStatement: FinancialStatement.INCOME_STATEMENT, classification: AccountClassification.COGS },
  { id: '9', name: 'Supplies Expense', naturalBalance: NaturalBalance.DEBIT, financialStatement: FinancialStatement.INCOME_STATEMENT, classification: AccountClassification.OPERATING_EXPENSE },
  { id: '10', name: 'Subscriptions Expense', naturalBalance: NaturalBalance.DEBIT, financialStatement: FinancialStatement.INCOME_STATEMENT, classification: AccountClassification.OPERATING_EXPENSE },
];

export const CLASSIFICATIONS = Object.values(AccountClassification);
export const STATEMENTS = Object.values(FinancialStatement);

import React, { useState, useMemo, useEffect } from 'react';
import { JournalEntry, Account, TabType, NaturalBalance } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>('Transaction Recorder');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [showAccountModal, setShowAccountModal] = useState(false);

  // Persistence (Optional simple load)
  useEffect(() => {
    const savedAccounts = localStorage.getItem('vista_accounts');
    const savedTransactions = localStorage.getItem('vista_transactions');
    if (savedAccounts) setAccounts(JSON.parse(savedAccounts));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
  }, []);

  useEffect(() => {
    localStorage.setItem('vista_accounts', JSON.stringify(accounts));
    localStorage.setItem('vista_transactions', JSON.stringify(transactions));
  }, [accounts, transactions]);

  const addAccount = (newAcc: Account) => {
    setAccounts(prev => [...prev, newAcc]);
  };

  const recordTransaction = (entry: JournalEntry) => {
    setTransactions(prev => [...prev, entry]);
  };

  const tabs: TabType[] = [
    'Transaction Recorder',
    'Ledgers',
    'General Journal',
    'BS',
    'IS',
    'CF',
    'Trial Balance'
  ];

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="bg-slate-800 text-white p-4 shadow-md flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <h1 className="text-xl font-bold tracking-tight">VISTA SHORE PRODUCTS, LLC</h1>
          <span className="bg-emerald-500 text-xs font-bold px-2 py-1 rounded uppercase">Accounting System</span>
        </div>
        <button 
          onClick={() => setShowAccountModal(true)}
          className="bg-white text-slate-800 hover:bg-slate-100 font-semibold py-1.5 px-4 rounded transition-colors text-sm"
        >
          + Create Account
        </button>
      </header>

      {/* Tabs */}
      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm">
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-6 py-3 text-sm font-medium whitespace-nowrap transition-all border-b-2 ${
              activeTab === tab 
                ? 'border-emerald-500 text-emerald-600 bg-emerald-50' 
                : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
            }`}
          >
            {tab}
          </button>
        ))}
      </nav>

      {/* Main Content */}
      <main className="flex-1 p-6 overflow-y-auto">
        <div className="max-w-7xl mx-auto bg-white rounded-lg shadow-sm border p-6">
          {activeTab === 'Transaction Recorder' && (
            <TransactionRecorder 
              accounts={accounts} 
              onRecord={recordTransaction} 
              lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 537}
            />
          )}
          {activeTab === 'General Journal' && (
            <GeneralJournal transactions={transactions} accounts={accounts} />
          )}
          {activeTab === 'Ledgers' && (
            <Ledgers transactions={transactions} accounts={accounts} />
          )}
          {activeTab === 'BS' && (
            <BalanceSheet transactions={transactions} accounts={accounts} />
          )}
          {activeTab === 'IS' && (
            <IncomeStatement transactions={transactions} accounts={accounts} />
          )}
          {activeTab === 'CF' && (
            <CashFlowStatement transactions={transactions} accounts={accounts} />
          )}
          {activeTab === 'Trial Balance' && (
            <TrialBalance transactions={transactions} accounts={accounts} />
          )}
        </div>
      </main>

      {showAccountModal && (
        <AccountModal 
          onClose={() => setShowAccountModal(false)} 
          onSave={addAccount} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Account, JournalEntry, JournalEntryLine } from '../types';

interface Props {
  accounts: Account[];
  onRecord: (entry: JournalEntry) => void;
  lastId: number;
}

const TransactionRecorder: React.FC<Props> = ({ accounts, onRecord, lastId }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [method, setMethod] = useState('');
  const [lines, setLines] = useState<JournalEntryLine[]>([
    { id: '1', accountId: '', debit: 0, credit: 0, description: '' },
    { id: '2', accountId: '', debit: 0, credit: 0, description: '' }
  ]);

  const totalDebits = lines.reduce((sum, l) => sum + (l.debit || 0), 0);
  const totalCredits = lines.reduce((sum, l) => sum + (l.credit || 0), 0);
  const isBalanced = Math.abs(totalDebits - totalCredits) < 0.01 && totalDebits > 0;

  const addLine = () => {
    setLines([...lines, { id: Math.random().toString(), accountId: '', debit: 0, credit: 0, description: '' }]);
  };

  const removeLine = (id: string) => {
    if (lines.length > 2) {
      setLines(lines.filter(l => l.id !== id));
    }
  };

  const updateLine = (id: string, field: keyof JournalEntryLine, value: any) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: value } : l));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isBalanced) {
      alert("Debits must equal credits!");
      return;
    }

    const entry: JournalEntry = {
      id: lastId + 1,
      date,
      method,
      lines: lines.filter(l => l.accountId && (l.debit > 0 || l.credit > 0))
    };

    onRecord(entry);

    // Reset form
    setMethod('');
    setLines([
      { id: '1', accountId: '', debit: 0, credit: 0, description: '' },
      { id: '2', accountId: '', debit: 0, credit: 0, description: '' }
    ]);
    alert("Transaction recorded successfully!");
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6 border-b pb-2">Record Journal Entry</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 bg-slate-50 p-4 rounded-lg border">
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Transaction ID</label>
            <input type="text" disabled value={lastId + 1} className="w-full bg-gray-100 border rounded px-3 py-2 text-gray-600" />
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Date</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)} 
              className="w-full border rounded px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none" 
              required
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Method / Card</label>
            <input 
              type="text" 
              value={method} 
              onChange={(e) => setMethod(e.target.value)} 
              placeholder="e.g. AmEx 1001, MC 6214"
              className="w-full border rounded px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none" 
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm border-collapse">
            <thead>
              <tr className="bg-slate-100 border-b">
                <th className="p-3 text-left font-semibold text-gray-600">Account</th>
                <th className="p-3 text-left font-semibold text-gray-600 w-32">Debit</th>
                <th className="p-3 text-left font-semibold text-gray-600 w-32">Credit</th>
                <th className="p-3 text-left font-semibold text-gray-600">Description</th>
                <th className="p-3 w-10"></th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {lines.map((line) => (
                <tr key={line.id} className="hover:bg-gray-50">
                  <td className="p-2">
                    <select
                      value={line.accountId}
                      onChange={(e) => updateLine(line.id, 'accountId', e.target.value)}
                      className="w-full border rounded px-2 py-1.5 focus:ring-2 focus:ring-emerald-500 outline-none"
                    >
                      <option value="">Select Account...</option>
                      {accounts.sort((a,b) => a.name.localeCompare(b.name)).map(acc => (
                        <option key={acc.id} value={acc.id}>{acc.name}</option>
                      ))}
                    </select>
                  </td>
                  <td className="p-2">
                    <input
                      type="number"
                      step="0.01"
                      value={line.debit || ''}
                      onChange={(e) => updateLine(line.id, 'debit', parseFloat(e.target.value) || 0)}
                      className="w-full border rounded px-2 py-1.5 text-right font-mono"
                      placeholder="0.00"
                    />
                  </td>
                  <td className="p-2">
                    <input
                      type="number"
                      step="0.01"
                      value={line.credit || ''}
                      onChange={(e) => updateLine(line.id, 'credit', parseFloat(e.target.value) || 0)}
                      className="w-full border rounded px-2 py-1.5 text-right font-mono"
                      placeholder="0.00"
                    />
                  </td>
                  <td className="p-2">
                    <input
                      type="text"
                      value={line.description}
                      onChange={(e) => updateLine(line.id, 'description', e.target.value)}
                      className="w-full border rounded px-2 py-1.5"
                      placeholder="Notes..."
                    />
                  </td>
                  <td className="p-2 text-center">
                    <button 
                      type="button"
                      onClick={() => removeLine(line.id)}
                      className="text-red-400 hover:text-red-600 p-1"
                      title="Remove Row"
                    >
                      ✕
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr className="bg-slate-50 font-bold border-t-2 border-slate-200">
                <td className="p-3 text-right">Totals:</td>
                <td className={`p-3 text-right font-mono ${totalDebits !== totalCredits ? 'text-red-500' : 'text-emerald-600'}`}>
                  {totalDebits.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td className={`p-3 text-right font-mono ${totalDebits !== totalCredits ? 'text-red-500' : 'text-emerald-600'}`}>
                  {totalCredits.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td colSpan={2} className="p-3">
                  {!isBalanced && totalDebits + totalCredits > 0 && (
                    <span className="text-xs text-red-500 font-medium">Out of balance by {(Math.abs(totalDebits - totalCredits)).toFixed(2)}</span>
                  )}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>

        <div className="flex justify-between items-center pt-4 border-t">
          <button 
            type="button" 
            onClick={addLine}
            className="text-emerald-600 font-semibold text-sm hover:underline"
          >
            + Add Row
          </button>

          <button 
            type="submit"
            disabled={!isBalanced}
            className={`px-8 py-3 rounded-lg font-bold shadow transition-all ${
              isBalanced 
                ? 'bg-emerald-600 text-white hover:bg-emerald-700 transform hover:-translate-y-0.5' 
                : 'bg-gray-300 text-gray-500 cursor-not-allowed'
            }`}
          >
            Record JE
          </button>
        </div>
      </form>
    </div>
  );
};

export default TransactionRecorder;

import React from 'react';
import { JournalEntry, Account } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
}

const GeneralJournal: React.FC<Props> = ({ transactions, accounts }) => {
  const accountMap = new Map(accounts.map(a => [a.id, a]));

  const sortedTransactions = [...transactions].sort((a, b) => b.id - a.id);

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6 border-b pb-2">General Journal</h2>
      <div className="overflow-x-auto">
        <table className="w-full text-sm border-collapse">
          <thead>
            <tr className="bg-slate-100 border-b">
              <th className="p-3 text-left font-semibold text-gray-600 w-16">ID</th>
              <th className="p-3 text-left font-semibold text-gray-600 w-24">Date</th>
              <th className="p-3 text-left font-semibold text-gray-600">Account</th>
              <th className="p-3 text-right font-semibold text-gray-600 w-32">Debit</th>
              <th className="p-3 text-right font-semibold text-gray-600 w-32">Credit</th>
              <th className="p-3 text-left font-semibold text-gray-600">Description / Method</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {sortedTransactions.length === 0 && (
              <tr>
                <td colSpan={6} className="p-8 text-center text-gray-400 italic">No transactions recorded yet.</td>
              </tr>
            )}
            {sortedTransactions.map((entry) => (
              <React.Fragment key={entry.id}>
                {entry.lines.map((line, idx) => {
                  const account = accountMap.get(line.accountId);
                  return (
                    <tr key={line.id} className={`${idx === 0 ? 'border-t-2 border-slate-200 bg-white' : 'bg-white'} hover:bg-slate-50`}>
                      <td className="p-3 align-top font-mono text-xs text-gray-400">{idx === 0 ? entry.id : ''}</td>
                      <td className="p-3 align-top text-gray-600">{idx === 0 ? entry.date : ''}</td>
                      <td className={`p-3 font-medium ${line.credit > 0 ? 'pl-10' : ''}`}>
                        {account?.name || 'Unknown Account'}
                      </td>
                      <td className="p-3 text-right font-mono text-emerald-700">
                        {line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                      </td>
                      <td className="p-3 text-right font-mono text-amber-700">
                        {line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                      </td>
                      <td className="p-3 text-gray-500 italic max-w-xs truncate">
                        {line.description} {idx === 0 && entry.method && <span className="text-slate-400 not-italic ml-2">({entry.method})</span>}
                      </td>
                    </tr>
                  );
                })}
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default GeneralJournal;

import React from 'react';
import { JournalEntry, Account, NaturalBalance } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
}

const Ledgers: React.FC<Props> = ({ transactions, accounts }) => {
  // Sort accounts by name for easy navigation
  const sortedAccounts = [...accounts].sort((a,b) => a.name.localeCompare(b.name));

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6 border-b pb-2">Ledgers</h2>

      <div className="grid grid-cols-1 gap-12">
        {sortedAccounts.map(account => {
          // Get all lines affecting this account
          const accountLines = transactions.flatMap(t => 
            t.lines
              .filter(l => l.accountId === account.id)
              .map(l => ({ ...l, date: t.date, txId: t.id, method: t.method }))
          ).sort((a,b) => a.txId - b.txId);

          let currentBalance = 0;

          return (
            <div key={account.id} className="border rounded-lg shadow-sm overflow-hidden">
              <div className="bg-slate-800 text-white p-3 flex justify-between items-center">
                <h3 className="font-bold text-lg">{account.name}</h3>
                <div className="flex gap-4 text-xs font-semibold">
                  <span className="opacity-70">Type: {account.classification}</span>
                  <span className="bg-white/20 px-2 py-0.5 rounded">Natural: {account.naturalBalance}</span>
                </div>
              </div>

              <table className="w-full text-xs text-left border-collapse">
                <thead className="bg-slate-100 border-b">
                  <tr>
                    <th className="p-2 border-r w-16">Tx ID</th>
                    <th className="p-2 border-r w-24">Date</th>
                    <th className="p-2 border-r">Method/Ref</th>
                    <th className="p-2 border-r text-right w-24">Debit</th>
                    <th className="p-2 border-r text-right w-24">Credit</th>
                    <th className="p-2 border-r text-right w-32">Balance ({account.naturalBalance})</th>
                    <th className="p-2">Description</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {accountLines.length === 0 ? (
                    <tr>
                      <td colSpan={7} className="p-4 text-center text-gray-400 italic">No activity for this account.</td>
                    </tr>
                  ) : (
                    accountLines.map((line, idx) => {
                      if (account.naturalBalance === NaturalBalance.DEBIT) {
                        currentBalance += (line.debit - line.credit);
                      } else {
                        currentBalance += (line.credit - line.debit);
                      }

                      return (
                        <tr key={`${line.txId}-${idx}`} className="hover:bg-slate-50">
                          <td className="p-2 border-r font-mono text-gray-500">{line.txId}</td>
                          <td className="p-2 border-r">{line.date}</td>
                          <td className="p-2 border-r text-gray-600 truncate max-w-[120px]">{line.method}</td>
                          <td className="p-2 border-r text-right font-mono text-emerald-600">
                            {line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                          </td>
                          <td className="p-2 border-r text-right font-mono text-amber-600">
                            {line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                          </td>
                          <td className="p-2 border-r text-right font-mono font-bold bg-slate-50">
                            {currentBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                          </td>
                          <td className="p-2 text-gray-500 italic truncate max-w-[200px]">{line.description}</td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Ledgers;

import React from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
}

const BalanceSheet: React.FC<Props> = ({ transactions, accounts }) => {
  const getBalance = (accountId: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let balance = 0;
    transactions.forEach(tx => {
      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) {
            balance += (l.debit - l.credit);
          } else {
            balance += (l.credit - l.debit);
          }
        }
      });
    });
    return balance;
  };

  // Calculate Net Income to include in Equity
  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
  let netIncome = 0;
  isAccounts.forEach(acc => {
    const b = getBalance(acc.id);
    if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
       // Assuming Revenue is CR natural. If b > 0, it means profit.
       netIncome += b; 
    } else {
       // Expenses are DR natural. If b > 0, it means cost.
       netIncome -= b;
    }
  });

  const bsAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.BALANCE_SHEET);

  const renderSection = (title: string, classification: AccountClassification) => {
    const filtered = bsAccounts.filter(a => a.classification === classification);
    const total = filtered.reduce((sum, a) => sum + getBalance(a.id), 0);
    return { 
      elements: (
        <>
          <tr className="bg-slate-50"><td colSpan={2} className="p-2 font-bold text-sm text-slate-600 uppercase tracking-wider">{title}</td></tr>
          {filtered.map(acc => (
            <tr key={acc.id} className="border-b">
              <td className="p-2 pl-6 text-sm">{acc.name}</td>
              <td className="p-2 text-right text-sm font-mono">{getBalance(acc.id).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
            </tr>
          ))}
          <tr className="font-bold bg-white">
            <td className="p-2 pl-4 italic">Total {title}</td>
            <td className="p-2 text-right font-mono border-t-2 border-slate-900">{total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
          </tr>
        </>
      ),
      total 
    };
  };

  const currentAssets = renderSection("Current Assets", AccountClassification.CURRENT_ASSET);
  const fixedAssets = renderSection("Long-Term Assets", AccountClassification.LONG_TERM_ASSET);
  const currentLiabilities = renderSection("Current Liabilities", AccountClassification.CURRENT_LIABILITY);
  const longTermLiabilities = renderSection("Long-Term Liabilities", AccountClassification.LONG_TERM_LIABILITY);
