import React from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification, TabType } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onNavigate: (tab: TabType) => void;
}

const Dashboard: React.FC<Props> = ({ transactions, accounts, onNavigate }) => {
  const getBalance = (accountId: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;
    let balance = 0;
    transactions.forEach(tx => {
      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
          else balance += (l.credit - l.debit);
        }
      });
    });
    return balance;
  };

  const cash = accounts.filter(a => a.name.toLowerCase().includes('cash')).reduce((sum, a) => sum + getBalance(a.id), 0);
  const inventory = accounts.filter(a => a.classification === AccountClassification.CURRENT_ASSET && a.name.toLowerCase().includes('inventory')).reduce((sum, a) => sum + getBalance(a.id), 0);
  const liabilities = accounts.filter(a => a.classification === AccountClassification.CURRENT_LIABILITY || a.classification === AccountClassification.LONG_TERM_LIABILITY).reduce((sum, a) => sum + getBalance(a.id), 0);

  // Net Income calculation
  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
  let netIncome = 0;
  isAccounts.forEach(acc => {
    const b = getBalance(acc.id);
    if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
       netIncome += b; 
    } else {
       netIncome -= b;
    }
  });

  const stats = [
    { name: 'Cash on Hand', value: cash, color: 'text-emerald-600', bg: 'bg-emerald-50', icon: '💰' },
    { name: 'Inventory Asset', value: inventory, color: 'text-indigo-600', bg: 'bg-indigo-50', icon: '📦' },
    { name: 'Total Liabilities', value: liabilities, color: 'text-amber-600', bg: 'bg-amber-50', icon: '💳' },
    { name: 'Net Income (All Time)', value: netIncome, color: netIncome >= 0 ? 'text-emerald-600' : 'text-red-600', bg: netIncome >= 0 ? 'bg-emerald-50' : 'bg-red-50', icon: '📈' },
  ];

  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-3xl font-extrabold text-slate-900">Financial Overview</h2>
        <p className="text-slate-500">Real-time health of Vista Shore Products, LLC</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat) => (
          <div key={stat.name} className={`${stat.bg} p-6 rounded-2xl border border-white shadow-sm transition-all hover:shadow-md`}>
            <div className="flex justify-between items-start mb-4">
              <span className="text-2xl">{stat.icon}</span>
              <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Live</span>
            </div>
            <p className="text-sm font-semibold text-slate-600 mb-1">{stat.name}</p>
            <p className={`text-2xl font-black font-mono ${stat.color}`}>
              ${stat.value.toLocaleString(undefined, { minimumFractionDigits: 2 })}
            </p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mt-12">
        <div className="bg-slate-50 p-6 rounded-2xl border">
          <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <span className="w-2 h-6 bg-emerald-500 rounded-full"></span>
            Quick Actions
          </h3>
          <div className="grid grid-cols-2 gap-4">
            <button 
              onClick={() => onNavigate('Transaction Recorder')}
              className="bg-white p-4 rounded-xl border hover:border-emerald-500 hover:text-emerald-600 transition-all font-bold text-sm text-left shadow-sm"
