import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [showAccountModal, setShowAccountModal] = useState(false);

  // Auth Listener
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // Firestore Sync Listener
  useEffect(() => {
    if (!user) return;

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    // Subscribe to real-time updates from Firestore
    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
      } else {
        // First time user - seed with initial accounts
        setDoc(userDocRef, { accounts: INITIAL_ACCOUNTS, transactions: [] });
      }
      setDataLoading(false);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = async (newAccounts: Account[], newTransactions: JournalEntry[]) => {
    if (!user) return;
    try {
      await setDoc(doc(db, 'users', user.uid), {
        accounts: newAccounts,
        transactions: newTransactions,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err) {
      console.error("Error saving to Firestore:", err);
    }
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions);
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Are you sure you want to delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated);
    }
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const existingNames = new Set(accounts.map(a => a.name.toLowerCase()));
    const uniqueNew = newAccounts.filter(a => !existingNames.has(a.name.toLowerCase()));
    const updatedAccs = [...accounts, ...uniqueNew];
    const updatedTxs = [...transactions, ...newTransactions];

    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs);
    alert("Import successful! Data synced to cloud.");
  };

  if (authLoading) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <div className="animate-pulse flex flex-col items-center gap-4">
          <div className="w-12 h-12 bg-emerald-500 rounded-lg"></div>
          <div className="h-4 w-32 bg-slate-800 rounded"></div>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Login />;
  }

  const tabs: TabType[] = [
    'Dashboard',
    'Transaction Recorder',
    'Ledgers',
    'General Journal',
    'BS',
    'IS',
    'CF',
    'Trial Balance',
    'Data Manager'
  ];

  return (
    <div className="min-h-screen flex flex-col">
      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"></path></svg>
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">VISTA SHORE PRODUCTS, LLC</h1>
            <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-[0.2em]">Enterprise Resource Planning</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end border-r border-slate-700 pr-6">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter">Current User</span>
            <span className="text-sm font-semibold">{user.displayName || user.email}</span>
          </div>
          <div className="flex gap-3">
            <button 
              onClick={() => setShowAccountModal(true)}
              className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-2 px-6 rounded-lg transition-all text-sm shadow-md"
            >
              + Create Account
            </button>
            <button 
              onClick={() => signOut(auth)}
              className="bg-slate-800 hover:bg-red-900 text-slate-300 hover:text-white font-bold py-2 px-4 rounded-lg transition-all text-sm border border-slate-700"
            >
              Logout
            </button>
          </div>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-6 py-4 text-sm font-semibold whitespace-nowrap transition-all border-b-4 ${
              activeTab === tab 
                ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' 
                : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
            }`}
          >
            {tab}
          </button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto">
        <div className="max-w-7xl mx-auto relative">
          {dataLoading && (
            <div className="absolute top-0 right-0 p-4 z-50">
              <span className="flex items-center gap-2 text-xs font-bold text-slate-400 animate-pulse">
                <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
                Syncing with Cloud...
              </span>
            </div>
          )}

          <div className="bg-white rounded-xl shadow-sm border p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && (
              <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} />
            )}
            {activeTab === 'Transaction Recorder' && (
              <TransactionRecorder 
                accounts={accounts} 
                onRecord={recordTransaction} 
                lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0}
              />
            )}
            {activeTab === 'General Journal' && (
              <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} />
            )}
            {activeTab === 'Ledgers' && (
              <Ledgers transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'BS' && (
              <BalanceSheet transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'IS' && (
              <IncomeStatement transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'CF' && (
              <CashFlowStatement transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'Trial Balance' && (
              <TrialBalance transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'Data Manager' && (
              <DataManager accounts={accounts} onImport={importData} />
            )}
          </div>
        </div>
      </main>

      {showAccountModal && (
        <AccountModal 
          onClose={() => setShowAccountModal(false)} 
          onSave={addAccount} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
}

const BalanceSheet: React.FC<Props> = ({ transactions, accounts }) => {
  // Extract all unique months for columns
  const periods = useMemo(() => {
    const unique = new Set<string>();
    transactions.forEach(t => {
      const date = new Date(t.date);
      if (!isNaN(date.getTime())) {
        unique.add(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`);
      }
    });
    return Array.from(unique).sort().reverse(); 
  }, [transactions]);

  // Balance Sheet is Point-in-Time, so we need cumulative balance up to the end of a period
  const getBalance = (accountId: string, upToPeriod?: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let balance = 0;
    transactions.forEach(tx => {
      // If period filter is applied, we only count transactions on or before the end of that period
      if (upToPeriod) {
        const txDate = new Date(tx.date);
        const [year, month] = upToPeriod.split('-').map(Number);
        const lastDayOfPeriod = new Date(year, month, 0); // Day 0 of next month is last day of current
        if (txDate > lastDayOfPeriod) return;
      }

      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) {
            balance += (l.debit - l.credit);
          } else {
            balance += (l.credit - l.debit);
          }
        }
      });
    });
    return balance;
  };

  // Helper for Net Income in Equity (Cumulative up to period)
  const getNetIncome = (upToPeriod: string) => {
    const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
    let net = 0;
    isAccounts.forEach(acc => {
      const b = getBalance(acc.id, upToPeriod);
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
         net += b; 
      } else {
         net -= b;
      }
    });
    return net;
  };

  const bsAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.BALANCE_SHEET);

  const calculateTotal = (classification: AccountClassification, upToPeriod: string) => {
    return bsAccounts
      .filter(a => a.classification === classification)
      .reduce((sum, a) => sum + getBalance(a.id, upToPeriod), 0);
  };

  const renderCells = (id: string | AccountClassification, isClassification: boolean) => {
    return periods.map(p => {
      const val = isClassification 
        ? calculateTotal(id as AccountClassification, p)
        : getBalance(id as string, p);
      return (
        <td key={p} className="p-2 text-right font-mono text-xs border-r border-slate-100">
          {val.toLocaleString(undefined, { minimumFractionDigits: 2 })}
        </td>
      );
    });
  };

  const renderSection = (title: string, classification: AccountClassification) => {
    const filtered = bsAccounts.filter(a => a.classification === classification);
    return (
      <>
        <tr className="bg-slate-50">
          <td className="p-2 font-bold text-slate-800 uppercase text-[10px] tracking-widest border-r">{title}</td>
          {periods.map(p => <td key={p} className="bg-slate-50 border-r border-slate-100"></td>)}
        </tr>
        {filtered.map(acc => (
          <tr key={acc.id} className="border-b hover:bg-slate-50/50">
            <td className="p-2 pl-6 text-xs font-medium text-slate-600 border-r">{acc.name}</td>
            {renderCells(acc.id, false)}
          </tr>
        ))}
        <tr className="font-bold border-t border-slate-400 bg-slate-50/20">
          <td className="p-2 pl-4 text-xs italic border-r">Total {title}</td>
          {renderCells(classification, true)}
        </tr>
      </>
    );
  };

  return (
    <div className="w-full">
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold uppercase">Monthly Comparative Balance Sheet</h2>
        <p className="text-gray-500 font-medium italic">Vista Shore Products, LLC</p>
        <p className="text-[10px] text-slate-400 uppercase tracking-widest font-bold mt-1">(Cumulative Point-in-Time Balances)</p>
      </div>

      <div className="overflow-x-auto border rounded-xl shadow-sm">
        <table className="w-full border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-800 text-white">
              <th className="p-3 text-left w-64 border-r border-slate-700">Accounts</th>
              {periods.map(p => (
                <th key={p} className="p-3 text-right text-xs uppercase tracking-tighter border-r border-slate-700">
                  {new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            <tr className="bg-slate-200"><td colSpan={periods.length + 1} className="p-2 font-black text-slate-800 text-xs">ASSETS</td></tr>
            {renderSection("Current Assets", AccountClassification.CURRENT_ASSET)}
            <tr className="h-2"></tr>
            {renderSection("Long-Term Assets", AccountClassification.LONG_TERM_ASSET)}
            <tr className="bg-slate-900 text-white font-bold">
              <td className="p-3 text-xs uppercase tracking-widest border-r border-slate-700">TOTAL ASSETS</td>
              {periods.map(p => {
                const total = calculateTotal(AccountClassification.CURRENT_ASSET, p) + calculateTotal(AccountClassification.LONG_TERM_ASSET, p);
                return <td key={p} className="p-3 text-right font-mono text-sm border-r border-slate-700">${total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>

            <tr className="h-8"></tr>

            <tr className="bg-slate-200"><td colSpan={periods.length + 1} className="p-2 font-black text-slate-800 text-xs">LIABILITIES & EQUITY</td></tr>
            {renderSection("Current Liabilities", AccountClassification.CURRENT_LIABILITY)}
            <tr className="h-2"></tr>
            {renderSection("Long-Term Liabilities", AccountClassification.LONG_TERM_LIABILITY)}
            <tr className="h-4"></tr>
            {renderSection("Equity", AccountClassification.EQUITY)}
            <tr className="border-b">
              <td className="p-2 pl-6 text-xs text-slate-600 italic border-r">Retained Earnings (Period Net Income)</td>
              {periods.map(p => (
                <td key={p} className="p-2 text-right font-mono text-xs border-r border-slate-100">
                  {getNetIncome(p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
              ))}
            </tr>
            <tr className="bg-slate-900 text-white font-bold">
              <td className="p-3 text-xs uppercase tracking-widest border-r border-slate-700">TOTAL LIABILITIES & EQUITY</td>
              {periods.map(p => {
                const totalL = calculateTotal(AccountClassification.CURRENT_LIABILITY, p) + calculateTotal(AccountClassification.LONG_TERM_LIABILITY, p);
                const totalE = calculateTotal(AccountClassification.EQUITY, p) + getNetIncome(p);
                return <td key={p} className="p-3 text-right font-mono text-sm border-r border-slate-700">${(totalL + totalE).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>
          </tbody>
        </table>
      </div>
      {periods.length === 0 && (
        <div className="p-20 text-center text-slate-400 italic">No historical data found. Point-in-time snapshots require transaction history.</div>
      )}
    </div>
  );
};

export default BalanceSheet;

import React, { useState } from 'react';
import { 
  signInWithPopup, 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  updateProfile
} from 'firebase/auth';
import { auth, microsoftProvider } from '../firebase';

const Login: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Email/Password state
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');

  const handleMicrosoftLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      await signInWithPopup(auth, microsoftProvider);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Failed to sign in with Microsoft.');
    } finally {
      setLoading(false);
    }
  };

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      if (isSignUp) {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        if (displayName) {
          await updateProfile(userCredential.user, { displayName });
        }
      } else {
        await signInWithEmailAndPassword(auth, email, password);
