import React, { useState } from 'react';
import { 
  signInWithPopup, 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  updateProfile
} from 'firebase/auth';
import { auth, googleProvider } from '../firebase';

const Login: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Email/Password state
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');

  const handleGoogleLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Failed to sign in with Google.');
    } finally {
      setLoading(false);
    }
  };

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      if (isSignUp) {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        if (displayName) {
          await updateProfile(userCredential.user, { displayName });
        }
      } else {
        await signInWithEmailAndPassword(auth, email, password);
      }
    } catch (err: any) {
      console.error(err);
      let message = 'An error occurred during authentication.';
      if (err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password' || err.code === 'auth/invalid-credential') {
        message = 'Invalid email or password.';
      } else if (err.code === 'auth/email-already-in-use') {
        message = 'This email is already registered.';
      } else if (err.code === 'auth/weak-password') {
        message = 'Password should be at least 6 characters.';
      }
      setError(message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-2xl overflow-hidden p-8 md:p-10 space-y-6 text-center border border-slate-800/20">
        <div className="flex flex-col items-center gap-3">
          <div className="bg-emerald-500 p-3 rounded-2xl shadow-xl shadow-emerald-500/20">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"></path>
            </svg>
          </div>
          <div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight leading-none">VISTA SHORE</h1>
            <p className="text-[10px] text-emerald-600 font-bold uppercase tracking-[0.3em] mt-1">Accounting Intelligence</p>
          </div>
        </div>

        <div className="space-y-4">
          {error && (
            <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-xl text-xs font-bold animate-shake">
              {error}
            </div>
          )}

          {/* Social Login */}
          <button
            onClick={handleGoogleLogin}
            disabled={loading}
            className="w-full bg-slate-900 hover:bg-slate-800 text-white font-bold py-3.5 rounded-2xl transition-all flex items-center justify-center gap-3 shadow-lg active:scale-[0.98] disabled:opacity-50"
          >
            {loading && !email ? (
              <span className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full"></span>
            ) : (
              <>
                <svg className="w-5 h-5" viewBox="0 0 24 24">
                  <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                  <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                  <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
                  <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
                </svg>
                <span className="text-sm">Sign in with Google</span>
              </>
            )}
          </button>

          <div className="flex items-center gap-4 py-2">
            <div className="h-[1px] bg-slate-100 flex-1"></div>
            <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Or use email</span>
            <div className="h-[1px] bg-slate-100 flex-1"></div>
          </div>

          {/* Email Form */}
          <form onSubmit={handleEmailAuth} className="space-y-3 text-left">
            {isSignUp && (
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Full Name</label>
                <input 
                  type="text" 
                  value={displayName}
                  onChange={(e) => setDisplayName(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-100 px-4 py-3 rounded-xl text-sm outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 transition-all"
                  placeholder="John Doe"
                  required={isSignUp}
                />
              </div>
            )}
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Email Address</label>
              <input 
                type="email" 
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-slate-50 border border-slate-100 px-4 py-3 rounded-xl text-sm outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 transition-all"
                placeholder="name@company.com"
                required
              />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Password</label>
              <input 
                type="password" 
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-slate-50 border border-slate-100 px-4 py-3 rounded-xl text-sm outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 transition-all"
                placeholder="••••••••"
                required
              />
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-3.5 rounded-2xl transition-all shadow-lg shadow-emerald-500/20 active:scale-[0.98] disabled:opacity-50 mt-2"
            >
              {loading && email ? (
                <span className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full mx-auto"></span>
              ) : (
                <span className="text-sm">{isSignUp ? 'Create Account' : 'Sign In to Dashboard'}</span>
              )}
            </button>
          </form>
        </div>

        <div className="pt-6 border-t border-slate-50 space-y-4">
          <p className="text-xs text-slate-500 font-medium">
            {isSignUp ? 'Already have an account?' : "Don't have an account yet?"}{' '}
            <button 
              onClick={() => setIsSignUp(!isSignUp)}
              className="text-emerald-600 font-bold hover:underline"
            >
              {isSignUp ? 'Sign In' : 'Sign Up'}
            </button>
          </p>
          <p className="text-[9px] text-slate-300 uppercase font-black tracking-[0.2em]">
            Enterprise Grade Security Provided by Firebase
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  // Auth Listener
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // Sync Logic
  useEffect(() => {
    if (!user) {
      setCloudError(null);
      return;
    }

    // Try loading from LocalStorage first as an instant fallback
    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
      } catch (e) {
        console.error("Local storage parse error:", e);
      }
    }

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    // Subscribe to real-time updates from Firestore with enhanced error handling
    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      setCloudError(null); // Reset error if we successfully connect
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        // Keep LocalStorage in sync
        localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
          accounts: data.accounts,
          transactions: data.transactions
        }));
      } else {
        // New user or no data - seed cloud
        setDoc(userDocRef, { accounts: INITIAL_ACCOUNTS, transactions: [] })
          .catch(err => console.error("Initial seeding failed:", err));
      }
      setDataLoading(false);
    }, (error) => {
      console.error("Firestore Error Detected:", error);
      setDataLoading(false);

      if (error.code === 'permission-denied' || error.message.includes('disabled')) {
        setCloudError("The Cloud Firestore API is disabled or not initialized for this project. The app is running in Local Fallback Mode.");
      } else {
        setCloudError(`Cloud Sync Issue: ${error.message}`);
      }
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = async (newAccounts: Account[], newTransactions: JournalEntry[]) => {
    if (!user) return;

    // Always save to localStorage immediately for reliability
    localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
      accounts: newAccounts,
      transactions: newTransactions
    }));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        accounts: newAccounts,
        transactions: newTransactions,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Error saving to Firestore:", err);
      // If we haven't already set a cloud error, do it now
      if (!cloudError) {
        setCloudError("Failed to save to cloud. Work is being saved locally instead.");
      }
    }
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions);
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Are you sure you want to delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated);
    }
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const existingNames = new Set(accounts.map(a => a.name.toLowerCase()));
    const uniqueNew = newAccounts.filter(a => !existingNames.has(a.name.toLowerCase()));
    const updatedAccs = [...accounts, ...uniqueNew];
    const updatedTxs = [...transactions, ...newTransactions];

    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs);
    alert("Import successful! Data saved locally and queued for cloud sync.");
  };

  if (authLoading) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <div className="animate-pulse flex flex-col items-center gap-4">
          <div className="w-12 h-12 bg-emerald-500 rounded-lg"></div>
          <div className="h-4 w-32 bg-slate-800 rounded"></div>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Login />;
  }

  const tabs: TabType[] = [
    'Dashboard',
    'Transaction Recorder',
    'Ledgers',
    'General Journal',
    'BS',
    'IS',
    'CF',
    'Trial Balance',
    'Data Manager'
  ];

  return (
    <div className="min-h-screen flex flex-col">
      {/* Cloud Error Banner */}
      {cloudError && (
        <div className="bg-amber-500 text-white px-4 py-2 text-xs font-bold flex items-center justify-between shadow-lg sticky top-0 z-[60]">
          <div className="flex items-center gap-2">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
            <span>{cloudError}</span>
          </div>
          <a 
            href="https://console.firebase.google.com/project/accounting-system-2daaa/firestore" 
            target="_blank" 
            rel="noopener noreferrer"
            className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded transition-colors"
          >
            Enable Cloud API
          </a>
        </div>
      )}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"></path></svg>
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">VISTA SHORE PRODUCTS, LLC</h1>
            <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-[0.2em]">Enterprise Resource Planning</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end border-r border-slate-700 pr-6">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter">Current User</span>
            <span className="text-sm font-semibold">{user.displayName || user.email}</span>
          </div>
          <div className="flex gap-3">
            <button 
              onClick={() => setShowAccountModal(true)}
              className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-2 px-6 rounded-lg transition-all text-sm shadow-md"
            >
              + Create Account
            </button>
            <button 
              onClick={() => signOut(auth)}
              className="bg-slate-800 hover:bg-red-900 text-slate-300 hover:text-white font-bold py-2 px-4 rounded-lg transition-all text-sm border border-slate-700"
            >
              Logout
            </button>
          </div>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-6 py-4 text-sm font-semibold whitespace-nowrap transition-all border-b-4 ${
              activeTab === tab 
                ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' 
                : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
            }`}
          >
            {tab}
          </button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto">
        <div className="max-w-7xl mx-auto relative">
          {dataLoading && (
            <div className="absolute top-0 right-0 p-4 z-50">
              <span className="flex items-center gap-2 text-xs font-bold text-slate-400 animate-pulse">
                <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
                Syncing with Cloud...
              </span>
            </div>
          )}

          <div className="bg-white rounded-xl shadow-sm border p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && (
              <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} />
            )}
            {activeTab === 'Transaction Recorder' && (
              <TransactionRecorder 
                accounts={accounts} 
                onRecord={recordTransaction} 
                lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0}
              />
            )}
            {activeTab === 'General Journal' && (
              <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} />
            )}
            {activeTab === 'Ledgers' && (
              <Ledgers transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'BS' && (
              <BalanceSheet transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'IS' && (
              <IncomeStatement transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'CF' && (
              <CashFlowStatement transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'Trial Balance' && (
              <TrialBalance transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'Data Manager' && (
              <DataManager accounts={accounts} onImport={importData} />
            )}
          </div>
        </div>
      </main>

      {showAccountModal && (
        <AccountModal 
          onClose={() => setShowAccountModal(false)} 
          onSave={addAccount} 
        />
      )}
    </div>
  );
