import React, { useState } from 'react';
import { JournalEntry, Account, NaturalBalance } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onUpdateAccount: (id: string, newName: string) => void;
}

const Ledgers: React.FC<Props> = ({ transactions, accounts, onUpdateAccount }) => {
  // Sort accounts by name for easy navigation
  const sortedAccounts = [...accounts].sort((a,b) => a.name.localeCompare(b.name));

  // Editing state
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState("");

  const startEditing = (account: Account) => {
    setEditingId(account.id);
    setEditValue(account.name);
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditValue("");
  };

  const saveEdit = (id: string) => {
    if (editValue.trim() && editValue.trim() !== accounts.find(a => a.id === id)?.name) {
      onUpdateAccount(id, editValue.trim());
    }
    setEditingId(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent, id: string) => {
    if (e.key === 'Enter') saveEdit(id);
    if (e.key === 'Escape') cancelEditing();
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6 border-b pb-4">
        <h2 className="text-2xl font-bold text-gray-800">Ledgers</h2>
        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Double-Entry Detail Records</p>
      </div>

      <div className="grid grid-cols-1 gap-12">
        {sortedAccounts.map(account => {
          // Get all lines affecting this account
          const accountLines = transactions.flatMap(t => 
            t.lines
              .filter(l => l.accountId === account.id)
              .map(l => ({ ...l, date: t.date, txId: t.id, method: t.method }))
          ).sort((a,b) => a.txId - b.txId);

          let currentBalance = 0;
          const isEditing = editingId === account.id;

          return (
            <div key={account.id} className="border rounded-lg shadow-sm overflow-hidden">
              <div className="bg-slate-800 text-white p-3 flex justify-between items-center">
                <div className="flex items-center gap-3 group">
                  {isEditing ? (
                    <div className="flex items-center gap-2">
                      <input
                        autoFocus
                        type="text"
                        value={editValue}
                        onChange={(e) => setEditValue(e.target.value)}
                        onKeyDown={(e) => handleKeyDown(e, account.id)}
                        onBlur={() => saveEdit(account.id)}
                        className="bg-slate-700 text-white px-2 py-1 rounded border border-slate-500 outline-none focus:ring-1 focus:ring-emerald-500 font-bold"
                      />
                      <button 
                        onMouseDown={(e) => e.preventDefault()} // Prevent blur before click
                        onClick={() => saveEdit(account.id)} 
                        className="text-emerald-400 hover:text-emerald-300"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                      </button>
                      <button 
                        onClick={cancelEditing} 
                        className="text-red-400 hover:text-red-300"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                      </button>
                    </div>
                  ) : (
                    <>
                      <h3 className="font-bold text-lg">{account.name}</h3>
                      <button 
                        onClick={() => startEditing(account)}
                        className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-white transition-all"
                        title="Edit Account Name"
                      >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                      </button>
                    </>
                  )}
                </div>
                <div className="flex gap-4 text-[10px] font-bold uppercase tracking-tighter">
                  <span className="opacity-70 bg-slate-700/50 px-2 py-1 rounded">Type: {account.classification}</span>
                  <span className="bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 px-2 py-1 rounded">Natural: {account.naturalBalance}</span>
                </div>
              </div>

              <table className="w-full text-xs text-left border-collapse">
                <thead className="bg-slate-100 border-b">
                  <tr>
                    <th className="p-2 border-r w-16 text-slate-500 uppercase font-black text-[9px]">Tx ID</th>
                    <th className="p-2 border-r w-24 text-slate-500 uppercase font-black text-[9px]">Date</th>
                    <th className="p-2 border-r text-slate-500 uppercase font-black text-[9px]">Method/Ref</th>
                    <th className="p-2 border-r text-right w-24 text-slate-500 uppercase font-black text-[9px]">Debit</th>
                    <th className="p-2 border-r text-right w-24 text-slate-500 uppercase font-black text-[9px]">Credit</th>
                    <th className="p-2 border-r text-right w-32 text-slate-500 uppercase font-black text-[9px]">Balance ({account.naturalBalance})</th>
                    <th className="p-2 text-slate-500 uppercase font-black text-[9px]">Description</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {accountLines.length === 0 ? (
                    <tr>
                      <td colSpan={7} className="p-4 text-center text-gray-400 italic font-medium">No activity for this account.</td>
                    </tr>
                  ) : (
                    accountLines.map((line, idx) => {
                      if (account.naturalBalance === NaturalBalance.DEBIT) {
                        currentBalance += (line.debit - line.credit);
                      } else {
                        currentBalance += (line.credit - line.debit);
                      }

                      return (
                        <tr key={`${line.txId}-${idx}`} className="hover:bg-slate-50 transition-colors">
                          <td className="p-2 border-r font-mono text-gray-500">{line.txId}</td>
                          <td className="p-2 border-r font-medium text-slate-700">{line.date}</td>
                          <td className="p-2 border-r text-slate-600 truncate max-w-[120px]">
                            {line.method || '-'}
                          </td>
                          <td className="p-2 border-r text-right font-mono font-bold text-emerald-600">
                            {line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                          </td>
                          <td className="p-2 border-r text-right font-mono font-bold text-amber-600">
                            {line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                          </td>
                          <td className={`p-2 border-r text-right font-mono font-black ${currentBalance < 0 ? 'text-red-500' : 'text-slate-900'} bg-slate-50/50`}>
                            {currentBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                          </td>
                          <td className="p-2 text-slate-500 italic truncate max-w-[200px]">{line.description}</td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
              {accountLines.length > 0 && (
                <div className="bg-slate-50 p-2 text-[10px] text-right text-slate-400 font-bold uppercase tracking-widest border-t">
                  Ending Balance: {currentBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Ledgers;

import React, { useState, useEffect, useCallback } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);
  const [retryTrigger, setRetryTrigger] = useState(0);

  // Auth Listener
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // Sync Logic
  useEffect(() => {
    if (!user) {
      setCloudError(null);
      return;
    }

    // Try loading from LocalStorage first as an instant fallback
    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
      } catch (e) {
        console.error("Local storage parse error:", e);
      }
    }

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    // Subscribe to real-time updates from Firestore with enhanced error handling
    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      setCloudError(null); // Reset error if we successfully connect
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        // Keep LocalStorage in sync
        localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
          accounts: data.accounts,
          transactions: data.transactions
        }));
      } else {
        // New user or no data - seed cloud
        setDoc(userDocRef, { accounts: INITIAL_ACCOUNTS, transactions: [] })
          .catch(err => console.error("Initial seeding failed:", err));
      }
      setDataLoading(false);
    }, (error) => {
      console.error("Firestore Error Detected:", error);
      setDataLoading(false);

      if (error.code === 'permission-denied') {
        setCloudError("Security Policy Violation: Access to your data was denied. Ensure Firestore Rules are set to production mode.");
      } else if (error.message.includes('disabled') || error.message.includes('not initialized')) {
        setCloudError("Cloud Firestore is not initialized. Please click 'Create Database' in your Firebase console.");
      } else {
        setCloudError(`Cloud Sync Issue: ${error.message}`);
      }
    });

    return () => unsubscribe();
  }, [user, retryTrigger]);

  const saveToFirestore = async (newAccounts: Account[], newTransactions: JournalEntry[]) => {
    if (!user) return;

    // Always save to localStorage immediately for reliability
    localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
      accounts: newAccounts,
      transactions: newTransactions
    }));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        accounts: newAccounts,
        transactions: newTransactions,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Error saving to Firestore:", err);
      if (err.code === 'permission-denied') {
        setCloudError("Access Denied: You do not have permission to save to this database.");
      } else if (!cloudError) {
        setCloudError("Failed to save to cloud. Work is being saved locally.");
      }
    }
  };

  const handleRefreshConnection = () => {
    setCloudError(null);
    setDataLoading(true);
    setRetryTrigger(prev => prev + 1);
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => 
      acc.id === id ? { ...acc, ...updatedFields } : acc
    );
    setAccounts(updated);
    saveToFirestore(updated, transactions);
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Are you sure you want to delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated);
    }
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const existingNames = new Set(accounts.map(a => a.name.toLowerCase()));
    const uniqueNew = newAccounts.filter(a => !existingNames.has(a.name.toLowerCase()));
    const updatedAccs = [...accounts, ...uniqueNew];
    const updatedTxs = [...transactions, ...newTransactions];

    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs);
    alert("Import successful! Data saved locally.");
  };

  if (authLoading) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <div className="animate-pulse flex flex-col items-center gap-4">
          <div className="w-12 h-12 bg-emerald-500 rounded-lg"></div>
          <div className="h-4 w-32 bg-slate-800 rounded"></div>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Login />;
  }

  const tabs: TabType[] = [
    'Dashboard',
    'Transaction Recorder',
    'Ledgers',
    'General Journal',
    'BS',
    'IS',
    'CF',
    'Trial Balance',
    'Data Manager'
  ];

  return (
    <div className="min-h-screen flex flex-col">
      {/* Cloud Error Banner */}
      {cloudError && (
        <div className="bg-amber-600 text-white px-4 py-3 text-xs font-bold flex items-center justify-between shadow-xl sticky top-0 z-[60]">
          <div className="flex items-center gap-3">
            <div className="bg-white/20 p-1.5 rounded-full">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
            </div>
            <span>{cloudError}</span>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={handleRefreshConnection}
              className="bg-emerald-500 hover:bg-emerald-400 text-white px-4 py-1.5 rounded-lg transition-colors border border-emerald-400 shadow-sm"
            >
              Check Again
            </button>
            <a 
              href="https://console.firebase.google.com/project/accounting-system-2daaa/firestore/rules" 
              target="_blank" 
              rel="noopener noreferrer"
              className="bg-white text-amber-700 hover:bg-slate-100 px-4 py-1.5 rounded-lg transition-colors shadow-sm"
            >
              Update Rules
            </a>
          </div>
        </div>
      )}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"></path></svg>
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-xl font-bold tracking-tight">VISTA SHORE PRODUCTS, LLC</h1>
              <span className="flex items-center gap-1 bg-emerald-500/20 text-emerald-400 text-[8px] font-black px-1.5 py-0.5 rounded border border-emerald-500/30 uppercase tracking-tighter">
                <svg className="w-2.5 h-2.5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd"></path></svg>
                Secure
              </span>
            </div>
            <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-[0.2em]">Enterprise Resource Planning</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end border-r border-slate-700 pr-6">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter">Authenticated User</span>
            <span className="text-sm font-semibold">{user.displayName || user.email}</span>
          </div>
          <div className="flex gap-3">
            <button 
              onClick={() => setShowAccountModal(true)}
              className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-2 px-6 rounded-lg transition-all text-sm shadow-md"
            >
              + Create Account
            </button>
            <button 
              onClick={() => signOut(auth)}
              className="bg-slate-800 hover:bg-red-900 text-slate-300 hover:text-white font-bold py-2 px-4 rounded-lg transition-all text-sm border border-slate-700"
            >
              Logout
            </button>
          </div>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-6 py-4 text-sm font-semibold whitespace-nowrap transition-all border-b-4 ${
              activeTab === tab 
                ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' 
                : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
            }`}
          >
            {tab}
          </button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto">
        <div className="max-w-7xl mx-auto relative">
          {dataLoading && (
            <div className="absolute top-0 right-0 p-4 z-50">
              <span className="flex items-center gap-2 text-xs font-bold text-slate-400 animate-pulse">
                <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
                Syncing with Cloud...
              </span>
            </div>
          )}

          <div className="bg-white rounded-xl shadow-sm border p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && (
              <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} />
            )}
            {activeTab === 'Transaction Recorder' && (
              <TransactionRecorder 
                accounts={accounts} 
                onRecord={recordTransaction} 
                lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0}
              />
            )}
            {activeTab === 'General Journal' && (
              <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} />
            )}
            {activeTab === 'Ledgers' && (
              <Ledgers 
                transactions={transactions} 
                accounts={accounts} 
                onUpdateAccount={updateAccount}
              />
            )}
            {activeTab === 'BS' && (
              <BalanceSheet transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'IS' && (
              <IncomeStatement transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'CF' && (
              <CashFlowStatement transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'Trial Balance' && (
              <TrialBalance transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'Data Manager' && (
              <DataManager accounts={accounts} onImport={importData} />
            )}
          </div>
        </div>
      </main>

      {showAccountModal && (
        <AccountModal 
          onClose={() => setShowAccountModal(false)} 
          onSave={addAccount} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification } from '../types';
import { STATEMENTS, CLASSIFICATIONS } from '../constants';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onUpdateAccount: (id: string, updatedFields: Partial<Account>) => void;
}

const Ledgers: React.FC<Props> = ({ transactions, accounts, onUpdateAccount }) => {
  const sortedAccounts = [...accounts].sort((a,b) => a.name.localeCompare(b.name));

  // Editing state - storing the full draft object
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState<Account | null>(null);

  const startEditing = (account: Account) => {
    setEditingId(account.id);
    setEditDraft({ ...account });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const saveEdit = () => {
    if (editingId && editDraft) {
      onUpdateAccount(editingId, {
        name: editDraft.name.trim(),
        classification: editDraft.classification,
        naturalBalance: editDraft.naturalBalance,
        financialStatement: editDraft.financialStatement
      });
      cancelEditing();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') saveEdit();
    if (e.key === 'Escape') cancelEditing();
  };

  const updateDraft = (field: keyof Account, value: any) => {
    if (editDraft) {
      setEditDraft({ ...editDraft, [field]: value });
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6 border-b pb-4">
        <h2 className="text-2xl font-bold text-gray-800">Ledgers</h2>
        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Chart of Accounts Management</p>
      </div>

      <div className="grid grid-cols-1 gap-12">
        {sortedAccounts.map(account => {
          const accountLines = transactions.flatMap(t => 
            t.lines
              .filter(l => l.accountId === account.id)
              .map(l => ({ ...l, date: t.date, txId: t.id, method: t.method }))
          ).sort((a,b) => a.txId - b.txId);

          let currentBalance = 0;
          const isEditing = editingId === account.id;

          return (
            <div key={account.id} className="border rounded-lg shadow-sm overflow-hidden">
              {/* LEDGER HEADER */}
              <div className={`${isEditing ? 'bg-slate-900' : 'bg-slate-800'} text-white p-3 flex flex-wrap items-center justify-between gap-4 transition-colors`}>
                <div className="flex items-center gap-3 group">
                  {isEditing && editDraft ? (
                    <div className="flex flex-wrap items-center gap-3">
                      {/* Name Edit */}
                      <input
                        autoFocus
                        type="text"
                        value={editDraft.name}
                        onChange={(e) => updateDraft('name', e.target.value)}
                        onKeyDown={handleKeyDown}
                        className="bg-slate-800 text-white px-3 py-1.5 rounded border border-slate-600 outline-none focus:ring-2 focus:ring-emerald-500 font-bold"
                        placeholder="Account Name"
                      />

                      {/* Classification Edit */}
                      <select
                        value={editDraft.classification}
                        onChange={(e) => updateDraft('classification', e.target.value as AccountClassification)}
                        className="bg-slate-800 text-xs font-bold text-slate-300 border border-slate-600 px-2 py-1.5 rounded outline-none focus:ring-2 focus:ring-emerald-500"
                      >
                        {CLASSIFICATIONS.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>

                      {/* Statement Edit */}
                      <select
                        value={editDraft.financialStatement}
                        onChange={(e) => updateDraft('financialStatement', e.target.value as FinancialStatement)}
                        className="bg-slate-800 text-xs font-bold text-slate-300 border border-slate-600 px-2 py-1.5 rounded outline-none focus:ring-2 focus:ring-emerald-500"
                      >
                        {STATEMENTS.map(s => <option key={s} value={s}>{s}</option>)}
                      </select>

                      {/* Natural Balance Toggle */}
                      <div className="flex bg-slate-800 border border-slate-600 rounded overflow-hidden">
                        <button
                          onClick={() => updateDraft('naturalBalance', NaturalBalance.DEBIT)}
                          className={`px-3 py-1.5 text-[10px] font-black tracking-widest transition-colors ${editDraft.naturalBalance === NaturalBalance.DEBIT ? 'bg-emerald-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
                        >
                          DR
                        </button>
                        <button
                          onClick={() => updateDraft('naturalBalance', NaturalBalance.CREDIT)}
                          className={`px-3 py-1.5 text-[10px] font-black tracking-widest transition-colors ${editDraft.naturalBalance === NaturalBalance.CREDIT ? 'bg-amber-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
                        >
                          CR
                        </button>
                      </div>

                      {/* Actions */}
                      <div className="flex items-center gap-2 ml-4">
                        <button 
                          onClick={saveEdit} 
                          className="bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-1.5 rounded-lg text-xs font-bold shadow-lg"
                        >
                          Save Changes
                        </button>
                        <button 
                          onClick={cancelEditing} 
                          className="bg-slate-700 hover:bg-slate-600 text-slate-300 px-4 py-1.5 rounded-lg text-xs font-bold"
                        >
                          Cancel
                        </button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <h3 className="font-bold text-lg">{account.name}</h3>
                      <button 
                        onClick={() => startEditing(account)}
                        className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-white transition-all bg-white/10 p-1.5 rounded-md"
                        title="Edit Account Settings"
                      >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                      </button>
                    </>
                  )}
                </div>

                {!isEditing && (
                  <div className="flex gap-4 text-[10px] font-bold uppercase tracking-tighter">
                    <span className="opacity-70 bg-slate-700/50 px-2 py-1 rounded">Type: {account.classification}</span>
                    <span className="opacity-70 bg-slate-700/50 px-2 py-1 rounded">Statement: {account.financialStatement}</span>
                    <span className={`px-2 py-1 rounded border ${account.naturalBalance === NaturalBalance.DEBIT ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-amber-500/20 text-amber-400 border-amber-500/30'}`}>
                      Natural: {account.naturalBalance}
                    </span>
                  </div>
                )}
              </div>

              {/* LEDGER TABLE */}
              <table className="w-full text-xs text-left border-collapse">
                <thead className="bg-slate-100 border-b">
                  <tr>
                    <th className="p-2 border-r w-16 text-slate-500 uppercase font-black text-[9px]">Tx ID</th>
                    <th className="p-2 border-r w-24 text-slate-500 uppercase font-black text-[9px]">Date</th>
                    <th className="p-2 border-r text-slate-500 uppercase font-black text-[9px]">Method/Ref</th>
                    <th className="p-2 border-r text-right w-24 text-slate-500 uppercase font-black text-[9px]">Debit</th>
                    <th className="p-2 border-r text-right w-24 text-slate-500 uppercase font-black text-[9px]">Credit</th>
                    <th className="p-2 border-r text-right w-32 text-slate-500 uppercase font-black text-[9px]">Balance ({account.naturalBalance})</th>
                    <th className="p-2 text-slate-500 uppercase font-black text-[9px]">Description</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {accountLines.length === 0 ? (
                    <tr>
                      <td colSpan={7} className="p-4 text-center text-gray-400 italic font-medium">No activity for this account.</td>
                    </tr>
                  ) : (
                    accountLines.map((line, idx) => {
                      if (account.naturalBalance === NaturalBalance.DEBIT) {
                        currentBalance += (line.debit - line.credit);
                      } else {
                        currentBalance += (line.credit - line.debit);
                      }

                      return (
                        <tr key={`${line.txId}-${idx}`} className="hover:bg-slate-50 transition-colors">
                          <td className="p-2 border-r font-mono text-gray-500">{line.txId}</td>
                          <td className="p-2 border-r font-medium text-slate-700">{line.date}</td>
                          <td className="p-2 border-r text-slate-600 truncate max-w-[120px]">
                            {line.method || '-'}
                          </td>
                          <td className="p-2 border-r text-right font-mono font-bold text-emerald-600">
                            {line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                          </td>
                          <td className="p-2 border-r text-right font-mono font-bold text-amber-600">
                            {line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                          </td>
                          <td className={`p-2 border-r text-right font-mono font-black ${currentBalance < 0 ? 'text-red-500' : 'text-slate-900'} bg-slate-50/50`}>
                            {currentBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                          </td>
                          <td className="p-2 text-slate-500 italic truncate max-w-[200px]">{line.description}</td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
              {accountLines.length > 0 && (
                <div className="bg-slate-50 p-2 text-[10px] text-right text-slate-400 font-bold uppercase tracking-widest border-t">
                  Ending Balance: {currentBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Ledgers;

export enum NaturalBalance {
  DEBIT = 'DR',
  CREDIT = 'CR'
}

export enum FinancialStatement {
  BALANCE_SHEET = 'Balance Sheet',
  INCOME_STATEMENT = 'Income Statement'
}

export enum AccountClassification {
  CURRENT_ASSET = 'Current Asset',
  LONG_TERM_ASSET = 'Long-Term Asset',
  CURRENT_LIABILITY = 'Current Liability',
  LONG_TERM_LIABILITY = 'Long-Term Liability',
  EQUITY = 'Equity',
  REVENUE = 'Revenue',
  COGS = 'Cost of Goods Sold',
  OPERATING_EXPENSE = 'Operating Expenses',
  OTHER_INCOME_EXPENSE = 'Other Income (Expenses)'
}

export interface Account {
  id: string;
  name: string;
  naturalBalance: NaturalBalance;
  financialStatement: FinancialStatement;
  classification: AccountClassification;
  isArchived?: boolean; // New: prevents new transactions but preserves history
}

export interface JournalEntryLine {
  id: string;
  accountId: string;
  debit: number;
  credit: number;
  description: string;
}

export interface JournalEntry {
  id: number;
  date: string;
  method: string;
  lines: JournalEntryLine[];
}

export type TabType = 
  | 'Dashboard'
  | 'Transaction Recorder' 
  | 'General Journal' 
  | 'Ledgers' 
  | 'BS' 
  | 'IS' 
  | 'CF' 
  | 'Trial Balance'
  | 'Data Manager';

import React, { useState, useEffect, useCallback } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);
  const [retryTrigger, setRetryTrigger] = useState(0);

  // Auth Listener
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // Sync Logic
  useEffect(() => {
    if (!user) {
      setCloudError(null);
      return;
    }

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
      } catch (e) {
        console.error("Local storage parse error:", e);
      }
    }

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
          accounts: data.accounts,
          transactions: data.transactions
        }));
      } else {
        setDoc(userDocRef, { accounts: INITIAL_ACCOUNTS, transactions: [] })
          .catch(err => console.error("Initial seeding failed:", err));
      }
      setDataLoading(false);
    }, (error) => {
      setDataLoading(false);
      if (error.code === 'permission-denied') {
        setCloudError("Security Policy Violation: Access to your data was denied.");
      } else {
        setCloudError(`Cloud Sync Issue: ${error.message}`);
      }
    });

    return () => unsubscribe();
  }, [user, retryTrigger]);

  const saveToFirestore = async (newAccounts: Account[], newTransactions: JournalEntry[]) => {
    if (!user) return;
    localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
      accounts: newAccounts,
      transactions: newTransactions
    }));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        accounts: newAccounts,
        transactions: newTransactions,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Error saving to Firestore:", err);
      if (err.code === 'permission-denied') {
        setCloudError("Access Denied: Check production security rules.");
      }
    }
  };

  const handleRefreshConnection = () => {
    setCloudError(null);
    setDataLoading(true);
    setRetryTrigger(prev => prev + 1);
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => 
      acc.id === id ? { ...acc, ...updatedFields } : acc
    );
    setAccounts(updated);
    saveToFirestore(updated, transactions);
  };

  const deleteAccount = (id: string) => {
    const account = accounts.find(a => a.id === id);
    if (!account) return;

    // Check if account has any transaction data
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));

    if (hasData) {
      // Archive instead of delete to preserve financial history
      const updated = accounts.map(acc => 
        acc.id === id ? { ...acc, isArchived: true } : acc
      );
      setAccounts(updated);
      saveToFirestore(updated, transactions);
      alert(`${account.name} has historical data. It has been archived and hidden from pickers, but remains in reports.`);
    } else {
      // Hard delete if unused
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions);
      alert(`${account.name} was unused and has been permanently removed.`);
    }
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Are you sure you want to delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated);
    }
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const existingNames = new Set(accounts.map(a => a.name.toLowerCase()));
    const uniqueNew = newAccounts.filter(a => !existingNames.has(a.name.toLowerCase()));
    const updatedAccs = [...accounts, ...uniqueNew];
    const updatedTxs = [...transactions, ...newTransactions];

    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs);
    alert("Import successful!");
  };

  if (authLoading) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <div className="animate-pulse flex flex-col items-center gap-4">
          <div className="w-12 h-12 bg-emerald-500 rounded-lg"></div>
          <div className="h-4 w-32 bg-slate-800 rounded"></div>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Login />;
  }

  const tabs: TabType[] = [
    'Dashboard',
    'Transaction Recorder',
    'Ledgers',
    'General Journal',
    'BS',
    'IS',
    'CF',
    'Trial Balance',
    'Data Manager'
  ];

  return (
    <div className="min-h-screen flex flex-col">
      {/* Cloud Error Banner */}
      {cloudError && (
        <div className="bg-amber-600 text-white px-4 py-3 text-xs font-bold flex items-center justify-between shadow-xl sticky top-0 z-[60]">
          <div className="flex items-center gap-3">
            <div className="bg-white/20 p-1.5 rounded-full">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
            </div>
            <span>{cloudError}</span>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={handleRefreshConnection} className="bg-emerald-500 hover:bg-emerald-400 text-white px-4 py-1.5 rounded-lg transition-colors border border-emerald-400">Check Again</button>
            <a href="https://console.firebase.google.com" target="_blank" className="bg-white text-amber-700 hover:bg-slate-100 px-4 py-1.5 rounded-lg">Firebase Console</a>
          </div>
        </div>
      )}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"></path></svg>
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-xl font-bold tracking-tight">VISTA SHORE PRODUCTS, LLC</h1>
              <span className="flex items-center gap-1 bg-emerald-500/20 text-emerald-400 text-[8px] font-black px-1.5 py-0.5 rounded border border-emerald-500/30 uppercase tracking-tighter">
                <svg className="w-2.5 h-2.5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd"></path></svg>
                Secure
              </span>
            </div>
            <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-[0.2em]">Enterprise Resource Planning</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end border-r border-slate-700 pr-6">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter">Auth User</span>
            <span className="text-sm font-semibold">{user.displayName || user.email}</span>
          </div>
          <div className="flex gap-3">
            <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-2 px-6 rounded-lg text-sm shadow-md transition-all">+ Create Account</button>
            <button onClick={() => signOut(auth)} className="bg-slate-800 hover:bg-red-900 text-slate-300 hover:text-white font-bold py-2 px-4 rounded-lg text-sm border border-slate-700 transition-all">Logout</button>
          </div>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-6 py-4 text-sm font-semibold whitespace-nowrap transition-all border-b-4 ${
              activeTab === tab 
                ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' 
                : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
            }`}
          >
            {tab}
          </button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto">
        <div className="max-w-7xl mx-auto relative">
          {dataLoading && (
            <div className="absolute top-0 right-0 p-4 z-50">
              <span className="flex items-center gap-2 text-xs font-bold text-slate-400 animate-pulse">
                <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
                Syncing with Cloud...
              </span>
            </div>
          )}

          <div className="bg-white rounded-xl shadow-sm border p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && (
              <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} />
            )}
            {activeTab === 'Transaction Recorder' && (
              <TransactionRecorder 
                accounts={accounts} 
                onRecord={recordTransaction} 
                lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0}
              />
            )}
            {activeTab === 'General Journal' && (
              <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} />
            )}
            {activeTab === 'Ledgers' && (
              <Ledgers 
                transactions={transactions} 
                accounts={accounts} 
                onUpdateAccount={updateAccount}
                onDeleteAccount={deleteAccount}
              />
            )}
            {activeTab === 'BS' && (
              <BalanceSheet transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'IS' && (
              <IncomeStatement transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'CF' && (
              <CashFlowStatement transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'Trial Balance' && (
              <TrialBalance transactions={transactions} accounts={accounts} />
            )}
            {activeTab === 'Data Manager' && (
              <DataManager accounts={accounts} onImport={importData} />
            )}
          </div>
        </div>
      </main>

      {showAccountModal && (
        <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification } from '../types';
import { STATEMENTS, CLASSIFICATIONS } from '../constants';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onUpdateAccount: (id: string, updatedFields: Partial<Account>) => void;
  onDeleteAccount: (id: string) => void;
}

const Ledgers: React.FC<Props> = ({ transactions, accounts, onUpdateAccount, onDeleteAccount }) => {
  const sortedAccounts = [...accounts].sort((a,b) => {
    // Sort archived accounts to the bottom
    if (a.isArchived && !b.isArchived) return 1;
    if (!a.isArchived && b.isArchived) return -1;
    return a.name.localeCompare(b.name);
  });

  // Editing state
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState<Account | null>(null);

  const startEditing = (account: Account) => {
    setEditingId(account.id);
    setEditDraft({ ...account });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const saveEdit = () => {
    if (editingId && editDraft) {
      onUpdateAccount(editingId, {
        name: editDraft.name.trim(),
        classification: editDraft.classification,
        naturalBalance: editDraft.naturalBalance,
        financialStatement: editDraft.financialStatement
      });
      cancelEditing();
    }
  };

  const handleDeleteClick = (id: string) => {
    const account = accounts.find(a => a.id === id);
    if (!account) return;

    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));

    let confirmMsg = "";
    if (hasData) {
      confirmMsg = `⚠️ "${account.name}" has transaction history.\n\nDeleting this account will ARCHIVE it. It will be hidden from new transactions but preserved in all past reports to keep your books balanced. Proceed?`;
    } else {
      confirmMsg = `Are you sure you want to PERMANENTLY delete the unused account "${account.name}"?`;
    }

    if (window.confirm(confirmMsg)) {
      onDeleteAccount(id);
      cancelEditing();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') saveEdit();
    if (e.key === 'Escape') cancelEditing();
  };

  const updateDraft = (field: keyof Account, value: any) => {
    if (editDraft) {
      setEditDraft({ ...editDraft, [field]: value });
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6 border-b pb-4">
        <h2 className="text-2xl font-bold text-gray-800">Ledgers</h2>
        <div className="flex items-center gap-4">
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Master Audit File</p>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-12">
        {sortedAccounts.map(account => {
          const accountLines = transactions.flatMap(t => 
            t.lines
              .filter(l => l.accountId === account.id)
              .map(l => ({ ...l, date: t.date, txId: t.id, method: t.method }))
          ).sort((a,b) => a.txId - b.txId);

          let currentBalance = 0;
          const isEditing = editingId === account.id;

          return (
            <div key={account.id} className={`border rounded-lg shadow-sm overflow-hidden ${account.isArchived ? 'opacity-80 grayscale-[0.3]' : ''}`}>
              {/* LEDGER HEADER */}
              <div className={`${isEditing ? 'bg-slate-900' : 'bg-slate-800'} text-white p-3 flex flex-wrap items-center justify-between gap-4 transition-colors`}>
                <div className="flex items-center gap-3 group">
                  {isEditing && editDraft ? (
                    <div className="flex flex-wrap items-center gap-3">
                      <input
                        autoFocus
                        type="text"
                        value={editDraft.name}
                        onChange={(e) => updateDraft('name', e.target.value)}
                        onKeyDown={handleKeyDown}
                        className="bg-slate-800 text-white px-3 py-1.5 rounded border border-slate-600 outline-none focus:ring-2 focus:ring-emerald-500 font-bold"
                        placeholder="Account Name"
                      />

                      <select
                        value={editDraft.classification}
                        onChange={(e) => updateDraft('classification', e.target.value as AccountClassification)}
                        className="bg-slate-800 text-xs font-bold text-slate-300 border border-slate-600 px-2 py-1.5 rounded outline-none"
                      >
                        {CLASSIFICATIONS.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>

                      <div className="flex bg-slate-800 border border-slate-600 rounded overflow-hidden">
                        <button
                          onClick={() => updateDraft('naturalBalance', NaturalBalance.DEBIT)}
                          className={`px-3 py-1.5 text-[10px] font-black ${editDraft.naturalBalance === NaturalBalance.DEBIT ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}
                        >
                          DR
                        </button>
                        <button
                          onClick={() => updateDraft('naturalBalance', NaturalBalance.CREDIT)}
                          className={`px-3 py-1.5 text-[10px] font-black ${editDraft.naturalBalance === NaturalBalance.CREDIT ? 'bg-amber-600 text-white' : 'text-slate-500'}`}
                        >
                          CR
                        </button>
                      </div>

                      <div className="flex items-center gap-2 ml-4">
                        <button onClick={saveEdit} className="bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-1.5 rounded-lg text-xs font-bold shadow-lg">Save</button>
                        <button onClick={cancelEditing} className="bg-slate-700 hover:bg-slate-600 text-slate-300 px-4 py-1.5 rounded-lg text-xs font-bold">Cancel</button>
                        <div className="w-[1px] h-6 bg-slate-700 mx-1"></div>
                        <button 
                          onClick={() => handleDeleteClick(account.id)}
                          className="bg-red-900/40 hover:bg-red-600 text-red-300 hover:text-white p-1.5 rounded-lg transition-all"
                          title="Delete Account"
                        >
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                        </button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <h3 className={`font-bold text-lg ${account.isArchived ? 'text-slate-400' : ''}`}>
                        {account.name}
                        {account.isArchived && (
                          <span className="ml-3 text-[9px] bg-red-500/20 text-red-400 border border-red-500/30 px-1.5 py-0.5 rounded uppercase tracking-tighter align-middle">Archived</span>
                        )}
                      </h3>
                      {!account.isArchived && (
                        <button 
                          onClick={() => startEditing(account)}
                          className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-white transition-all bg-white/10 p-1.5 rounded-md"
                          title="Edit Account Settings"
                        >
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                        </button>
                      )}
                    </>
                  )}
                </div>

                {!isEditing && (
                  <div className="flex gap-4 text-[10px] font-bold uppercase tracking-tighter">
                    <span className="opacity-70 bg-slate-700/50 px-2 py-1 rounded">{account.classification}</span>
                    <span className={`px-2 py-1 rounded border ${account.naturalBalance === NaturalBalance.DEBIT ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-amber-500/20 text-amber-400 border-amber-500/30'}`}>
                      Natural: {account.naturalBalance}
                    </span>
                  </div>
                )}
              </div>

              <table className="w-full text-xs text-left border-collapse">
                <thead className="bg-slate-100 border-b">
                  <tr>
                    <th className="p-2 border-r w-16 text-slate-500 uppercase font-black text-[9px]">ID</th>
                    <th className="p-2 border-r w-24 text-slate-500 uppercase font-black text-[9px]">Date</th>
                    <th className="p-2 border-r text-slate-500 uppercase font-black text-[9px]">Method</th>
                    <th className="p-2 border-r text-right w-24 text-slate-500 uppercase font-black text-[9px]">Debit</th>
                    <th className="p-2 border-r text-right w-24 text-slate-500 uppercase font-black text-[9px]">Credit</th>
                    <th className="p-2 border-r text-right w-32 text-slate-500 uppercase font-black text-[9px]">Balance ({account.naturalBalance})</th>
                    <th className="p-2 text-slate-500 uppercase font-black text-[9px]">Memo</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {accountLines.length === 0 ? (
                    <tr>
                      <td colSpan={7} className="p-4 text-center text-gray-400 italic font-medium">No account activity recorded.</td>
                    </tr>
                  ) : (
                    accountLines.map((line, idx) => {
                      if (account.naturalBalance === NaturalBalance.DEBIT) {
                        currentBalance += (line.debit - line.credit);
                      } else {
                        currentBalance += (line.credit - line.debit);
                      }

                      return (
                        <tr key={`${line.txId}-${idx}`} className="hover:bg-slate-50 transition-colors">
                          <td className="p-2 border-r font-mono text-gray-400">{line.txId}</td>
                          <td className="p-2 border-r font-medium text-slate-700">{line.date}</td>
                          <td className="p-2 border-r text-slate-600 truncate max-w-[120px]">{line.method || '-'}</td>
                          <td className="p-2 border-r text-right font-mono font-bold text-emerald-600">
                            {line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                          </td>
                          <td className="p-2 border-r text-right font-mono font-bold text-amber-600">
                            {line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                          </td>
                          <td className={`p-2 border-r text-right font-mono font-black ${currentBalance < 0 ? 'text-red-500' : 'text-slate-900'} bg-slate-50/50`}>
                            {currentBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                          </td>
                          <td className="p-2 text-slate-500 italic truncate max-w-[200px]">{line.description}</td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Ledgers;

import React, { useState } from 'react';
import { Account, JournalEntry, JournalEntryLine } from '../types';

interface Props {
  accounts: Account[];
  onRecord: (entry: JournalEntry) => void;
  lastId: number;
}

const TransactionRecorder: React.FC<Props> = ({ accounts, onRecord, lastId }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [method, setMethod] = useState('');
  const [lines, setLines] = useState<JournalEntryLine[]>([
    { id: '1', accountId: '', debit: 0, credit: 0, description: '' },
    { id: '2', accountId: '', debit: 0, credit: 0, description: '' }
  ]);

  // Filter out archived accounts for new transactions
  const activeAccounts = accounts
    .filter(acc => !acc.isArchived)
    .sort((a,b) => a.name.localeCompare(b.name));

  const totalDebits = lines.reduce((sum, l) => sum + (l.debit || 0), 0);
  const totalCredits = lines.reduce((sum, l) => sum + (l.credit || 0), 0);
  const isBalanced = Math.abs(totalDebits - totalCredits) < 0.01 && totalDebits > 0;

  const addLine = () => {
    setLines([...lines, { id: Math.random().toString(), accountId: '', debit: 0, credit: 0, description: '' }]);
  };

  const removeLine = (id: string) => {
    if (lines.length > 2) {
      setLines(lines.filter(l => l.id !== id));
    }
  };

  const updateLine = (id: string, field: keyof JournalEntryLine, value: any) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: value } : l));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isBalanced) {
      alert("Debits must equal credits!");
      return;
    }

    const entry: JournalEntry = {
      id: lastId + 1,
      date,
      method,
      lines: lines.filter(l => l.accountId && (l.debit > 0 || l.credit > 0))
    };

    onRecord(entry);
    setMethod('');
    setLines([
      { id: '1', accountId: '', debit: 0, credit: 0, description: '' },
      { id: '2', accountId: '', debit: 0, credit: 0, description: '' }
    ]);
    alert("Transaction recorded successfully!");
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6 border-b pb-2">Record Journal Entry</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 bg-slate-50 p-4 rounded-lg border">
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Transaction ID</label>
            <input type="text" disabled value={lastId + 1} className="w-full bg-gray-100 border rounded px-3 py-2 text-gray-600" />
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Date</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)} 
              className="w-full border rounded px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none" 
              required
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Method / Card</label>
            <input 
              type="text" 
              value={method} 
              onChange={(e) => setMethod(e.target.value)} 
              placeholder="e.g. AmEx 1001, MC 6214"
              className="w-full border rounded px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none" 
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm border-collapse">
            <thead>
              <tr className="bg-slate-100 border-b">
                <th className="p-3 text-left font-semibold text-gray-600">Account</th>
                <th className="p-3 text-left font-semibold text-gray-600 w-32">Debit</th>
                <th className="p-3 text-left font-semibold text-gray-600 w-32">Credit</th>
                <th className="p-3 text-left font-semibold text-gray-600">Description</th>
                <th className="p-3 w-10"></th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {lines.map((line) => (
                <tr key={line.id} className="hover:bg-gray-50">
                  <td className="p-2">
                    <select
                      value={line.accountId}
                      onChange={(e) => updateLine(line.id, 'accountId', e.target.value)}
                      className="w-full border rounded px-2 py-1.5 focus:ring-2 focus:ring-emerald-500 outline-none"
                    >
                      <option value="">Select Account...</option>
                      {activeAccounts.map(acc => (
                        <option key={acc.id} value={acc.id}>{acc.name}</option>
                      ))}
                    </select>
                  </td>
                  <td className="p-2">
                    <input
                      type="number"
                      step="0.01"
                      value={line.debit || ''}
                      onChange={(e) => updateLine(line.id, 'debit', parseFloat(e.target.value) || 0)}
                      className="w-full border rounded px-2 py-1.5 text-right font-mono"
                      placeholder="0.00"
                    />
                  </td>
                  <td className="p-2">
                    <input
                      type="number"
                      step="0.01"
                      value={line.credit || ''}
                      onChange={(e) => updateLine(line.id, 'credit', parseFloat(e.target.value) || 0)}
                      className="w-full border rounded px-2 py-1.5 text-right font-mono"
                      placeholder="0.00"
                    />
                  </td>
                  <td className="p-2">
                    <input
                      type="text"
                      value={line.description}
                      onChange={(e) => updateLine(line.id, 'description', e.target.value)}
                      className="w-full border rounded px-2 py-1.5"
                      placeholder="Notes..."
                    />
                  </td>
                  <td className="p-2 text-center">
                    <button 
                      type="button"
                      onClick={() => removeLine(line.id)}
                      className="text-red-400 hover:text-red-600 p-1"
                      title="Remove Row"
                    >
                      ✕
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr className="bg-slate-50 font-bold border-t-2 border-slate-200">
                <td className="p-3 text-right">Totals:</td>
                <td className={`p-3 text-right font-mono ${totalDebits !== totalCredits ? 'text-red-500' : 'text-emerald-600'}`}>
                  {totalDebits.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td className={`p-3 text-right font-mono ${totalDebits !== totalCredits ? 'text-red-500' : 'text-emerald-600'}`}>
                  {totalCredits.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td colSpan={2} className="p-3">
                  {!isBalanced && totalDebits + totalCredits > 0 && (
                    <span className="text-xs text-red-500 font-medium">Out of balance by {(Math.abs(totalDebits - totalCredits)).toFixed(2)}</span>
                  )}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>

        <div className="flex justify-between items-center pt-4 border-t">
          <button 
            type="button" 
            onClick={addLine}
            className="text-emerald-600 font-semibold text-sm hover:underline"
          >
            + Add Row
          </button>

          <button 
            type="submit"
            disabled={!isBalanced}
            className={`px-8 py-3 rounded-lg font-bold shadow transition-all ${
              isBalanced 
                ? 'bg-emerald-600 text-white hover:bg-emerald-700 transform hover:-translate-y-0.5' 
                : 'bg-gray-300 text-gray-500 cursor-not-allowed'
            }`}
          >
            Record JE
          </button>
        </div>
      </form>
    </div>
  );
};

