                      <td className="p-2 text-slate-500 italic truncate max-w-[200px]">{line.description}</td>
                      <td className="p-2 text-center">
                        <button onClick={() => onDeleteTransaction(line.txId)} className="opacity-0 group-hover:opacity-100 text-red-300 hover:text-red-600 transition-all">✕</button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            <div className="bg-slate-50 p-2 text-[10px] text-right text-slate-400 font-bold uppercase tracking-widest border-t">Ending Balance: {runningBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}</div>
          </div>
        );
      })}
    </div>
  );
};

export default Ledgers;

import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  closedPeriods: string[]; // Added: only show these months
}

const BalanceSheet: React.FC<Props> = ({ transactions, accounts, closedPeriods }) => {
  const periods = useMemo(() => {
    return [...closedPeriods].sort((a,b) => a.localeCompare(b)); // Sort oldest to newest (A -> Z)
  }, [closedPeriods]);

  const getBalance = (accountId: string, upToPeriod?: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let balance = account.startingBalance || 0;
    transactions.forEach(tx => {
      if (upToPeriod) {
        const txDate = new Date(tx.date);
        const [year, month] = upToPeriod.split('-').map(Number);
        const lastDayOfPeriod = new Date(year, month, 0);
        if (txDate > lastDayOfPeriod) return;
      }

      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
          else balance += (l.credit - l.debit);
        }
      });
    });
    return balance;
  };

  const getNetIncome = (upToPeriod: string) => {
    const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
    let net = 0;
    isAccounts.forEach(acc => {
      const b = getBalance(acc.id, upToPeriod) - (acc.startingBalance || 0); // P&L starting balances are usually 0, but safety first
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) net += b; 
      else net -= b;
    });
    return net;
  };

  const bsAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.BALANCE_SHEET);

  const calculateTotal = (classification: AccountClassification, upToPeriod: string) => {
    return bsAccounts
      .filter(a => a.classification === classification)
      .reduce((sum, a) => sum + getBalance(a.id, upToPeriod), 0);
  };

  const renderCells = (id: string | AccountClassification, isClassification: boolean) => {
    return periods.map(p => {
      const val = isClassification ? calculateTotal(id as AccountClassification, p) : getBalance(id as string, p);
      return <td key={p} className="p-2 text-right font-mono text-xs border-r border-slate-100">{val.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>;
    });
  };

  const renderSection = (title: string, classification: AccountClassification) => {
    const filtered = bsAccounts.filter(a => a.classification === classification);
    return (
      <>
        <tr className="bg-slate-50"><td className="p-2 font-bold text-slate-800 uppercase text-[10px] tracking-widest border-r">{title}</td>{periods.map(p => <td key={p} className="bg-slate-50 border-r border-slate-100"></td>)}</tr>
        {filtered.map(acc => (
          <tr key={acc.id} className="border-b hover:bg-slate-50/50">
            <td className="p-2 pl-6 text-xs font-medium text-slate-600 border-r">{acc.name}</td>
            {renderCells(acc.id, false)}
          </tr>
        ))}
        <tr className="font-bold border-t border-slate-400 bg-slate-50/20"><td className="p-2 pl-4 text-xs italic border-r">Total {title}</td>{renderCells(classification, true)}</tr>
      </>
    );
  };

  return (
    <div className="w-full">
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold uppercase tracking-tight">Comparative Balance Sheet</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Closed Monthly Periods (Oldest to Newest)</p>
      </div>

      <div className="overflow-x-auto border rounded-xl shadow-sm">
        <table className="w-full border-collapse min-w-[600px]">
          <thead>
            <tr className="bg-slate-800 text-white">
              <th className="p-3 text-left w-64 border-r border-slate-700">Accounts</th>
              {periods.map(p => (
                <th key={p} className="p-3 text-right text-xs uppercase tracking-tighter border-r border-slate-700">
                  {new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            <tr className="bg-slate-200"><td colSpan={periods.length + 1} className="p-2 font-black text-slate-800 text-xs">ASSETS</td></tr>
            {renderSection("Current Assets", AccountClassification.CURRENT_ASSET)}
            {renderSection("Long-Term Assets", AccountClassification.LONG_TERM_ASSET)}
            <tr className="bg-slate-900 text-white font-bold">
              <td className="p-3 text-xs uppercase tracking-widest border-r border-slate-700">TOTAL ASSETS</td>
              {periods.map(p => {
                const total = calculateTotal(AccountClassification.CURRENT_ASSET, p) + calculateTotal(AccountClassification.LONG_TERM_ASSET, p);
                return <td key={p} className="p-3 text-right font-mono text-sm border-r border-slate-700">${total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>
            <tr className="h-8"></tr>
            <tr className="bg-slate-200"><td colSpan={periods.length + 1} className="p-2 font-black text-slate-800 text-xs">LIABILITIES & EQUITY</td></tr>
            {renderSection("Current Liabilities", AccountClassification.CURRENT_LIABILITY)}
            {renderSection("Long-Term Liabilities", AccountClassification.LONG_TERM_LIABILITY)}
            {renderSection("Equity", AccountClassification.EQUITY)}
            <tr className="border-b">
              <td className="p-2 pl-6 text-xs text-slate-600 italic border-r">Retained Earnings (Cumulative Net Income)</td>
              {periods.map(p => <td key={p} className="p-2 text-right font-mono text-xs border-r border-slate-100">{getNetIncome(p).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>)}
            </tr>
            <tr className="bg-slate-900 text-white font-bold">
              <td className="p-3 text-xs uppercase tracking-widest border-r border-slate-700">TOTAL LIABILITIES & EQUITY</td>
              {periods.map(p => {
                const totalL = calculateTotal(AccountClassification.CURRENT_LIABILITY, p) + calculateTotal(AccountClassification.LONG_TERM_LIABILITY, p);
                const totalE = calculateTotal(AccountClassification.EQUITY, p) + getNetIncome(p);
                return <td key={p} className="p-3 text-right font-mono text-sm border-r border-slate-700">${(totalL + totalE).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>
          </tbody>
        </table>
      </div>
      {periods.length === 0 && (
        <div className="p-20 text-center text-slate-400 italic bg-slate-50 rounded-xl border-2 border-dashed">
          No months have been "Closed" yet. Use the Data Manager tab to dictate which periods appear in this statement.
        </div>
      )}
    </div>
  );
};

