import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  closedPeriods: string[];
}

const IncomeStatement: React.FC<Props> = ({ transactions, accounts, closedPeriods }) => {
  const periods = useMemo(() => {
    return [...closedPeriods].sort((a,b) => a.localeCompare(b));
  }, [closedPeriods]);

  const getBalance = (accountId: string, period?: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let balance = 0;
    transactions.forEach(tx => {
      if (period) {
        const txPeriod = `${new Date(tx.date).getFullYear()}-${String(new Date(tx.date).getMonth() + 1).padStart(2, '0')}`;
        if (txPeriod !== period) return;
      }

      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
          else balance += (l.credit - l.debit);
        }
      });
    });
    return balance;
  };

  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);

  const calculateTotal = (classification: AccountClassification, period?: string) => {
    return isAccounts
      .filter(a => a.classification === classification)
      .reduce((sum, a) => sum + getBalance(a.id, period), 0);
  };

  const renderCells = (id: string | AccountClassification, isClassification: boolean) => {
    return periods.map(p => {
      const val = isClassification ? calculateTotal(id as AccountClassification, p) : getBalance(id as string, p);
      return <td key={p} className={`p-2 text-right font-mono text-xs ${val < 0 ? 'text-red-600' : ''}`}>{val.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>;
    });
  };

  const renderNetIncomeCells = () => {
    return periods.map(p => {
      const rev = calculateTotal(AccountClassification.REVENUE, p);
      const cogs = calculateTotal(AccountClassification.COGS, p);
      const op = calculateTotal(AccountClassification.OPERATING_EXPENSE, p);
      const other = calculateTotal(AccountClassification.OTHER_INCOME_EXPENSE, p);
      const net = (rev - cogs) - op + other;
      return <td key={p} className={`p-2 text-right font-mono font-bold text-sm ${net < 0 ? 'text-red-400' : 'text-emerald-400'}`}>{net.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>;
    });
  };

  const renderSection = (title: string, classification: AccountClassification) => {
    const filtered = isAccounts.filter(a => a.classification === classification);
    return (
      <>
        <tr className="bg-slate-50"><td colSpan={periods.length + 1} className="p-2 font-bold text-slate-800 uppercase text-[10px] tracking-widest">{title}</td></tr>
        {filtered.map(acc => (
          <tr key={acc.id} className="border-b hover:bg-slate-50">
            <td className="p-2 pl-6 text-xs font-medium text-slate-600">{acc.name}</td>
            {renderCells(acc.id, false)}
          </tr>
        ))}
        <tr className="font-bold border-t border-slate-400 bg-slate-50/10"><td className="p-2 pl-4 text-xs italic">Total {title}</td>{renderCells(classification, true)}</tr>
      </>
    );
  };

  return (
    <div className="w-full">
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold uppercase tracking-tight">Comparative Income Statement</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Closed Monthly Performance Periods</p>
      </div>

      <div className="overflow-x-auto border rounded-xl shadow-sm">
        <table className="w-full border-collapse min-w-[600px]">
          <thead>
            <tr className="bg-slate-800 text-white">
              <th className="p-3 text-left w-64 border-r border-slate-700">Accounts</th>
              {periods.map(p => (
                <th key={p} className="p-3 text-right text-xs uppercase tracking-tighter border-r border-slate-700">
                  {new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {renderSection("Revenue", AccountClassification.REVENUE)}
            {renderSection("Cost of Goods Sold", AccountClassification.COGS)}
            {renderSection("Operating Expenses", AccountClassification.OPERATING_EXPENSE)}
            {renderSection("Other Income / (Expenses)", AccountClassification.OTHER_INCOME_EXPENSE)}
            <tr className="h-8"></tr>
            <tr className="bg-slate-900 text-white">
              <td className="p-3 font-black text-xs uppercase tracking-widest">PERIOD NET INCOME</td>
              {renderNetIncomeCells()}
            </tr>
          </tbody>
        </table>
      </div>
      {periods.length === 0 && (
        <div className="p-20 text-center text-slate-400 italic bg-slate-50 rounded-xl border-2 border-dashed">
          No months have been "Closed" yet. Use the Data Manager tab to dictate which periods appear in this statement.
        </div>
      )}
    </div>
  );
};

