import React, { useRef, useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification } from '../types';

interface Props {
  accounts: Account[];
  transactions: JournalEntry[];
  onImport: (transactions: JournalEntry[], accounts: Account[]) => void;
  closedPeriods: string[];
  onTogglePeriod: (period: string) => void;
}

const DataManager: React.FC<Props> = ({ accounts, transactions, onImport, closedPeriods, onTogglePeriod }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const availablePeriods = useMemo(() => {
    const periods = new Set<string>();
    transactions.forEach(t => {
      const date = new Date(t.date);
      if (!isNaN(date.getTime())) {
        periods.add(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`);
      }
    });
    return Array.from(periods).sort((a,b) => b.localeCompare(a));
  }, [transactions]);

  const downloadTemplate = () => {
    const headers = "Date,Method,Account Name,Debit,Credit,Description,TransactionID\n";
    const example = "2023-10-25,AmEx,Cash,150.00,0,Starting Balance,1001\n2023-10-25,AmEx,Revenue,0,150.00,Sales,1001";
    const blob = new Blob([headers + example], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'vista_import_template.csv';
    a.click();
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => parseCSV(event.target?.result as string);
    reader.readAsText(file);
  };

  const parseCSV = (csv: string) => {
    const lines = csv.split('\n');
    const txMap: Record<number, JournalEntry> = {};
    const newAccounts: Account[] = [];

    for (let i = 1; i < lines.length; i++) {
      if (!lines[i].trim()) continue;
      const values = lines[i].split(',').map(v => v.trim());
      const [date, method, accName, debitVal, creditVal, desc, txIdVal] = values;
      const debit = parseFloat(debitVal) || 0;
      const credit = parseFloat(creditVal) || 0;
      const txId = parseInt(txIdVal) || Math.floor(Math.random() * 10000);

      let account = accounts.find(a => a.name.toLowerCase() === accName.toLowerCase()) || newAccounts.find(a => a.name.toLowerCase() === accName.toLowerCase());
      if (!account) {
        account = {
          id: Math.random().toString(),
          name: accName,
          naturalBalance: (accName.toLowerCase().includes('revenue') || accName.toLowerCase().includes('payable')) ? NaturalBalance.CREDIT : NaturalBalance.DEBIT,
          financialStatement: (accName.toLowerCase().includes('revenue') || accName.toLowerCase().includes('expense')) ? FinancialStatement.INCOME_STATEMENT : FinancialStatement.BALANCE_SHEET,
          classification: accName.toLowerCase().includes('revenue') ? AccountClassification.REVENUE : AccountClassification.CURRENT_ASSET,
          startingBalance: 0
        };
        newAccounts.push(account);
      }

      if (!txMap[txId]) txMap[txId] = { id: txId, date, method, lines: [] };
      txMap[txId].lines.push({ id: Math.random().toString(), accountId: account.id, debit, credit, description: desc });
    }
    onImport(Object.values(txMap), newAccounts);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12">
      <section className="bg-emerald-50 border-2 border-emerald-100 p-8 rounded-2xl flex flex-col md:flex-row items-center gap-8">
        <div className="flex-1 space-y-4">
          <h2 className="text-2xl font-black text-emerald-900">Historical Import</h2>
          <p className="text-emerald-700 text-sm leading-relaxed">Import bulk data from Excel. Use Transaction IDs to group lines together.</p>
          <div className="flex gap-4">
            <button onClick={downloadTemplate} className="bg-white text-emerald-600 border border-emerald-200 px-6 py-2 rounded-lg font-bold hover:bg-emerald-100 shadow-sm transition-all">Get Template</button>
            <button onClick={() => fileInputRef.current?.click()} className="bg-emerald-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-emerald-700 shadow-md">Upload CSV</button>
            <input type="file" ref={fileInputRef} className="hidden" accept=".csv" onChange={handleFileUpload} />
          </div>
        </div>
      </section>

      <section className="space-y-4">
        <div className="flex justify-between items-end border-b pb-2">
          <div>
            <h3 className="text-lg font-bold text-slate-800">Period Manager (Month-End Close)</h3>
            <p className="text-xs text-slate-500">Toggle months to include them in Comparative Balance Sheet and Income Statements.</p>
          </div>
          <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-2 py-1 rounded border border-emerald-200 uppercase tracking-tighter">{closedPeriods.length} Periods Closed</span>
        </div>

        {availablePeriods.length === 0 ? (
          <div className="p-8 text-center text-slate-400 italic bg-slate-50 rounded-xl border-2 border-dashed">Record some transactions to see available months for closing.</div>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
            {availablePeriods.map(p => {
              const isClosed = closedPeriods.includes(p);
              const dateObj = new Date(p + "-02");
              return (
                <button
                  key={p}
                  onClick={() => onTogglePeriod(p)}
                  className={`p-4 rounded-xl border-2 text-left transition-all ${isClosed ? 'bg-slate-800 border-slate-900 text-white shadow-lg shadow-slate-200' : 'bg-white border-slate-100 text-slate-600 hover:border-emerald-200'}`}
                >
                  <div className="text-[10px] font-black uppercase opacity-60">{dateObj.getFullYear()}</div>
                  <div className="font-bold text-lg">{dateObj.toLocaleString('default', { month: 'long' })}</div>
                  <div className={`mt-2 text-[9px] font-black uppercase tracking-widest ${isClosed ? 'text-emerald-400' : 'text-slate-300'}`}>
                    {isClosed ? '● Closed' : '○ Open'}
                  </div>
                </button>
              );
            })}
          </div>
        )}
      </section>
    </div>
  );
};

export default DataManager;

export enum NaturalBalance {
  DEBIT = 'DR',
  CREDIT = 'CR'
}

export enum FinancialStatement {
  BALANCE_SHEET = 'Balance Sheet',
  INCOME_STATEMENT = 'Income Statement'
}

export enum AccountClassification {
  CURRENT_ASSET = 'Current Asset',
  LONG_TERM_ASSET = 'Long-Term Asset',
  CURRENT_LIABILITY = 'Current Liability',
  LONG_TERM_LIABILITY = 'Long-Term Liability',
  EQUITY = 'Equity',
  REVENUE = 'Revenue',
  COGS = 'Cost of Goods Sold',
  OPERATING_EXPENSE = 'Operating Expenses',
  OTHER_INCOME_EXPENSE = 'Other Income (Expenses)'
}

export interface Account {
  id: string;
  name: string;
  naturalBalance: NaturalBalance;
  financialStatement: FinancialStatement;
  classification: AccountClassification;
  startingBalance: number; // Balance forward anchor
  isArchived?: boolean;
}

export interface JournalEntryLine {
  id: string;
  accountId: string;
  debit: number;
  credit: number;
  description: string;
}

export interface JournalEntry {
  id: number;
  date: string;
  method: string;
  lines: JournalEntryLine[];
}

export type TabType = 
  | 'Dashboard'
  | 'Transaction Recorder' 
  | 'General Journal' 
  | 'Ledgers' 
  | 'BS' 
  | 'IS' 
  | 'CF' 
  | 'Trial Balance'
  | 'Data Manager';

import React, { useState } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification } from '../types';
import { CLASSIFICATIONS } from '../constants';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onUpdateAccount: (id: string, updatedFields: Partial<Account>) => void;
  onDeleteAccount: (id: string) => void;
  onDeleteTransaction: (id: number) => void;
}

const Ledgers: React.FC<Props> = ({ transactions, accounts = [], onUpdateAccount, onDeleteAccount, onDeleteTransaction }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState<Account | null>(null);

  const sortedAccounts = [...accounts].sort((a, b) => {
    if (a.isArchived && !b.isArchived) return 1;
    if (!a.isArchived && b.isArchived) return -1;
    return a.name.localeCompare(b.name);
  });

  const startEditing = (account: Account) => {
    setEditingId(account.id);
    setEditDraft({ ...account });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const saveEdit = () => {
    if (editingId && editDraft) {
      onUpdateAccount(editingId, {
        name: editDraft.name.trim(),
        classification: editDraft.classification,
        naturalBalance: editDraft.naturalBalance,
        financialStatement: editDraft.financialStatement,
        startingBalance: Number(editDraft.startingBalance) || 0
      });
      cancelEditing();
    }
  };

  const updateDraft = (field: keyof Account, value: any) => {
    if (editDraft) setEditDraft({ ...editDraft, [field]: value });
  };

  return (
    <div className="space-y-10">
      <div className="flex justify-between items-center border-b pb-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Account Ledgers</h2>
          <p className="text-xs text-slate-500 mt-1 font-medium">Manage starting balances and individual entries.</p>
        </div>
        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Double-Entry Audit View</div>
      </div>

      {sortedAccounts.map(account => {
        // Safety check for starting balance
        const startBal = Number(account.startingBalance) || 0;

        const accountLines = (transactions || []).flatMap(t => 
          t.lines
            .filter(l => l.accountId === account.id)
            .map(l => ({ ...l, date: t.date, txId: t.id, method: t.method }))
        ).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

        let runningBalance = startBal;
        const isEditing = editingId === account.id;

        return (
          <div key={account.id} className={`border rounded-xl shadow-sm overflow-hidden ${account.isArchived ? 'opacity-50 grayscale' : ''}`}>
            {/* Header / Edit Controls */}
            <div className={`${isEditing ? 'bg-slate-900' : 'bg-slate-800'} text-white p-4 flex flex-wrap items-center justify-between gap-4 transition-colors`}>
              <div className="flex items-center gap-4 group">
                {isEditing && editDraft ? (
                  <div className="flex flex-wrap items-center gap-3">
                    <div className="flex flex-col">
                      <label className="text-[9px] text-slate-400 font-black uppercase">Name</label>
                      <input type="text" value={editDraft.name} onChange={(e) => updateDraft('name', e.target.value)} className="bg-slate-800 text-white px-3 py-1.5 rounded border border-slate-600 text-sm font-bold w-48" />
                    </div>
                    <div className="flex flex-col">
                      <label className="text-[9px] text-slate-400 font-black uppercase">Start Balance (Forward)</label>
                      <input type="number" step="0.01" value={editDraft.startingBalance} onChange={(e) => updateDraft('startingBalance', e.target.value)} className="bg-slate-800 text-white px-2 py-1.5 rounded border border-slate-600 text-sm font-mono w-32" />
                    </div>
                    <div className="flex flex-col">
                      <label className="text-[9px] text-slate-400 font-black uppercase">Type</label>
                      <select value={editDraft.classification} onChange={(e) => updateDraft('classification', e.target.value as AccountClassification)} className="bg-slate-800 text-xs font-bold border border-slate-600 px-2 py-1.5 rounded h-[34px] mt-[2px]">
                        {CLASSIFICATIONS.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                    <div className="flex gap-2 ml-4 self-end pb-1">
                      <button onClick={saveEdit} className="bg-emerald-600 hover:bg-emerald-500 px-4 py-1.5 rounded text-xs font-bold shadow-lg transition-all">Save</button>
                      <button onClick={cancelEditing} className="bg-slate-700 hover:bg-slate-600 px-4 py-1.5 rounded text-xs font-bold transition-all">Cancel</button>
                    </div>
                  </div>
                ) : (
                  <>
                    <h3 className="font-bold text-lg">{account.name}</h3>
                    <button onClick={() => startEditing(account)} className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-white transition-all bg-white/10 p-1.5 rounded-md">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" strokeWidth="2"></path></svg>
                    </button>
                  </>
                )}
              </div>

              {!isEditing && (
                <div className="flex items-center gap-4 text-[10px] font-bold uppercase tracking-tighter">
                  <div className="flex flex-col items-end">
                    <span className="opacity-50">Starting Balance</span>
                    <span className="text-sm font-mono">${startBal.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
                  </div>
                  <div className={`px-2 py-2 rounded border ${account.naturalBalance === NaturalBalance.DEBIT ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-amber-500/20 text-amber-400 border-amber-500/30'}`}>
                    {account.naturalBalance}
                  </div>
                </div>
              )}
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-xs text-left border-collapse">
                <thead className="bg-slate-100 border-b">
                  <tr>
                    <th className="p-3 border-r w-16 text-slate-500 font-black uppercase text-[9px]">TX ID</th>
                    <th className="p-3 border-r w-24 text-slate-500 font-black uppercase text-[9px]">Date</th>
                    <th className="p-3 border-r text-slate-500 font-black uppercase text-[9px]">Reference</th>
                    <th className="p-3 border-r text-right w-28 text-slate-500 font-black uppercase text-[9px]">Debit</th>
                    <th className="p-3 border-r text-right w-28 text-slate-500 font-black uppercase text-[9px]">Credit</th>
                    <th className="p-3 border-r text-right w-36 text-slate-500 font-black uppercase text-[9px]">Balance</th>
                    <th className="p-3 text-slate-500 font-black uppercase text-[9px]">Memo</th>
                    <th className="p-3 w-10"></th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {/* The Balance Forward Row */}
                  <tr className="bg-slate-50/50 italic">
                    <td className="p-3 border-r text-slate-300 font-mono">-</td>
                    <td className="p-3 border-r text-slate-400">Opening</td>
                    <td className="p-3 border-r text-slate-400 uppercase text-[9px] font-bold tracking-widest">Balance Forward</td>
                    <td className="p-3 border-r text-right font-mono text-slate-300">-</td>
                    <td className="p-3 border-r text-right font-mono text-slate-300">-</td>
                    <td className="p-3 border-r text-right font-mono font-black text-slate-400 bg-slate-100/30">
                      {startBal.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>
                    <td colSpan={2} className="p-3 text-slate-400">Initial setup balance</td>
                  </tr>

                  {accountLines.length === 0 && (
                    <tr>
                      <td colSpan={8} className="p-6 text-center text-slate-400 italic font-medium">No transactions recorded for this period.</td>
                    </tr>
                  )}

                  {accountLines.map((line, idx) => {
                    const netChange = account.naturalBalance === NaturalBalance.DEBIT 
                      ? (line.debit - line.credit) 
                      : (line.credit - line.debit);
                    runningBalance += netChange;

                    return (
                      <tr key={`${line.txId}-${idx}`} className="group hover:bg-slate-50 transition-colors">
                        <td className="p-3 border-r font-mono text-slate-400">{line.txId}</td>
                        <td className="p-3 border-r font-medium text-slate-700">{line.date}</td>
                        <td className="p-3 border-r text-slate-600 truncate max-w-[120px]">{line.method || '-'}</td>
                        <td className="p-3 border-r text-right font-mono font-bold text-emerald-600">
                          {line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                        <td className="p-3 border-r text-right font-mono font-bold text-amber-600">
                          {line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}
                        </td>
                        <td className={`p-3 border-r text-right font-mono font-black bg-slate-50/50 ${runningBalance < 0 ? 'text-red-500' : 'text-slate-900'}`}>
                          {runningBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                        </td>
                        <td className="p-3 text-slate-500 italic truncate max-w-[200px]">{line.description}</td>
                        <td className="p-3 text-center">
                          <button 
                            onClick={() => {
                              if(window.confirm(`Delete transaction #${line.txId} from ledgers?`)) {
                                onDeleteTransaction(line.txId);
                              }
                            }} 
                            className="opacity-0 group-hover:opacity-100 text-red-300 hover:text-red-600 transition-all text-lg font-bold"
                            title="Delete Transaction"
                          >
                            ✕
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            <div className="bg-slate-100/50 p-3 text-[10px] text-right text-slate-500 font-bold uppercase tracking-widest border-t flex justify-end gap-4">
               <span>Total Activity: {(runningBalance - startBal).toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
               <span className="text-slate-900">Current Adjusted Balance: {runningBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
};

