import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  closedPeriods: string[];
}

const IncomeStatement: React.FC<Props> = ({ transactions = [], accounts = [], closedPeriods = [] }) => {
  const sortedPeriods = useMemo(() => {
    return [...closedPeriods].sort((a, b) => a.localeCompare(b));
  }, [closedPeriods]);

  const getMonthlyActivity = (accountId: string, period: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let activity = 0;
    const [year, month] = period.split('-').map(Number);

    transactions.forEach(tx => {
      const txDate = new Date(tx.date);
      if (txDate.getFullYear() === year && (txDate.getMonth() + 1) === month) {
        tx.lines.forEach(l => {
          if (l.accountId === accountId) {
            if (account.naturalBalance === NaturalBalance.DEBIT) activity += (l.debit - l.credit);
            else activity += (l.credit - l.debit);
          }
        });
      }
    });
    return activity;
  };

  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);

  const calculateMonthlyNet = (period: string) => {
    let rev = 0;
    let exp = 0;
    isAccounts.forEach(acc => {
      const act = getMonthlyActivity(acc.id, period);
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
        rev += act;
      } else {
        exp += act;
      }
    });
    return rev - exp;
  };

  if (sortedPeriods.length === 0) {
    return (
      <div className="p-20 text-center text-slate-400 italic bg-slate-50 rounded-xl border-2 border-dashed border-slate-200">
        <p className="text-lg font-semibold mb-2 text-slate-600">Comparative Income Statement Ready</p>
        <p>Close your first month in the Data Manager tab to begin comparative reporting.</p>
      </div>
    );
  }

  return (
    <div className="w-full">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-900">Income Performance Report</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">Monthly Revenue & Expense Analysis</p>
      </div>

      <div className="overflow-x-auto border rounded-2xl shadow-xl">
        <table className="w-full border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-900 text-white">
              <th className="p-4 text-left w-72 border-r border-slate-800">Income Category</th>
              {sortedPeriods.map(p => (
                <th key={p} className="p-4 text-right text-xs uppercase font-black tracking-widest border-r border-slate-800">
                  {new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {[
              { title: "Revenue", type: AccountClassification.REVENUE, color: "text-emerald-700" },
              { title: "Cost of Goods Sold", type: AccountClassification.COGS, color: "text-amber-700" },
              { title: "Operating Expenses", type: AccountClassification.OPERATING_EXPENSE, color: "text-slate-700" },
              { title: "Other Income / (Exp)", type: AccountClassification.OTHER_INCOME_EXPENSE, color: "text-indigo-700" }
            ].map(section => (
              <React.Fragment key={section.title}>
                <tr className="bg-slate-100/80 border-t border-slate-200">
                  <td className="p-2.5 font-black text-slate-900 text-[10px] tracking-widest uppercase">{section.title}</td>
                  {sortedPeriods.map(p => <td key={p} className="p-2 border-r border-slate-200 bg-slate-100/20"></td>)}
                </tr>
                {isAccounts.filter(a => a.classification === section.type).map(acc => (
                  <tr key={acc.id} className="border-b hover:bg-slate-50/50 transition-colors">
                    <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                    {sortedPeriods.map(p => (
                      <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                        {getMonthlyActivity(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                ))}
              </React.Fragment>
            ))}

            <tr className="h-10"></tr>
            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900 shadow-lg">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">NET MONTHLY INCOME</td>
              {sortedPeriods.map(p => {
                const net = calculateMonthlyNet(p);
                return (
                  <td key={p} className={`p-4 text-right font-mono text-sm border-r border-slate-700 ${net < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                    ${net.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                );
              })}
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default IncomeStatement;

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);
  const [retryTrigger, setRetryTrigger] = useState(0);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
      } catch (e) {}
    }

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
        localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
          accounts: data.accounts,
          transactions: data.transactions,
          closedPeriods: data.closedPeriods || []
        }));
      } else {
        setDoc(userDocRef, { accounts: INITIAL_ACCOUNTS, transactions: [], closedPeriods: [] })
          .catch(err => console.error("Seeding failed:", err));
      }
      setDataLoading(false);
    }, (error) => {
      setDataLoading(false);
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user, retryTrigger]);

  const saveToFirestore = async (newAccs: Account[], newTxs: JournalEntry[], newPeriods: string[]) => {
    if (!user) return;
    localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods
    }));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        accounts: newAccs,
        transactions: newTxs,
        closedPeriods: newPeriods,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Save error:", err);
    }
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods);
    }
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Permanently delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated, closedPeriods);
    }
  };

  const togglePeriod = (period: string) => {
    const updated = closedPeriods.includes(period) 
      ? closedPeriods.filter(p => p !== period)
      : [...closedPeriods, period];
    setClosedPeriods(updated);
    saveToFirestore(accounts, transactions, updated);
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const existingNames = new Set(accounts.map(a => a.name.toLowerCase()));
    const uniqueNew = newAccounts.filter(a => !existingNames.has(a.name.toLowerCase()));
    const updatedAccs = [...accounts, ...uniqueNew];
    const updatedTxs = [...transactions, ...newTransactions];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <h1 className="text-xl font-bold">VISTA SHORE</h1>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} closedPeriods={closedPeriods} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} closedPeriods={closedPeriods} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={importData} closedPeriods={closedPeriods} onTogglePeriod={togglePeriod} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { JournalEntry, Account, JournalEntryLine } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onDelete: (id: number) => void;
  onUpdate: (entry: JournalEntry) => void;
}

const GeneralJournal: React.FC<Props> = ({ transactions, accounts, onDelete, onUpdate }) => {
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editDraft, setEditDraft] = useState<JournalEntry | null>(null);

  const accountMap = new Map<string, Account>(accounts.map(a => [a.id, a]));
  const activeAccounts = accounts.filter(a => !a.isArchived).sort((a,b) => a.name.localeCompare(b.name));
  const sortedTransactions = [...transactions].sort((a, b) => b.id - a.id);

  const startEditing = (entry: JournalEntry) => {
    setEditingId(entry.id);
    setEditDraft(JSON.parse(JSON.stringify(entry))); // Deep copy
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const updateDraftLine = (lineId: string, field: keyof JournalEntryLine, value: any) => {
    if (!editDraft) return;
    const updatedLines = editDraft.lines.map(l => l.id === lineId ? { ...l, [field]: value } : l);
    setEditDraft({ ...editDraft, lines: updatedLines });
  };

  const handleSave = () => {
    if (!editDraft) return;

    // Validate balance
    const totalDr = editDraft.lines.reduce((sum, l) => sum + (Number(l.debit) || 0), 0);
    const totalCr = editDraft.lines.reduce((sum, l) => sum + (Number(l.credit) || 0), 0);

    if (Math.abs(totalDr - totalCr) > 0.01) {
      alert(`Entry must be balanced! Difference: $${Math.abs(totalDr - totalCr).toFixed(2)}`);
      return;
    }

    onUpdate(editDraft);
    cancelEditing();
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6 border-b pb-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">General Journal</h2>
          <p className="text-xs text-slate-500 mt-1">Audit trail of all recorded transactions.</p>
        </div>
        <div className="text-xs font-bold text-slate-400 uppercase tracking-widest">
          {transactions.length} Total Entries
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b">
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider w-16">ID</th>
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider w-32">Date</th>
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider">Account</th>
              <th className="p-4 text-right font-bold text-slate-500 uppercase tracking-wider w-32">Debit</th>
              <th className="p-4 text-right font-bold text-slate-500 uppercase tracking-wider w-32">Credit</th>
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider">Memo / Ref</th>
              <th className="p-4 w-24"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sortedTransactions.length === 0 && (
              <tr>
                <td colSpan={7} className="p-12 text-center text-slate-400 italic font-medium">No recorded journal entries found.</td>
              </tr>
            )}
            {sortedTransactions.map((entry) => {
              const isEditing = editingId === entry.id;
              const displayEntry = isEditing && editDraft ? editDraft : entry;

              return (
                <React.Fragment key={entry.id}>
                  {displayEntry.lines.map((line, idx) => {
                    const account = accountMap.get(line.accountId);
                    return (
                      <tr key={line.id} className={`group ${idx === 0 ? 'bg-slate-50/30' : 'bg-white'} ${isEditing ? 'bg-emerald-50/20' : 'hover:bg-emerald-50/30'} transition-colors`}>
                        <td className="p-4 align-top font-mono text-xs text-slate-400">
                          {idx === 0 ? entry.id : ''}
                        </td>
                        <td className="p-4 align-top text-slate-600 font-medium whitespace-nowrap">
                          {idx === 0 ? (
                            isEditing ? (
                              <input 
                                type="date" 
                                value={displayEntry.date} 
                                onChange={(e) => setEditDraft({...editDraft!, date: e.target.value})}
                                className="border rounded px-2 py-1 text-xs w-full bg-white"
                              />
                            ) : entry.date
                          ) : ''}
                        </td>
                        <td className={`p-4 font-semibold ${line.credit > 0 ? 'pl-12 text-slate-700' : 'text-slate-900'}`}>
                          {isEditing ? (
                            <select
                              value={line.accountId}
                              onChange={(e) => updateDraftLine(line.id, 'accountId', e.target.value)}
                              className="w-full border rounded px-2 py-1 text-xs font-semibold bg-white outline-none focus:ring-1 focus:ring-emerald-500"
                            >
                              <option value="">Select Account...</option>
                              {activeAccounts.map(acc => (
                                <option key={acc.id} value={acc.id}>{acc.name}</option>
                              ))}
                            </select>
                          ) : (
                            account?.name || 'Unknown Account'
                          )}
                        </td>
                        <td className="p-4 text-right font-mono font-bold text-emerald-700">
                          {isEditing ? (
                            <input 
                              type="number" 
                              step="0.01"
                              value={line.debit || ''} 
                              onChange={(e) => updateDraftLine(line.id, 'debit', parseFloat(e.target.value) || 0)}
                              className="border rounded px-2 py-1 text-xs w-full text-right bg-white"
                            />
                          ) : (
                            line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'
                          )}
                        </td>
                        <td className="p-4 text-right font-mono font-bold text-amber-700">
                          {isEditing ? (
                            <input 
                              type="number" 
                              step="0.01"
                              value={line.credit || ''} 
                              onChange={(e) => updateDraftLine(line.id, 'credit', parseFloat(e.target.value) || 0)}
                              className="border rounded px-2 py-1 text-xs w-full text-right bg-white"
                            />
                          ) : (
                            line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'
                          )}
                        </td>
                        <td className="p-4 text-slate-500 italic max-w-xs truncate">
                          {isEditing ? (
                            <input 
                              type="text" 
                              value={line.description} 
                              onChange={(e) => updateDraftLine(line.id, 'description', e.target.value)}
                              className="border rounded px-2 py-1 text-xs w-full bg-white"
                              placeholder="Memo..."
                            />
                          ) : (
                            line.description
                          )}
                          {idx === 0 && entry.method && !isEditing && (
                            <span className="not-italic text-[10px] bg-slate-100 px-1.5 py-0.5 rounded ml-2 font-bold text-slate-400 uppercase tracking-tighter">
                              {entry.method}
                            </span>
                          )}
                        </td>
                        <td className="p-4 text-right">
                          {idx === 0 && (
                            <div className="flex justify-end gap-2">
                              {isEditing ? (
                                <>
                                  <button onClick={handleSave} className="text-emerald-600 hover:text-emerald-700 transition-all font-black text-[10px] uppercase tracking-tighter bg-emerald-50 px-2 py-1 rounded border border-emerald-100 shadow-sm">Save</button>
                                  <button onClick={cancelEditing} className="text-slate-400 hover:text-slate-600 transition-all font-black text-[10px] uppercase tracking-tighter">Cancel</button>
                                </>
                              ) : (
                                <>
                                  <button 
                                    onClick={() => startEditing(entry)}
                                    className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-slate-600 transition-all p-1"
                                    title="Edit Transaction"
                                  >
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                                  </button>
                                  <button 
                                    onClick={() => onDelete(entry.id)}
                                    className="opacity-0 group-hover:opacity-100 text-red-200 hover:text-red-500 transition-all p-1"
                                    title="Delete Transaction"
                                  >
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                                  </button>
                                </>
                              )}
                            </div>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default GeneralJournal;

export enum NaturalBalance {
  DEBIT = 'DR',
  CREDIT = 'CR'
}

export enum FinancialStatement {
  BALANCE_SHEET = 'Balance Sheet',
  INCOME_STATEMENT = 'Income Statement',
  OFF_STATEMENT = 'Off-Statement (Internal/Clearing)'
}

export enum AccountClassification {
  CURRENT_ASSET = 'Current Asset',
  LONG_TERM_ASSET = 'Long-Term Asset',
  CURRENT_LIABILITY = 'Current Liability',
  LONG_TERM_LIABILITY = 'Long-Term Liability',
  EQUITY = 'Equity',
  REVENUE = 'Revenue',
  COGS = 'Cost of Goods Sold',
  OPERATING_EXPENSE = 'Operating Expenses',
  OTHER_INCOME_EXPENSE = 'Other Income (Expenses)',
  CLEARING_ACCOUNT = 'Clearing Account',
  TEMPORARY_ACCOUNT = 'Temporary Account'
}

export interface Account {
  id: string;
  name: string;
  naturalBalance: NaturalBalance;
  financialStatement: FinancialStatement;
  classification: AccountClassification;
  startingBalance: number; // Balance forward anchor
  isArchived?: boolean;
}

export interface JournalEntryLine {
