import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
}

const BalanceSheet: React.FC<Props> = ({ transactions = [], accounts = [] }) => {
  // Derive periods from transaction data
  const sortedPeriods = useMemo(() => {
    const periods = new Set<string>();
    transactions.forEach(tx => {
      const date = new Date(tx.date);
      if (!isNaN(date.getTime())) {
        periods.add(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`);
      }
    });
    return Array.from(periods).sort((a, b) => a.localeCompare(b));
  }, [transactions]);

  const getCumulativeBalance = (accountId: string, upToPeriod: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let balance = Number(account.startingBalance) || 0;
    const [year, month] = upToPeriod.split('-').map(Number);
    const cutoffDate = new Date(year, month, 0, 23, 59, 59);

    transactions.forEach(tx => {
      const txDate = new Date(tx.date);
      if (txDate <= cutoffDate) {
        tx.lines.forEach(l => {
          if (l.accountId === accountId) {
            if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
            else balance += (l.credit - l.debit);
          }
        });
      }
    });
    return balance;
  };

  const getNetIncomeCumulative = (upToPeriod: string) => {
    const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
    let net = 0;
    isAccounts.forEach(acc => {
      const start = Number(acc.startingBalance) || 0;
      const currentBal = getCumulativeBalance(acc.id, upToPeriod);
      const activity = currentBal - start;

      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
        net += activity;
      } else {
        net -= activity;
      }
    });
    return net;
  };

  const bsAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.BALANCE_SHEET);

  const calculateClassTotal = (classification: AccountClassification, upToPeriod: string) => {
    return bsAccounts
      .filter(a => a.classification === classification)
      .reduce((sum, a) => sum + getCumulativeBalance(a.id, upToPeriod), 0);
  };

  if (sortedPeriods.length === 0) {
    return (
      <div className="p-20 text-center text-slate-400 italic bg-slate-50 rounded-xl border-2 border-dashed border-slate-200">
        <p className="text-lg font-bold mb-2 text-slate-700 tracking-tight">Financial Reports Pending</p>
        <p className="text-sm">Record your first transactions to generate comparative balance sheets.</p>
      </div>
    );
  }

  return (
    <div className="w-full">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-900">Comparative Balance Sheet</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">Historical Wealth Positioning</p>
      </div>

      <div className="overflow-x-auto border rounded-2xl shadow-xl bg-white">
        <table className="w-full border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-900 text-white">
              <th className="p-4 text-left w-72 border-r border-slate-800 text-[10px] font-black uppercase tracking-widest">Account Classification</th>
              {sortedPeriods.map(p => (
                <th key={p} className="p-4 text-right text-[10px] uppercase font-black tracking-widest border-r border-slate-800">
                  {new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            <tr className="bg-slate-50"><td colSpan={sortedPeriods.length + 1} className="p-3 font-black text-slate-900 text-[10px] tracking-widest uppercase border-b">1. ASSETS</td></tr>

            <tr className="bg-white"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Current Assets</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
            {bsAccounts.filter(a => a.classification === AccountClassification.CURRENT_ASSET).map(acc => (
              <tr key={acc.id} className="border-b hover:bg-slate-50/50 transition-colors">
                <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                {sortedPeriods.map(p => (
                  <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                    {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                ))}
              </tr>
            ))}
            <tr className="font-bold bg-slate-50/50 border-t border-slate-100">
              <td className="p-2.5 pl-6 text-[10px] uppercase italic text-slate-400 border-r border-slate-100">Total Current Assets</td>
              {sortedPeriods.map(p => (
                <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                  {calculateClassTotal(AccountClassification.CURRENT_ASSET, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
              ))}
            </tr>

            <tr className="bg-white"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Long-Term Assets</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
            {bsAccounts.filter(a => a.classification === AccountClassification.LONG_TERM_ASSET).map(acc => (
              <tr key={acc.id} className="border-b hover:bg-slate-50/50 transition-colors">
                <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                {sortedPeriods.map(p => (
                  <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                    {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                ))}
              </tr>
            ))}
            <tr className="font-bold bg-slate-50/50 border-t border-slate-100">
              <td className="p-2.5 pl-6 text-[10px] uppercase italic text-slate-400 border-r border-slate-100">Total Long-Term Assets</td>
              {sortedPeriods.map(p => (
                <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                  {calculateClassTotal(AccountClassification.LONG_TERM_ASSET, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
              ))}
            </tr>

            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">TOTAL ASSETS</td>
              {sortedPeriods.map(p => {
                const total = calculateClassTotal(AccountClassification.CURRENT_ASSET, p) + calculateClassTotal(AccountClassification.LONG_TERM_ASSET, p);
                return <td key={p} className="p-4 text-right font-mono text-sm border-r border-slate-700">${total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>

            <tr className="h-10"></tr>

            <tr className="bg-slate-50"><td colSpan={sortedPeriods.length + 1} className="p-3 font-black text-slate-900 text-[10px] tracking-widest uppercase border-b">2. LIABILITIES & EQUITY</td></tr>

            <tr className="bg-white"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Liabilities</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
            {[AccountClassification.CURRENT_LIABILITY, AccountClassification.LONG_TERM_LIABILITY].map(cls => (
              bsAccounts.filter(a => a.classification === cls).map(acc => (
                <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                  <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                  {sortedPeriods.map(p => (
                    <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                      {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>
                  ))}
                </tr>
              ))
            ))}

            <tr className="bg-white border-t border-slate-100"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Equity</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
            {bsAccounts.filter(a => a.classification === AccountClassification.EQUITY).map(acc => (
              <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                {sortedPeriods.map(p => (
                  <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                    {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                ))}
              </tr>
            ))}
            <tr className="border-b hover:bg-slate-50/50">
              <td className="p-2.5 pl-8 text-xs font-medium text-slate-500 italic border-r border-slate-100">Retained Earnings (All-Time)</td>
              {sortedPeriods.map(p => (
                <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100 text-emerald-600 font-black">
                  {getNetIncomeCumulative(p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
              ))}
            </tr>

            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">TOTAL LIABILITIES & EQUITY</td>
              {sortedPeriods.map(p => {
                const totalL = calculateClassTotal(AccountClassification.CURRENT_LIABILITY, p) + calculateClassTotal(AccountClassification.LONG_TERM_LIABILITY, p);
                const totalE = calculateClassTotal(AccountClassification.EQUITY, p) + getNetIncomeCumulative(p);
                return <td key={p} className="p-4 text-right font-mono text-sm border-r border-slate-700">${(totalL + totalE).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default BalanceSheet;

import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
}

const IncomeStatement: React.FC<Props> = ({ transactions = [], accounts = [] }) => {
  const sortedPeriods = useMemo(() => {
    const periods = new Set<string>();
    transactions.forEach(tx => {
      const date = new Date(tx.date);
      if (!isNaN(date.getTime())) {
        periods.add(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`);
      }
    });
    return Array.from(periods).sort((a, b) => a.localeCompare(b));
  }, [transactions]);

  const getMonthlyActivity = (accountId: string, period: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let activity = 0;
    const [year, month] = period.split('-').map(Number);

    transactions.forEach(tx => {
      const txDate = new Date(tx.date);
      if (txDate.getFullYear() === year && (txDate.getMonth() + 1) === month) {
        tx.lines.forEach(l => {
          if (l.accountId === accountId) {
            if (account.naturalBalance === NaturalBalance.DEBIT) activity += (l.debit - l.credit);
            else activity += (l.credit - l.debit);
          }
        });
      }
    });
    return activity;
  };

  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);

  const calculateMonthlyNet = (period: string) => {
    let rev = 0;
    let exp = 0;
    isAccounts.forEach(acc => {
      const act = getMonthlyActivity(acc.id, period);
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
        rev += act;
      } else {
        exp += act;
      }
    });
    return rev - exp;
  };

  if (sortedPeriods.length === 0) {
    return (
      <div className="p-20 text-center text-slate-400 italic bg-slate-50 rounded-xl border-2 border-dashed border-slate-200">
        <p className="text-lg font-bold mb-2 text-slate-700 tracking-tight">Income Reporting Ready</p>
        <p className="text-sm">Record transactions to see monthly revenue and expense performance columns.</p>
      </div>
    );
  }

  return (
    <div className="w-full">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-900">Income Performance</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">Dynamic Revenue & Expense Matrix</p>
      </div>

      <div className="overflow-x-auto border rounded-2xl shadow-xl bg-white">
        <table className="w-full border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-900 text-white">
              <th className="p-4 text-left w-72 border-r border-slate-800 text-[10px] font-black uppercase tracking-widest">Income Category</th>
              {sortedPeriods.map(p => (
                <th key={p} className="p-4 text-right text-[10px] uppercase font-black tracking-widest border-r border-slate-800">
                  {new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {[
              { title: "Revenue", type: AccountClassification.REVENUE, color: "text-emerald-700" },
              { title: "Cost of Goods Sold", type: AccountClassification.COGS, color: "text-amber-700" },
              { title: "Operating Expenses", type: AccountClassification.OPERATING_EXPENSE, color: "text-slate-700" },
              { title: "Other Income / (Exp)", type: AccountClassification.OTHER_INCOME_EXPENSE, color: "text-indigo-700" }
            ].map(section => (
              <React.Fragment key={section.title}>
                <tr className="bg-slate-50 border-t border-slate-100">
                  <td className="p-2.5 font-black text-slate-900 text-[9px] tracking-widest uppercase">{section.title}</td>
                  {sortedPeriods.map(p => <td key={p} className="p-2 border-r border-slate-100"></td>)}
                </tr>
                {isAccounts.filter(a => a.classification === section.type).map(acc => (
                  <tr key={acc.id} className="border-b hover:bg-slate-50/50 transition-colors">
                    <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                    {sortedPeriods.map(p => (
                      <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                        {getMonthlyActivity(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                ))}
              </React.Fragment>
            ))}

            <tr className="h-10"></tr>
            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900 shadow-inner">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">NET PERIOD INCOME</td>
              {sortedPeriods.map(p => {
                const net = calculateMonthlyNet(p);
                return (
                  <td key={p} className={`p-4 text-right font-mono text-sm border-r border-slate-700 ${net < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                    ${net.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                );
              })}
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default IncomeStatement;

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<string[]>(['JE']);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
        if (parsed.paymentMethods) setPaymentMethods(parsed.paymentMethods);
      } catch (e) {}
    }

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
        if (data.paymentMethods) setPaymentMethods(data.paymentMethods || ['JE']);
        localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
          accounts: data.accounts,
          transactions: data.transactions,
          closedPeriods: data.closedPeriods || [],
          paymentMethods: data.paymentMethods || ['JE']
        }));
      } else {
        setDoc(userDocRef, { accounts: INITIAL_ACCOUNTS, transactions: [], closedPeriods: [], paymentMethods: ['JE'] })
          .catch(err => console.error("Seeding failed:", err));
      }
      setDataLoading(false);
    }, (error) => {
      setDataLoading(false);
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = async (newAccs: Account[], newTxs: JournalEntry[], newPeriods: string[], newMethods: string[]) => {
    if (!user) return;
    localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods,
      paymentMethods: newMethods
    }));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        accounts: newAccs,
        transactions: newTxs,
        closedPeriods: newPeriods,
        paymentMethods: newMethods,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Save error:", err);
    }
  };

  const resetSystem = (full: boolean) => {
    const defaultMethods = ['JE'];
    if (full) {
      setAccounts(INITIAL_ACCOUNTS);
      setTransactions([]);
      setClosedPeriods([]);
      setPaymentMethods(defaultMethods);
      saveToFirestore(INITIAL_ACCOUNTS, [], [], defaultMethods);
    } else {
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(accounts, [], [], paymentMethods);
    }
    setActiveTab('Dashboard');
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods, paymentMethods);
    }
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Permanently delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated, closedPeriods, paymentMethods);
    }
  };

  const addPaymentMethod = (method: string) => {
    if (paymentMethods.includes(method)) return;
    const updated = [...paymentMethods, method];
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated);
  };

  const removePaymentMethod = (method: string) => {
    if (method === 'JE') return; // Protect default
    const updated = paymentMethods.filter(m => m !== method);
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated);
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const existingNames = new Set(accounts.map(a => a.name.toLowerCase()));
    const uniqueNew = newAccounts.filter(a => !existingNames.has(a.name.toLowerCase()));
    const updatedAccs = [...accounts, ...uniqueNew];
    const updatedTxs = [...transactions, ...newTransactions];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods, paymentMethods);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <h1 className="text-xl font-bold tracking-tighter">VISTA SHORE</h1>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-emerald-500 transition-colors">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm text-slate-300 hover:text-white transition-colors">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto bg-slate-50">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} paymentMethods={paymentMethods} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={importData} onReset={resetSystem} paymentMethods={paymentMethods} onAddMethod={addPaymentMethod} onRemoveMethod={removePaymentMethod} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Account, JournalEntry, JournalEntryLine } from '../types';

interface Props {
  accounts: Account[];
  onRecord: (entry: JournalEntry) => void;
  lastId: number;
  paymentMethods: string[];
}

const TransactionRecorder: React.FC<Props> = ({ accounts, onRecord, lastId, paymentMethods }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [method, setMethod] = useState('JE');
  const [lines, setLines] = useState<JournalEntryLine[]>([
    { id: '1', accountId: '', debit: 0, credit: 0, description: '' },
    { id: '2', accountId: '', debit: 0, credit: 0, description: '' }
  ]);

  // Filter out archived accounts for new transactions
  const activeAccounts = accounts
    .filter(acc => !acc.isArchived)
    .sort((a,b) => a.name.localeCompare(b.name));

  const totalDebits = lines.reduce((sum, l) => sum + (l.debit || 0), 0);
  const totalCredits = lines.reduce((sum, l) => sum + (l.credit || 0), 0);
  const isBalanced = Math.abs(totalDebits - totalCredits) < 0.01 && totalDebits > 0;

  const addLine = () => {
    setLines([...lines, { id: Math.random().toString(), accountId: '', debit: 0, credit: 0, description: '' }]);
  };

  const removeLine = (id: string) => {
    if (lines.length > 2) {
      setLines(lines.filter(l => l.id !== id));
    }
  };

  const updateLine = (id: string, field: keyof JournalEntryLine, value: any) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: value } : l));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isBalanced) {
      alert("Debits must equal credits!");
      return;
    }

    const entry: JournalEntry = {
      id: lastId + 1,
      date,
      method: method || 'JE',
      lines: lines.filter(l => l.accountId && (l.debit > 0 || l.credit > 0))
    };

    onRecord(entry);
    setMethod('JE');
    setLines([
      { id: '1', accountId: '', debit: 0, credit: 0, description: '' },
      { id: '2', accountId: '', debit: 0, credit: 0, description: '' }
    ]);
    alert("Transaction recorded successfully!");
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6 border-b pb-2">Record Journal Entry</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 bg-slate-50 p-4 rounded-lg border">
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Transaction ID</label>
            <input type="text" disabled value={lastId + 1} className="w-full bg-gray-100 border rounded px-3 py-2 text-gray-600" />
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Date</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)} 
              className="w-full border rounded px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none" 
              required
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Method / Card</label>
            <select 
              value={method} 
              onChange={(e) => setMethod(e.target.value)} 
              className="w-full border rounded px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none bg-white font-semibold"
            >
              {paymentMethods.map(m => (
                <option key={m} value={m}>{m}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm border-collapse">
            <thead>
              <tr className="bg-slate-100 border-b">
                <th className="p-3 text-left font-semibold text-gray-600">Account</th>
                <th className="p-3 text-left font-semibold text-gray-600 w-32">Debit</th>
                <th className="p-3 text-left font-semibold text-gray-600 w-32">Credit</th>
                <th className="p-3 text-left font-semibold text-gray-600">Description</th>
                <th className="p-3 w-10"></th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {lines.map((line) => (
                <tr key={line.id} className="hover:bg-gray-50">
                  <td className="p-2">
                    <select
                      value={line.accountId}
                      onChange={(e) => updateLine(line.id, 'accountId', e.target.value)}
                      className="w-full border rounded px-2 py-1.5 focus:ring-2 focus:ring-emerald-500 outline-none"
                    >
                      <option value="">Select Account...</option>
                      {activeAccounts.map(acc => (
                        <option key={acc.id} value={acc.id}>{acc.name}</option>
                      ))}
                    </select>
                  </td>
                  <td className="p-2">
                    <input
                      type="number"
                      step="0.01"
                      value={line.debit || ''}
                      onChange={(e) => updateLine(line.id, 'debit', parseFloat(e.target.value) || 0)}
                      className="w-full border rounded px-2 py-1.5 text-right font-mono"
                      placeholder="0.00"
                    />
                  </td>
                  <td className="p-2">
                    <input
                      type="number"
                      step="0.01"
                      value={line.credit || ''}
                      onChange={(e) => updateLine(line.id, 'credit', parseFloat(e.target.value) || 0)}
                      className="w-full border rounded px-2 py-1.5 text-right font-mono"
                      placeholder="0.00"
                    />
                  </td>
                  <td className="p-2">
                    <input
                      type="text"
                      value={line.description}
                      onChange={(e) => updateLine(line.id, 'description', e.target.value)}
                      className="w-full border rounded px-2 py-1.5"
                      placeholder="Notes..."
                    />
                  </td>
                  <td className="p-2 text-center">
                    <button 
                      type="button"
                      onClick={() => removeLine(line.id)}
                      className="text-red-400 hover:text-red-600 p-1"
                      title="Remove Row"
                    >
                      ✕
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr className="bg-slate-50 font-bold border-t-2 border-slate-200">
                <td className="p-3 text-right">Totals:</td>
                <td className={`p-3 text-right font-mono ${totalDebits !== totalCredits ? 'text-red-500' : 'text-emerald-600'}`}>
                  {totalDebits.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td className={`p-3 text-right font-mono ${totalDebits !== totalCredits ? 'text-red-500' : 'text-emerald-600'}`}>
                  {totalCredits.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td colSpan={2} className="p-3">
                  {!isBalanced && totalDebits + totalCredits > 0 && (
                    <span className="text-xs text-red-500 font-medium">Out of balance by {(Math.abs(totalDebits - totalCredits)).toFixed(2)}</span>
                  )}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>

        <div className="flex justify-between items-center pt-4 border-t">
          <button 
            type="button" 
            onClick={addLine}
            className="text-emerald-600 font-semibold text-sm hover:underline"
          >
            + Add Row
          </button>

          <button 
            type="submit"
            disabled={!isBalanced}
            className={`px-8 py-3 rounded-lg font-bold shadow transition-all ${
              isBalanced 
                ? 'bg-emerald-600 text-white hover:bg-emerald-700 transform hover:-translate-y-0.5' 
                : 'bg-gray-300 text-gray-500 cursor-not-allowed'
            }`}
          >
            Record JE
          </button>
        </div>
      </form>
    </div>
  );
};

