import React, { useRef, useState } from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification } from '../types';

interface Props {
  accounts: Account[];
  transactions: JournalEntry[];
  onImport: (transactions: JournalEntry[], accounts: Account[]) => void;
  onReset: (full: boolean) => void;
  paymentMethods: string[];
  onAddMethod: (method: string) => void;
  onRemoveMethod: (method: string) => void;
}

const DataManager: React.FC<Props> = ({ accounts, transactions, onImport, onReset, paymentMethods, onAddMethod, onRemoveMethod }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [newMethod, setNewMethod] = useState('');

  const downloadTemplate = () => {
    const headers = "Date,Method,Account Name,Debit,Credit,Description,TransactionID\n";
    const example = "2024-01-01,Setup,Cash,5000.00,0,Opening Balance,1001\n2024-01-01,Setup,Benson Contributions,0,5000.00,Initial Capital,1001";
    const blob = new Blob([headers + example], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'vista_import_template.csv';
    a.click();
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => parseCSV(event.target?.result as string);
    reader.readAsText(file);
  };

  const parseCSV = (csv: string) => {
    const lines = csv.split('\n');
    const txMap: Record<number, JournalEntry> = {};
    const newAccounts: Account[] = [];

    for (let i = 1; i < lines.length; i++) {
      if (!lines[i].trim()) continue;
      const values = lines[i].split(',').map(v => v.trim());
      const [date, method, accName, debitVal, creditVal, desc, txIdVal] = values;
      const debit = parseFloat(debitVal) || 0;
      const credit = parseFloat(creditVal) || 0;
      const txId = parseInt(txIdVal) || Math.floor(Math.random() * 10000);

      let account = accounts.find(a => a.name.toLowerCase() === accName.toLowerCase()) || newAccounts.find(a => a.name.toLowerCase() === accName.toLowerCase());
      if (!account) {
        account = {
          id: Math.random().toString(),
          name: accName,
          naturalBalance: NaturalBalance.DEBIT,
          financialStatement: FinancialStatement.BALANCE_SHEET,
          classification: AccountClassification.CURRENT_ASSET,
          startingBalance: 0
        };
        newAccounts.push(account);
      }

      if (!txMap[txId]) txMap[txId] = { id: txId, date, method, lines: [] };
      txMap[txId].lines.push({ id: Math.random().toString(), accountId: account.id, debit, credit, description: desc });
    }
    onImport(Object.values(txMap), newAccounts);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const confirmReset = (full: boolean) => {
    const msg = full 
      ? "PERMANENT DESTRUCTION: This will delete ALL accounts, transactions, and settings. Are you absolutely sure?" 
      : "TRANSACTION WIPE: This will delete ALL journal entries and history, but KEEP your current Chart of Accounts. Use this for starting a new fiscal year. Proceed?";

    if (window.confirm(msg)) {
      if (window.confirm("FINAL WARNING: This action is irreversible. Proceed?")) {
        onReset(full);
      }
    }
  };

  const handleAddMethod = () => {
    if (newMethod.trim()) {
      onAddMethod(newMethod.trim());
      setNewMethod('');
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 pb-20">
      {/* Cards & Methods Setup Section */}
      <section className="bg-slate-50 border-2 border-slate-200 p-10 rounded-3xl space-y-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter flex items-center gap-3">
            <span className="text-blue-500">💳</span> Cards & Reference Accounts
          </h2>
          <p className="text-slate-500 text-sm font-medium mt-1">Configure the methods/cards used in the Transaction Recorder.</p>
        </div>

        <div className="flex gap-4">
          <input 
            type="text" 
            value={newMethod} 
            onChange={(e) => setNewMethod(e.target.value)}
            className="flex-1 border rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 text-sm font-semibold"
            placeholder="e.g. AmEx 1001, Cash, Petty Cash..."
            onKeyDown={(e) => e.key === 'Enter' && handleAddMethod()}
          />
          <button 
            onClick={handleAddMethod}
            className="bg-blue-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-blue-700 shadow-md transition-all active:scale-95"
          >
            Add Method
          </button>
        </div>

        <div className="flex flex-wrap gap-2">
          {paymentMethods.map(method => (
            <div key={method} className="bg-white border border-slate-200 pl-4 pr-2 py-2 rounded-xl flex items-center gap-4 group shadow-sm">
              <span className="text-sm font-bold text-slate-700">{method}</span>
              {method !== 'JE' && (
                <button 
                  onClick={() => onRemoveMethod(method)}
                  className="text-slate-300 hover:text-red-500 transition-colors p-1"
                >
                  ✕
                </button>
              )}
            </div>
          ))}
          {paymentMethods.length === 0 && <p className="text-xs text-slate-400 italic">No methods configured. Default "JE" will be used.</p>}
        </div>
      </section>

      {/* Import Section */}
      <section className="bg-emerald-50 border-2 border-emerald-100 p-10 rounded-3xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-10">
          <svg className="w-32 h-32" fill="currentColor" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>
        </div>
        <div className="relative z-10 space-y-6">
          <div>
            <h2 className="text-3xl font-black text-emerald-900 tracking-tighter">Bulk Import Engine</h2>
            <p className="text-emerald-700 text-sm font-medium mt-1">Populate your ledgers with historical Excel/CSV data.</p>
          </div>
          <div className="flex flex-wrap gap-4">
            <button onClick={downloadTemplate} className="bg-white text-emerald-600 border border-emerald-200 px-8 py-3 rounded-xl font-bold hover:bg-emerald-100 shadow-sm transition-all flex items-center gap-2">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
              Get CSV Template
            </button>
            <button onClick={() => fileInputRef.current?.click()} className="bg-emerald-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-emerald-700 shadow-lg shadow-emerald-200 transition-all active:scale-95">
              Upload Local Data
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept=".csv" onChange={handleFileUpload} />
          </div>
        </div>
      </section>

      {/* Maintenance Zone */}
      <section className="bg-white border-2 border-red-50 p-10 rounded-3xl space-y-8">
        <div className="border-b-2 border-red-50 pb-4">
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter flex items-center gap-3">
            <span className="text-red-500">⚠</span> Maintenance & System Reset
          </h2>
          <p className="text-slate-500 text-sm mt-1">Tools for system migration and data cleanup.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-4 p-6 bg-slate-50 rounded-2xl border border-slate-100">
            <h3 className="font-black text-slate-800 uppercase tracking-widest text-xs">Option A: Transactional Wipe</h3>
            <p className="text-xs text-slate-500 leading-relaxed">
              Deletes all General Journal entries and Ledger history. 
              <strong> Keeps your Chart of Accounts, Classifications, and Starting Balances.</strong> 
              Ideal for starting a new fiscal year fresh.
            </p>
            <button 
              onClick={() => confirmReset(false)}
              className="w-full bg-slate-800 text-white py-3 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-slate-700 transition-colors shadow-sm"
            >
              Clear Transactions Only
            </button>
          </div>

          <div className="space-y-4 p-6 bg-red-50 rounded-2xl border border-red-100">
            <h3 className="font-black text-red-800 uppercase tracking-widest text-xs">Option B: Factory Reset</h3>
            <p className="text-xs text-red-600/70 leading-relaxed">
              Wipes the entire database clean. Removes all accounts and all transactions. 
              System will return to original default accounts.
            </p>
            <button 
              onClick={() => confirmReset(true)}
              className="w-full bg-red-600 text-white py-3 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-red-700 transition-colors shadow-lg shadow-red-100"
            >
              Destroy All Data
            </button>
          </div>
        </div>

        <div className="text-center">
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em]">Warning: These actions cannot be undone</p>
        </div>
      </section>
    </div>
  );
};

