              className="w-full bg-slate-800 text-white py-3 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-slate-700 transition-colors shadow-sm"
            >
              Clear Transactions Only
            </button>
          </div>

          <div className="space-y-4 p-6 bg-red-50 rounded-2xl border border-red-100">
            <h3 className="font-black text-red-800 uppercase tracking-widest text-xs">Option B: Factory Reset</h3>
            <p className="text-xs text-red-600/70 leading-relaxed">
              Wipes the entire database clean. Removes all accounts and all transactions. 
              System will return to original default accounts.
            </p>
            <button 
              onClick={() => confirmReset(true)}
              className="w-full bg-red-600 text-white py-3 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-red-700 transition-colors shadow-lg shadow-red-100"
            >
              Destroy All Data
            </button>
          </div>
        </div>

        <div className="text-center">
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em]">Warning: These actions cannot be undone</p>
        </div>
      </section>
    </div>
  );
};

export default DataManager;

import React from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification, TabType } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onNavigate: (tab: TabType) => void;
}

const Dashboard: React.FC<Props> = ({ transactions, accounts, onNavigate }) => {
  const getBalance = (accountId: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;
    let balance = Number(account.startingBalance) || 0;
    transactions.forEach(tx => {
      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
          else balance += (l.credit - l.debit);
        }
      });
    });
    return balance;
  };

  const cashAccounts = accounts.filter(a => 
    a.classification === AccountClassification.CURRENT_ASSET && 
    (a.name.toLowerCase().includes('cash') || a.name.toLowerCase().includes('bank'))
  );

  const liabilityAccounts = accounts.filter(a => 
    a.classification === AccountClassification.CURRENT_LIABILITY || 
    a.classification === AccountClassification.LONG_TERM_LIABILITY
  );

  const totalCash = cashAccounts.reduce((sum, a) => sum + getBalance(a.id), 0);
  const totalLiabilities = liabilityAccounts.reduce((sum, a) => sum + getBalance(a.id), 0);

  // Net Income calculation
  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
  let netIncome = 0;
  isAccounts.forEach(acc => {
    const b = getBalance(acc.id);
    const start = Number(acc.startingBalance) || 0;
    const activity = b - start;
    if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
       netIncome += activity; 
    } else {
       netIncome -= activity;
    }
  });

  return (
    <div className="space-y-10">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Financial Health</h2>
          <p className="text-slate-500 font-medium">Real-time ledger audit for Vista Shore Products, LLC</p>
        </div>
        <div className="bg-emerald-50 px-4 py-2 rounded-full border border-emerald-100">
          <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-2">
            <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
            Cloud Sync Active
          </span>
        </div>
      </div>

      {/* Primary KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow group">
          <div className="flex justify-between items-center mb-6">
            <span className="text-3xl grayscale group-hover:grayscale-0 transition-all">💰</span>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Liquid Assets</span>
          </div>
          <p className="text-sm font-bold text-slate-500 mb-1">Total Cash Position</p>
          <p className="text-3xl font-black font-mono text-emerald-600 tracking-tighter">
            ${totalCash.toLocaleString(undefined, { minimumFractionDigits: 2 })}
          </p>
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow group">
          <div className="flex justify-between items-center mb-6">
            <span className="text-3xl grayscale group-hover:grayscale-0 transition-all">💳</span>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Total Debt</span>
          </div>
          <p className="text-sm font-bold text-slate-500 mb-1">Current Liabilities</p>
          <p className="text-3xl font-black font-mono text-amber-600 tracking-tighter">
            ${totalLiabilities.toLocaleString(undefined, { minimumFractionDigits: 2 })}
          </p>
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow group">
          <div className="flex justify-between items-center mb-6">
            <span className="text-3xl grayscale group-hover:grayscale-0 transition-all">📈</span>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Performance</span>
          </div>
          <p className="text-sm font-bold text-slate-500 mb-1">Net Income (Current Cycle)</p>
          <p className={`text-3xl font-black font-mono tracking-tighter ${netIncome >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
            ${netIncome.toLocaleString(undefined, { minimumFractionDigits: 2 })}
          </p>
        </div>
      </div>

      {/* Granular Account Watchlist */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Liability Breakdown (Credit Cards) */}
        <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
          <div className="bg-slate-50 p-6 border-b border-slate-100 flex justify-between items-center">
            <h3 className="text-lg font-black text-slate-800 tracking-tight flex items-center gap-2">
              <span className="w-2 h-6 bg-amber-500 rounded-full"></span>
              Liability breakdown (Watchlist)
            </h3>
            <button onClick={() => onNavigate('Ledgers')} className="text-[10px] font-black uppercase text-slate-400 hover:text-amber-600 transition-colors">View All</button>
          </div>
          <div className="p-6 space-y-4">
            {liabilityAccounts.length === 0 ? (
              <p className="text-center py-10 text-slate-400 italic text-sm font-medium">No liability accounts configured.</p>
            ) : (
              liabilityAccounts.map(acc => {
                const bal = getBalance(acc.id);
                return (
                  <div key={acc.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100 hover:border-amber-200 transition-colors">
                    <div className="flex flex-col">
                      <span className="text-xs font-black text-slate-400 uppercase tracking-widest">{acc.classification}</span>
                      <span className="font-bold text-slate-700">{acc.name}</span>
                    </div>
                    <div className="text-right">
                      <span className={`text-lg font-mono font-black ${bal > 0 ? 'text-amber-600' : 'text-slate-400'}`}>
                        ${bal.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </span>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Liquidity Breakdown (Banks/Cash) */}
        <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
          <div className="bg-slate-50 p-6 border-b border-slate-100 flex justify-between items-center">
            <h3 className="text-lg font-black text-slate-800 tracking-tight flex items-center gap-2">
              <span className="w-2 h-6 bg-emerald-500 rounded-full"></span>
              Cash & Liquidity Sources
            </h3>
            <button onClick={() => onNavigate('Ledgers')} className="text-[10px] font-black uppercase text-slate-400 hover:text-emerald-600 transition-colors">View All</button>
          </div>
          <div className="p-6 space-y-4">
            {cashAccounts.length === 0 ? (
              <p className="text-center py-10 text-slate-400 italic text-sm font-medium">No cash accounts configured.</p>
            ) : (
              cashAccounts.map(acc => {
                const bal = getBalance(acc.id);
                return (
                  <div key={acc.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100 hover:border-emerald-200 transition-colors">
                    <div className="flex flex-col">
                      <span className="text-xs font-black text-slate-400 uppercase tracking-widest">{acc.classification}</span>
                      <span className="font-bold text-slate-700">{acc.name}</span>
                    </div>
                    <div className="text-right">
                      <span className={`text-lg font-mono font-black ${bal > 0 ? 'text-emerald-600' : 'text-slate-400'}`}>
                        ${bal.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </span>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>

      {/* Quick Actions & Recent TX */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 bg-slate-900 p-8 rounded-3xl text-white space-y-6">
          <h3 className="text-xl font-black tracking-tight">System Controls</h3>
          <div className="grid grid-cols-1 gap-3">
            <button onClick={() => onNavigate('Transaction Recorder')} className="w-full bg-emerald-600 hover:bg-emerald-500 p-4 rounded-2xl font-bold text-sm transition-all shadow-lg shadow-emerald-900/40 text-left flex items-center justify-between">
              Record Entry
              <span>→</span>
            </button>
            <button onClick={() => onNavigate('BS')} className="w-full bg-slate-800 hover:bg-slate-700 p-4 rounded-2xl font-bold text-sm transition-all text-left flex items-center justify-between">
              Balance Sheet
              <span>→</span>
            </button>
            <button onClick={() => onNavigate('IS')} className="w-full bg-slate-800 hover:bg-slate-700 p-4 rounded-2xl font-bold text-sm transition-all text-left flex items-center justify-between">
              Income Statement
              <span>→</span>
            </button>
          </div>
        </div>

        <div className="lg:col-span-2 bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
          <h3 className="text-xl font-black text-slate-800 tracking-tight mb-6 flex items-center gap-3">
            <span className="text-blue-500">📄</span>
            Recent Transaction Audit
          </h3>
          <div className="space-y-3">
            {transactions.slice(-5).reverse().map(t => (
              <div key={t.id} className="group bg-slate-50 p-4 rounded-2xl border border-slate-100 flex justify-between items-center transition-all hover:border-blue-200">
                <div className="flex items-center gap-4">
                  <span className="w-10 h-10 bg-white rounded-xl flex items-center justify-center font-black text-slate-400 text-xs border border-slate-100 group-hover:border-blue-100">#{t.id}</span>
                  <div className="flex flex-col">
                    <span className="font-black text-slate-700 text-sm">{t.date}</span>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{t.method}</span>
                  </div>
                </div>
                <div className="font-mono font-black text-slate-900 text-lg">
                  ${t.lines.filter(l => l.debit > 0).reduce((s,l) => s + l.debit, 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </div>
              </div>
            ))}
            {transactions.length === 0 && (
              <div className="text-center py-12">
                <p className="text-slate-300 italic font-black uppercase tracking-widest text-xs">No ledger activity found</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

export enum NaturalBalance {
  DEBIT = 'DR',
  CREDIT = 'CR'
}

export enum FinancialStatement {
  BALANCE_SHEET = 'Balance Sheet',
  INCOME_STATEMENT = 'Income Statement',
  OFF_STATEMENT = 'Off-Statement (Internal/Clearing)'
}

export enum AccountClassification {
  CURRENT_ASSET = 'Current Asset',
  LONG_TERM_ASSET = 'Long-Term Asset',
  CURRENT_LIABILITY = 'Current Liability',
  LONG_TERM_LIABILITY = 'Long-Term Liability',
  EQUITY = 'Equity',
  REVENUE = 'Revenue',
  COGS = 'Cost of Goods Sold',
  OPERATING_EXPENSE = 'Operating Expenses',
  OTHER_INCOME_EXPENSE = 'Other Income (Expenses)',
  CLEARING_ACCOUNT = 'Clearing Account',
  TEMPORARY_ACCOUNT = 'Temporary Account'
}

export interface Account {
  id: string;
  name: string;
  naturalBalance: NaturalBalance;
  financialStatement: FinancialStatement;
  classification: AccountClassification;
  startingBalance: number; // Balance forward anchor
  isArchived?: boolean;
}

export interface PaymentMethod {
  name: string;
  accountId: string;
}

export interface JournalEntryLine {
  id: string;
  accountId: string;
  debit: number;
  credit: number;
  description: string;
}

export interface JournalEntry {
  id: number;
  date: string;
  method: string;
  lines: JournalEntryLine[];
}

export type TabType = 
  | 'Dashboard'
  | 'Transaction Recorder' 
  | 'General Journal' 
  | 'Ledgers' 
  | 'BS' 
  | 'IS' 
  | 'CF' 
  | 'Trial Balance'
  | 'Data Manager';

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType, PaymentMethod } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([{ name: 'JE', accountId: '' }]);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
        if (parsed.paymentMethods) setPaymentMethods(parsed.paymentMethods);
      } catch (e) {}
    }

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
        if (data.paymentMethods) setPaymentMethods(data.paymentMethods);
        localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
          accounts: data.accounts,
          transactions: data.transactions,
          closedPeriods: data.closedPeriods || [],
          paymentMethods: data.paymentMethods || [{ name: 'JE', accountId: '' }]
        }));
      } else {
        setDoc(userDocRef, { accounts: INITIAL_ACCOUNTS, transactions: [], closedPeriods: [], paymentMethods: [{ name: 'JE', accountId: '' }] })
          .catch(err => console.error("Seeding failed:", err));
      }
      setDataLoading(false);
    }, (error) => {
      setDataLoading(false);
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = async (newAccs: Account[], newTxs: JournalEntry[], newPeriods: string[], newMethods: PaymentMethod[]) => {
    if (!user) return;
    localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods,
      paymentMethods: newMethods
    }));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        accounts: newAccs,
        transactions: newTxs,
        closedPeriods: newPeriods,
        paymentMethods: newMethods,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Save error:", err);
    }
  };

  const resetSystem = (full: boolean) => {
    const defaultMethods = [{ name: 'JE', accountId: '' }];
    if (full) {
      setAccounts(INITIAL_ACCOUNTS);
      setTransactions([]);
      setClosedPeriods([]);
      setPaymentMethods(defaultMethods);
      saveToFirestore(INITIAL_ACCOUNTS, [], [], defaultMethods);
    } else {
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(accounts, [], [], paymentMethods);
    }
    setActiveTab('Dashboard');
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods, paymentMethods);
    }
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Permanently delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated, closedPeriods, paymentMethods);
    }
  };

  const addPaymentMethod = (method: string, accountId: string) => {
    if (paymentMethods.some(m => m.name === method)) return;
    const updated = [...paymentMethods, { name: method, accountId }];
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated);
  };

  const removePaymentMethod = (methodName: string) => {
    if (methodName === 'JE') return;
    const updated = paymentMethods.filter(m => m.name !== methodName);
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated);
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const existingNames = new Set(accounts.map(a => a.name.toLowerCase()));
    const uniqueNew = newAccounts.filter(a => !existingNames.has(a.name.toLowerCase()));
    const updatedAccs = [...accounts, ...uniqueNew];
    const updatedTxs = [...transactions, ...newTransactions];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods, paymentMethods);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <h1 className="text-xl font-bold tracking-tighter">VISTA SHORE</h1>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-emerald-500 transition-colors">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm text-slate-300 hover:text-white transition-colors">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto bg-slate-50">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} paymentMethods={paymentMethods} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={importData} onReset={resetSystem} paymentMethods={paymentMethods} onAddMethod={addPaymentMethod} onRemoveMethod={removePaymentMethod} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Account, JournalEntry, JournalEntryLine, PaymentMethod, NaturalBalance } from '../types';

interface Props {
  accounts: Account[];
  onRecord: (entry: JournalEntry) => void;
  lastId: number;
  paymentMethods: PaymentMethod[];
}

const TransactionRecorder: React.FC<Props> = ({ accounts, onRecord, lastId, paymentMethods }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [methodName, setMethodName] = useState('JE');
  const [lines, setLines] = useState<JournalEntryLine[]>([
    { id: '1', accountId: '', debit: 0, credit: 0, description: '' },
    { id: '2', accountId: '', debit: 0, credit: 0, description: '' }
  ]);

  // Filter out archived accounts for new transactions
  const activeAccounts = accounts
    .filter(acc => !acc.isArchived)
    .sort((a,b) => a.name.localeCompare(b.name));

  // Auto-update second line when method changes
  useEffect(() => {
    if (methodName === 'JE') return;
    const method = paymentMethods.find(m => m.name === methodName);
    if (method && method.accountId) {
      setLines(prev => {
        const newLines = [...prev];
        // Ensure second line always tracks the payment source if method is set
        newLines[1] = { 
          ...newLines[1], 
          accountId: method.accountId,
          description: `Paid via ${methodName}`
        };
        return newLines;
      });
    }
  }, [methodName, paymentMethods]);

  const totalDebits = lines.reduce((sum, l) => sum + (l.debit || 0), 0);
  const totalCredits = lines.reduce((sum, l) => sum + (l.credit || 0), 0);
  const isBalanced = Math.abs(totalDebits - totalCredits) < 0.01 && totalDebits > 0;

  const addLine = () => {
    setLines([...lines, { id: Math.random().toString(), accountId: '', debit: 0, credit: 0, description: '' }]);
  };

  const removeLine = (id: string) => {
    if (lines.length > 2) {
      setLines(lines.filter(l => l.id !== id));
    }
  };

  const updateLine = (id: string, field: keyof JournalEntryLine, value: any) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: value } : l));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isBalanced) {
      alert("Debits must equal credits!");
      return;
    }

    const entry: JournalEntry = {
      id: lastId + 1,
      date,
      method: methodName || 'JE',
      lines: lines.filter(l => l.accountId && (l.debit > 0 || l.credit > 0))
    };

    onRecord(entry);
    setMethodName('JE');
    setLines([
      { id: '1', accountId: '', debit: 0, credit: 0, description: '' },
      { id: '2', accountId: '', debit: 0, credit: 0, description: '' }
    ]);
    alert("Transaction recorded successfully!");
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6 border-b pb-2">Record Journal Entry</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 bg-slate-50 p-4 rounded-lg border">
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Transaction ID</label>
            <input type="text" disabled value={lastId + 1} className="w-full bg-gray-100 border rounded px-3 py-2 text-gray-600" />
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Date</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)} 
              className="w-full border rounded px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none" 
              required
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Method / Card</label>
            <select 
              value={methodName} 
              onChange={(e) => setMethodName(e.target.value)} 
              className="w-full border rounded px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none bg-white font-semibold"
            >
              {paymentMethods.map(m => (
                <option key={m.name} value={m.name}>{m.name}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm border-collapse">
            <thead>
              <tr className="bg-slate-100 border-b">
                <th className="p-3 text-left font-semibold text-gray-600">Account</th>
                <th className="p-3 text-left font-semibold text-gray-600 w-32">Debit</th>
                <th className="p-3 text-left font-semibold text-gray-600 w-32">Credit</th>
                <th className="p-3 text-left font-semibold text-gray-600">Description</th>
                <th className="p-3 w-10"></th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {lines.map((line, idx) => (
                <tr key={line.id} className="hover:bg-gray-50">
                  <td className="p-2">
                    <select
                      value={line.accountId}
                      disabled={idx === 1 && methodName !== 'JE'}
                      onChange={(e) => updateLine(line.id, 'accountId', e.target.value)}
                      className={`w-full border rounded px-2 py-1.5 focus:ring-2 focus:ring-emerald-500 outline-none ${idx === 1 && methodName !== 'JE' ? 'bg-slate-100 font-bold' : ''}`}
                    >
                      <option value="">Select Account...</option>
                      {activeAccounts.map(acc => (
                        <option key={acc.id} value={acc.id}>{acc.name}</option>
                      ))}
                    </select>
                  </td>
                  <td className="p-2">
                    <input
                      type="number"
                      step="0.01"
                      value={line.debit || ''}
                      onChange={(e) => updateLine(line.id, 'debit', parseFloat(e.target.value) || 0)}
                      className="w-full border rounded px-2 py-1.5 text-right font-mono"
                      placeholder="0.00"
                    />
                  </td>
                  <td className="p-2">
                    <input
                      type="number"
                      step="0.01"
                      value={line.credit || ''}
                      onChange={(e) => updateLine(line.id, 'credit', parseFloat(e.target.value) || 0)}
                      className="w-full border rounded px-2 py-1.5 text-right font-mono"
                      placeholder="0.00"
                    />
                  </td>
                  <td className="p-2">
                    <input
                      type="text"
                      value={line.description}
                      onChange={(e) => updateLine(line.id, 'description', e.target.value)}
                      className="w-full border rounded px-2 py-1.5"
                      placeholder="Notes..."
                    />
                  </td>
                  <td className="p-2 text-center">
                    <button 
                      type="button"
                      disabled={idx === 1 && methodName !== 'JE'}
                      onClick={() => removeLine(line.id)}
                      className="text-red-400 hover:text-red-600 p-1 disabled:opacity-0"
                      title="Remove Row"
                    >
                      ✕
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr className="bg-slate-50 font-bold border-t-2 border-slate-200">
                <td className="p-3 text-right">Totals:</td>
                <td className={`p-3 text-right font-mono ${totalDebits !== totalCredits ? 'text-red-500' : 'text-emerald-600'}`}>
                  {totalDebits.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td className={`p-3 text-right font-mono ${totalDebits !== totalCredits ? 'text-red-500' : 'text-emerald-600'}`}>
                  {totalCredits.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td colSpan={2} className="p-3">
                  {!isBalanced && totalDebits + totalCredits > 0 && (
                    <span className="text-xs text-red-500 font-medium">Out of balance by {(Math.abs(totalDebits - totalCredits)).toFixed(2)}</span>
                  )}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>

        <div className="flex justify-between items-center pt-4 border-t">
          <button 
            type="button" 
            onClick={addLine}
            className="text-emerald-600 font-semibold text-sm hover:underline"
          >
            + Add Row
          </button>

          <button 
            type="submit"
            disabled={!isBalanced}
            className={`px-8 py-3 rounded-lg font-bold shadow transition-all ${
              isBalanced 
                ? 'bg-emerald-600 text-white hover:bg-emerald-700 transform hover:-translate-y-0.5' 
                : 'bg-gray-300 text-gray-500 cursor-not-allowed'
            }`}
          >
            Record JE
          </button>
        </div>
      </form>
    </div>
  );
};

export default TransactionRecorder;

import React, { useRef, useState, useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification, PaymentMethod } from '../types';

interface Props {
  accounts: Account[];
  transactions: JournalEntry[];
  onImport: (transactions: JournalEntry[], accounts: Account[]) => void;
  onReset: (full: boolean) => void;
  paymentMethods: PaymentMethod[];
  onAddMethod: (method: string, accountId: string) => void;
  onRemoveMethod: (method: string) => void;
}

const DataManager: React.FC<Props> = ({ accounts, transactions, onImport, onReset, paymentMethods, onAddMethod, onRemoveMethod }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [newMethodName, setNewMethodName] = useState('');
  const [targetAccountId, setTargetAccountId] = useState('');

  const eligibleAccounts = accounts.filter(a => 
    !a.isArchived && 
    (a.classification === AccountClassification.CURRENT_ASSET || 
     a.classification === AccountClassification.CURRENT_LIABILITY)
  ).sort((a, b) => a.name.localeCompare(b.name));

  const downloadTemplate = () => {
    const headers = "Date,Method,Account Name,Debit,Credit,Description,TransactionID\n";
    const example = "2024-01-01,Setup,Cash,5000.00,0,Opening Balance,1001\n2024-01-01,Setup,Benson Contributions,0,5000.00,Initial Capital,1001";
    const blob = new Blob([headers + example], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'vista_import_template.csv';
    a.click();
  };

  const exportFinancials = () => {
    let csv = "VISTA SHORE FINANCIAL REPORT PACKAGE\n";
    csv += `Exported: ${new Date().toLocaleString()}\n\n`;

    const getPeriods = () => {
      const p = new Set<string>();
      transactions.forEach(t => p.add(t.date.slice(0, 7)));
      return Array.from(p).sort();
    };
    const periods = getPeriods();

    const getBal = (accId: string, p: string) => {
      const acc = accounts.find(a => a.id === accId);
      if (!acc) return 0;
      let b = Number(acc.startingBalance) || 0;
      const yearStr = p.split('-')[0];
      const monthStr = p.split('-')[1];
      const cutoff = new Date(parseInt(yearStr), parseInt(monthStr), 0, 23, 59, 59);
      transactions.filter(t => new Date(t.date) <= cutoff).forEach(t => {
        t.lines.filter(l => l.accountId === accId).forEach(l => {
          if (acc.naturalBalance === NaturalBalance.DEBIT) b += (l.debit - l.credit);
          else b += (l.credit - l.debit);
        });
      });
      return b;
    };

    csv += "--- BALANCE SHEET ---\n";
    csv += "Account," + periods.join(",") + "\n";
    accounts.filter(a => a.financialStatement === FinancialStatement.BALANCE_SHEET).forEach(a => {
      let row = `${a.name}`;
      periods.forEach(p => row += `,${getBal(a.id, p).toFixed(2)}`);
      csv += row + "\n";
    });
    csv += "\n";

    csv += "--- INCOME STATEMENT ---\n";
    csv += "Account," + periods.join(",") + "\n";
    accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT).forEach(a => {
      let row = `${a.name}`;
      periods.forEach(p => {
        let monthAct = 0;
        transactions.filter(t => t.date.startsWith(p)).forEach(t => {
          t.lines.filter(l => l.accountId === a.id).forEach(l => {
            if (a.naturalBalance === NaturalBalance.DEBIT) monthAct += (l.debit - l.credit);
            else monthAct += (l.credit - l.debit);
          });
        });
        row += `,${monthAct.toFixed(2)}`;
      });
      csv += row + "\n";
    });
    csv += "\n";

    csv += "--- CASH FLOW SUMMARY ---\n";
    csv += "Period,Net Change in Cash\n";
    periods.forEach(p => {
      let delta = 0;
      transactions.filter(t => t.date.startsWith(p)).forEach(t => {
        t.lines.forEach(l => {
          const acc = accounts.find(a => a.id === l.accountId);
          if (acc?.name.toLowerCase().includes('cash')) {
             delta += (l.debit - l.credit);
          }
        });
      });
      csv += `${p},${delta.toFixed(2)}\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `vista_financials_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => parseCSV(event.target?.result as string);
    reader.readAsText(file);
  };

  const parseCSV = (csv: string) => {
    const lines = csv.split('\n');
    const txMap: Record<number, JournalEntry> = {};
    const newAccounts: Account[] = [];

    for (let i = 1; i < lines.length; i++) {
      if (!lines[i].trim()) continue;
      const values = lines[i].split(',').map(v => v.trim());
      const [date, method, accName, debitVal, creditVal, desc, txIdVal] = values;
      const debit = parseFloat(debitVal) || 0;
      const credit = parseFloat(creditVal) || 0;
      const txId = parseInt(txIdVal) || Math.floor(Math.random() * 10000);

      let account = accounts.find(a => a.name.toLowerCase() === accName.toLowerCase()) || newAccounts.find(a => a.name.toLowerCase() === accName.toLowerCase());
      if (!account) {
        account = {
          id: Math.random().toString(),
          name: accName,
          naturalBalance: NaturalBalance.DEBIT,
          financialStatement: FinancialStatement.BALANCE_SHEET,
          classification: AccountClassification.CURRENT_ASSET,
          startingBalance: 0
        };
        newAccounts.push(account);
      }

      if (!txMap[txId]) txMap[txId] = { id: txId, date, method, lines: [] };
      txMap[txId].lines.push({ id: Math.random().toString(), accountId: account.id, debit, credit, description: desc });
    }
    onImport(Object.values(txMap), newAccounts);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const confirmReset = (full: boolean) => {
    const msg = full 
      ? "PERMANENT DESTRUCTION: This will delete ALL accounts, transactions, and settings. Are you absolutely sure?" 
      : "TRANSACTION WIPE: This will delete ALL journal entries and history, but KEEP your current Chart of Accounts. Use this for starting a new fiscal year. Proceed?";

    if (window.confirm(msg)) {
      if (window.confirm("FINAL WARNING: This action is irreversible. Proceed?")) {
        onReset(full);
      }
    }
  };

  const handleAddMethod = () => {
    if (newMethodName.trim() && targetAccountId) {
      onAddMethod(newMethodName.trim(), targetAccountId);
      setNewMethodName('');
      setTargetAccountId('');
    } else {
      alert("Please enter a method name and select an associated ledger account.");
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 pb-20">
      {/* Report Export Center */}
      <section className="bg-indigo-50 border-2 border-indigo-100 p-10 rounded-3xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-10">
          <svg className="w-32 h-32" fill="currentColor" viewBox="0 0 24 24"><path d="M19 12v7H5v-7H3v7c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2v-7h-2zm-6 .67l2.59-2.58L17 11.5l-5 5-5-5 1.41-1.41L11 12.67V3h2v9.67z"/></svg>
        </div>
        <div className="relative z-10 space-y-6">
          <div>
            <h2 className="text-3xl font-black text-indigo-900 tracking-tighter">Report Export Center</h2>
            <p className="text-indigo-700 text-sm font-medium mt-1">Export your full financial package (BS, IS, CF) for Excel or external audits.</p>
          </div>
          <button 
            onClick={exportFinancials}
            className="bg-indigo-600 text-white px-10 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-indigo-700 shadow-xl shadow-indigo-200 transition-all active:scale-95 flex items-center gap-3"
          >
            Generate Financial Package (.CSV)
          </button>
        </div>
      </section>

      {/* Cards & Methods Setup Section */}
      <section className="bg-slate-50 border-2 border-slate-200 p-10 rounded-3xl space-y-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter flex items-center gap-3">
            <span className="text-blue-500">💳</span> Cards & Reference Accounts
          </h2>
          <p className="text-slate-500 text-sm font-medium mt-1">Stipulate which accounts correspond to specific credit cards or cash sources.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Method Alias (e.g. AmEx 1001)</label>
            <input 
              type="text" 
              value={newMethodName} 
              onChange={(e) => setNewMethodName(e.target.value)}
              className="w-full border rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 text-sm font-semibold"
              placeholder="Display Name..."
            />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Maps to Ledger Account</label>
            <div className="flex gap-2">
              <select 
                value={targetAccountId}
                onChange={(e) => setTargetAccountId(e.target.value)}
                className="flex-1 border rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 text-sm font-semibold bg-white"
              >
                <option value="">Select Account...</option>
                {eligibleAccounts.map(acc => (
                  <option key={acc.id} value={acc.id}>{acc.name} ({acc.naturalBalance})</option>
                ))}
              </select>
              <button 
                onClick={handleAddMethod}
                className="bg-blue-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-blue-700 shadow-md transition-all active:scale-95"
              >
                Link
              </button>
            </div>
          </div>
        </div>

        <div className="flex flex-wrap gap-3">
          {paymentMethods.map(m => {
            const acc = accounts.find(a => a.id === m.accountId);
            return (
              <div key={m.name} className="bg-white border border-slate-200 pl-4 pr-2 py-3 rounded-2xl flex items-center gap-6 group shadow-sm">
                <div className="flex flex-col">
                  <span className="text-sm font-black text-slate-900 uppercase tracking-tighter">{m.name}</span>
                  <span className="text-[9px] font-bold text-slate-400">{acc ? `${acc.name} (${acc.classification})` : 'Journal Only'}</span>
                </div>
                {m.name !== 'JE' && (
                  <button 
                    onClick={() => onRemoveMethod(m.name)}
                    className="text-slate-300 hover:text-red-500 transition-colors p-1"
                  >
                    ✕
                  </button>
                )}
              </div>
            );
          })}
        </div>
      </section>

      {/* Maintenance Zone */}
      <section className="bg-white border-2 border-red-50 p-10 rounded-3xl space-y-8">
        <div className="border-b-2 border-red-50 pb-4">
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter flex items-center gap-3">
            <span className="text-red-500">⚠</span> Maintenance & System Reset
          </h2>
          <p className="text-slate-500 text-sm mt-1">Tools for system migration and data cleanup.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-4 p-6 bg-slate-50 rounded-2xl border border-slate-100">
            <h3 className="font-black text-slate-800 uppercase tracking-widest text-xs">Option A: Transactional Wipe</h3>
            <p className="text-xs text-slate-500 leading-relaxed">
              Deletes all General Journal entries and Ledger history. 
              <strong> Keeps your Chart of Accounts, Classifications, and Starting Balances.</strong> 
            </p>
            <button 
              onClick={() => confirmReset(false)}
              className="w-full bg-slate-800 text-white py-3 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-slate-700 transition-colors shadow-sm"
            >
              Clear Transactions Only
            </button>
          </div>

          <div className="space-y-4 p-6 bg-red-50 rounded-2xl border border-red-100">
            <h3 className="font-black text-red-800 uppercase tracking-widest text-xs">Option B: Factory Reset</h3>
            <p className="text-xs text-red-600/70 leading-relaxed">
              Wipes the entire database clean. Returns to original default accounts.
            </p>
            <button 
              onClick={() => confirmReset(true)}
              className="w-full bg-red-600 text-white py-3 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-red-700 transition-colors shadow-lg shadow-red-100"
            >
              Destroy All Data
            </button>
          </div>
        </div>
      </section>
    </div>
  );
};

export default DataManager;

import React, { useRef, useState, useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification, PaymentMethod } from '../types';

interface Props {
  accounts: Account[];
  transactions: JournalEntry[];
  onImport: (transactions: JournalEntry[], accounts: Account[]) => void;
  onReset: (full: boolean) => void;
  paymentMethods: PaymentMethod[];
  onAddMethod: (method: string, accountId: string) => void;
  onRemoveMethod: (method: string) => void;
}

const DataManager: React.FC<Props> = ({ accounts, transactions, onImport, onReset, paymentMethods, onAddMethod, onRemoveMethod }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [newMethodName, setNewMethodName] = useState('');
  const [targetAccountId, setTargetAccountId] = useState('');

  // Refined filter to only show Cash/Bank or Credit Card related accounts
  const eligibleAccounts = accounts.filter(a => {
    const name = a.name.toLowerCase();
    const isActive = !a.isArchived;
    const isLiquidAsset = a.classification === AccountClassification.CURRENT_ASSET && 
                         (name.includes('cash') || name.includes('bank'));
    const isCreditLiability = a.classification === AccountClassification.CURRENT_LIABILITY && 
                             (name.includes('credit card') || name.includes('card') || name.includes('amex') || name.includes('visa'));

    return isActive && (isLiquidAsset || isCreditLiability);
  }).sort((a, b) => a.name.localeCompare(b.name));

  const downloadTemplate = () => {
    const headers = "Date,Method,Account Name,Debit,Credit,Description,TransactionID\n";
    const example = "2024-01-01,Setup,Cash,5000.00,0,Opening Balance,1001\n2024-01-01,Setup,Benson Contributions,0,5000.00,Initial Capital,1001";
    const blob = new Blob([headers + example], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'vista_import_template.csv';
    a.click();
  };

  const exportFinancials = () => {
    let csv = "VISTA SHORE FINANCIAL REPORT PACKAGE\n";
    csv += `Exported: ${new Date().toLocaleString()}\n\n`;

    const getPeriods = () => {
      const p = new Set<string>();
      transactions.forEach(t => p.add(t.date.slice(0, 7)));
      return Array.from(p).sort();
    };
    const periods = getPeriods();

    const getBal = (accId: string, p: string) => {
      const acc = accounts.find(a => a.id === accId);
      if (!acc) return 0;
      let b = Number(acc.startingBalance) || 0;
      const yearStr = p.split('-')[0];
      const monthStr = p.split('-')[1];
      const cutoff = new Date(parseInt(yearStr), parseInt(monthStr), 0, 23, 59, 59);
