import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
}

const BalanceSheet: React.FC<Props> = ({ transactions = [], accounts = [] }) => {
  // Derive periods from transaction data and prepend "Opening"
  const sortedPeriods = useMemo(() => {
    const periods = new Set<string>();
    transactions.forEach(tx => {
      const date = new Date(tx.date);
      if (!isNaN(date.getTime())) {
        periods.add(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`);
      }
    });
    return ["Opening", ...Array.from(periods).sort((a, b) => a.localeCompare(b))];
  }, [transactions]);

  const getCumulativeBalance = (accountId: string, upToPeriod: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let balance = Number(account.startingBalance) || 0;
    if (upToPeriod === "Opening") return balance;

    const [year, month] = upToPeriod.split('-').map(Number);
    const cutoffDate = new Date(year, month, 0, 23, 59, 59);

    transactions.forEach(tx => {
      const txDate = new Date(tx.date);
      if (txDate <= cutoffDate) {
        tx.lines.forEach(l => {
          if (l.accountId === accountId) {
            if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
            else balance += (l.credit - l.debit);
          }
        });
      }
    });
    return balance;
  };

  // New function to get ONLY the net income for a specific period (non-cumulative)
  const getNetIncomeForSpecificPeriod = (period: string) => {
    if (period === "Opening") return 0;

    const [year, month] = period.split('-').map(Number);
    const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);

    let periodNet = 0;
    transactions.forEach(tx => {
      const txDate = new Date(tx.date);
      if (txDate.getFullYear() === year && (txDate.getMonth() + 1) === month) {
        tx.lines.forEach(l => {
          const acc = isAccounts.find(a => a.id === l.accountId);
          if (acc) {
            // Revenue/Other Income increase Net Income via Credit
            if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
              periodNet += (l.credit - l.debit);
            } else {
              // Expenses decrease Net Income via Debit
              periodNet -= (l.debit - l.credit);
            }
          }
        });
      }
    });
    return periodNet;
  };

  // Helper for total equity calculation per column
  const getNetIncomeCumulative = (upToPeriod: string) => {
    if (upToPeriod === "Opening") return 0;
    const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
    let net = 0;
    isAccounts.forEach(acc => {
      const start = Number(acc.startingBalance) || 0;
      const currentBal = getCumulativeBalance(acc.id, upToPeriod);
      const activity = currentBal - start;
      if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
        net += activity;
      } else {
        net -= activity;
      }
    });
    return net;
  };

  const bsAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.BALANCE_SHEET);

  const calculateClassTotal = (classification: AccountClassification, upToPeriod: string) => {
    return bsAccounts
      .filter(a => a.classification === classification)
      .reduce((sum, a) => {
        const bal = getCumulativeBalance(a.id, upToPeriod);
        return sum + bal;
      }, 0);
  };

  // Partnership Subtotal Logic: Group accounts by prefix (e.g., "Benson - ")
  const partnerGroups = useMemo(() => {
    const equityAccounts = bsAccounts.filter(a => a.classification === AccountClassification.EQUITY);
    const groups: Record<string, Account[]> = {};
    const ungrouped: Account[] = [];

    equityAccounts.forEach(acc => {
      const parts = acc.name.split(/ - |,/);
      if (parts.length > 1) {
        const partnerName = parts[0].trim();
        if (!groups[partnerName]) groups[partnerName] = [];
        groups[partnerName].push(acc);
      } else {
        ungrouped.push(acc);
      }
    });
    return { groups, ungrouped };
  }, [bsAccounts]);

  if (sortedPeriods.length <= 1 && transactions.length === 0) {
    return (
      <div className="p-20 text-center text-slate-400 italic bg-slate-50 rounded-xl border-2 border-dashed border-slate-200">
        <p className="text-lg font-bold mb-2 text-slate-700 tracking-tight">Financial Reports Pending</p>
        <p className="text-sm">Record your first transactions to generate comparative balance sheets.</p>
      </div>
    );
  }

  return (
    <div className="w-full">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-900">Comparative Balance Sheet</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">Historical Wealth Positioning</p>
      </div>

      <div className="overflow-x-auto border rounded-2xl shadow-xl bg-white">
        <table className="w-full border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-900 text-white">
              <th className="p-4 text-left w-64 border-r border-slate-800 text-[10px] font-black uppercase tracking-widest">Account Classification</th>
              {sortedPeriods.map(p => (
                <th key={p} className={`p-4 text-right text-[10px] uppercase font-black tracking-widest border-r border-slate-800 ${p === 'Opening' ? 'bg-slate-800' : ''}`}>
                  {p === 'Opening' ? 'Opening Balance' : new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            <tr className="bg-slate-50"><td colSpan={sortedPeriods.length + 1} className="p-3 font-black text-slate-900 text-[10px] tracking-widest uppercase border-b">1. ASSETS</td></tr>

            <tr className="bg-white"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Current Assets</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
            {bsAccounts.filter(a => a.classification === AccountClassification.CURRENT_ASSET).map(acc => (
              <tr key={acc.id} className="border-b hover:bg-slate-50/50 transition-colors">
                <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                {sortedPeriods.map(p => (
                  <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 ${p === 'Opening' ? 'bg-slate-50/50 italic text-slate-400' : ''}`}>
                    {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                ))}
              </tr>
            ))}
            <tr className="font-bold bg-slate-50/50 border-t border-slate-100">
              <td className="p-2.5 pl-6 text-[10px] uppercase italic text-slate-400 border-r border-slate-100">Total Current Assets</td>
              {sortedPeriods.map(p => (
                <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 ${p === 'Opening' ? 'bg-slate-50' : ''}`}>
                  {calculateClassTotal(AccountClassification.CURRENT_ASSET, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
              ))}
            </tr>

            <tr className="bg-white"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Long-Term Assets</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
            {bsAccounts.filter(a => a.classification === AccountClassification.LONG_TERM_ASSET).map(acc => (
              <tr key={acc.id} className="border-b hover:bg-slate-50/50 transition-colors">
                <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                {sortedPeriods.map(p => (
                  <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 ${p === 'Opening' ? 'bg-slate-50/50 italic text-slate-400' : ''}`}>
                    {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                ))}
              </tr>
            ))}
            <tr className="font-bold bg-slate-50/50 border-t border-slate-100">
              <td className="p-2.5 pl-6 text-[10px] uppercase italic text-slate-400 border-r border-slate-100">Total Long-Term Assets</td>
              {sortedPeriods.map(p => (
                <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 ${p === 'Opening' ? 'bg-slate-50' : ''}`}>
                  {calculateClassTotal(AccountClassification.LONG_TERM_ASSET, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
              ))}
            </tr>

            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">TOTAL ASSETS</td>
              {sortedPeriods.map(p => {
                const total = calculateClassTotal(AccountClassification.CURRENT_ASSET, p) + calculateClassTotal(AccountClassification.LONG_TERM_ASSET, p);
                return <td key={p} className={`p-4 text-right font-mono text-sm border-r border-slate-700 ${p === 'Opening' ? 'bg-slate-800' : ''}`}>${total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>

            <tr className="h-10"></tr>

            <tr className="bg-slate-50"><td colSpan={sortedPeriods.length + 1} className="p-3 font-black text-slate-900 text-[10px] tracking-widest uppercase border-b">2. LIABILITIES & EQUITY</td></tr>

            <tr className="bg-white"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Liabilities</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
            {[AccountClassification.CURRENT_LIABILITY, AccountClassification.LONG_TERM_LIABILITY].map(cls => (
              bsAccounts.filter(a => a.classification === cls).map(acc => (
                <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                  <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                  {sortedPeriods.map(p => (
                    <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 ${p === 'Opening' ? 'bg-slate-50/50 italic text-slate-400' : ''}`}>
                      {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>
                  ))}
                </tr>
              ))
            ))}

            <tr className="bg-white border-t border-slate-100"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Partner Equity Breakdown</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>

            {/* Grouped Partners */}
            {Object.entries(partnerGroups.groups).map(([partner, accs]) => (
              <React.Fragment key={partner}>
                {accs.map(acc => (
                  <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                    <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                    {sortedPeriods.map(p => (
                      <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 ${p === 'Opening' ? 'bg-slate-50/50 italic text-slate-400' : ''}`}>
                        {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                ))}
                <tr className="bg-slate-50/30 font-black border-b border-slate-200">
                  <td className="p-2.5 pl-6 text-[10px] uppercase text-slate-800 border-r border-slate-100">Subtotal: {partner} Capital</td>
                  {sortedPeriods.map(p => {
                    const groupSum = accs.reduce((sum, a) => {
                      const bal = getCumulativeBalance(a.id, p);
                      // Equity is typically Credit, so assume Natural Balance handled in getCumulativeBalance correctly for the sum
                      return sum + bal;
                    }, 0);
                    return <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100 text-slate-900 bg-slate-100/30">${groupSum.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                  })}
                </tr>
              </React.Fragment>
            ))}

            {/* Ungrouped Equity Accounts */}
            {partnerGroups.ungrouped.map(acc => (
              <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                {sortedPeriods.map(p => (
                  <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 ${p === 'Opening' ? 'bg-slate-50/50 italic text-slate-400' : ''}`}>
                    {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                ))}
              </tr>
            ))}

            <tr className="border-b hover:bg-slate-50/50 bg-emerald-50/10">
              <td className="p-2.5 pl-8 text-xs font-black text-emerald-800 italic border-r border-slate-100">Current Period Earnings (IS)</td>
              {sortedPeriods.map(p => (
                <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 font-black ${p === 'Opening' ? 'text-slate-300 italic' : 'text-emerald-600'}`}>
                  {getNetIncomeForSpecificPeriod(p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
              ))}
            </tr>

            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">TOTAL LIABILITIES & EQUITY</td>
              {sortedPeriods.map(p => {
                const totalL = calculateClassTotal(AccountClassification.CURRENT_LIABILITY, p) + calculateClassTotal(AccountClassification.LONG_TERM_LIABILITY, p);
                const totalE = calculateClassTotal(AccountClassification.EQUITY, p) + getNetIncomeCumulative(p);
                return <td key={p} className={`p-4 text-right font-mono text-sm border-r border-slate-700 ${p === 'Opening' ? 'bg-slate-800' : ''}`}>${(totalL + totalE).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>
          </tbody>
        </table>
      </div>
      <div className="mt-4 p-4 bg-slate-50 rounded-xl border border-slate-200">
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Note: "Current Period Earnings" reflects the profit/loss of exactly that month, before any manual closing entries to partner capital accounts.</p>
      </div>
    </div>
  );
};

