import { auth, db } from './firebase';
import { JournalEntry, Account, TabType, PaymentMethod } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([{ name: 'JE', accountId: '' }]);
  const [companyName, setCompanyName] = useState('Vista Shore Products, LLC');
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
        if (parsed.paymentMethods) setPaymentMethods(parsed.paymentMethods);
        if (parsed.companyName) setCompanyName(parsed.companyName);
      } catch (e) {}
    }

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
        if (data.paymentMethods) setPaymentMethods(data.paymentMethods);
        if (data.companyName) setCompanyName(data.companyName);
        localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
          accounts: data.accounts,
          transactions: data.transactions,
          closedPeriods: data.closedPeriods || [],
          paymentMethods: data.paymentMethods || [{ name: 'JE', accountId: '' }],
          companyName: data.companyName || 'Vista Shore Products, LLC'
        }));
      } else {
        setDoc(userDocRef, { 
          accounts: INITIAL_ACCOUNTS, 
          transactions: [], 
          closedPeriods: [], 
          paymentMethods: [{ name: 'JE', accountId: '' }],
          companyName: 'Vista Shore Products, LLC'
        }).catch(err => console.error("Seeding failed:", err));
      }
      setDataLoading(false);
    }, (error) => {
      setDataLoading(false);
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = async (newAccs: Account[], newTxs: JournalEntry[], newPeriods: string[], newMethods: PaymentMethod[], newName: string) => {
    if (!user) return;
    localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods,
      paymentMethods: newMethods,
      companyName: newName
    }));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        accounts: newAccs,
        transactions: newTxs,
        closedPeriods: newPeriods,
        paymentMethods: newMethods,
        companyName: newName,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Save error:", err);
    }
  };

  const updateCompanyName = (name: string) => {
    setCompanyName(name);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, name);
  };

  const resetSystem = (full: boolean) => {
    const defaultMethods = [{ name: 'JE', accountId: '' }];
    const defaultName = 'Vista Shore Products, LLC';
    if (full) {
      setAccounts(INITIAL_ACCOUNTS);
      setTransactions([]);
      setClosedPeriods([]);
      setPaymentMethods(defaultMethods);
      setCompanyName(defaultName);
      saveToFirestore(INITIAL_ACCOUNTS, [], [], defaultMethods, defaultName);
    } else {
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(accounts, [], [], paymentMethods, companyName);
    }
    setActiveTab('Dashboard');
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName);
    }
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Permanently delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName);
    }
  };

  const addPaymentMethod = (method: string, accountId: string) => {
    if (paymentMethods.some(m => m.name === method)) return;
    const updated = [...paymentMethods, { name: method, accountId }];
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName);
  };

  const removePaymentMethod = (methodName: string) => {
    if (methodName === 'JE') return;
    const updated = paymentMethods.filter(m => m.name !== methodName);
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName);
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const existingNames = new Set(accounts.map(a => a.name.toLowerCase()));
    const uniqueNew = newAccounts.filter(a => !existingNames.has(a.name.toLowerCase()));
    const updatedAccs = [...accounts, ...uniqueNew];
    const updatedTxs = [...transactions, ...newTransactions];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods, paymentMethods, companyName);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}

      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <h1 className="text-xl font-bold tracking-tighter">VISTA SHORE</h1>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-emerald-500 transition-colors">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm text-slate-300 hover:text-white transition-colors">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto bg-slate-50">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} paymentMethods={paymentMethods} companyName={companyName} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} paymentMethods={paymentMethods} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={importData} onReset={resetSystem} paymentMethods={paymentMethods} onAddMethod={addPaymentMethod} onRemoveMethod={removePaymentMethod} companyName={companyName} onUpdateCompanyName={updateCompanyName} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import React from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification, TabType, PaymentMethod } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onNavigate: (tab: TabType) => void;
  paymentMethods: PaymentMethod[];
  companyName: string;
}

const Dashboard: React.FC<Props> = ({ transactions, accounts, onNavigate, paymentMethods, companyName }) => {
  const getBalance = (accountId: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;
    let balance = Number(account.startingBalance) || 0;
    transactions.forEach(tx => {
      tx.lines.forEach(l => {
        if (l.accountId === accountId) {
          if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
          else balance += (l.credit - l.debit);
        }
      });
    });
    return balance;
  };

  const cashAccounts = accounts.filter(a => 
    !a.isArchived &&
    a.classification === AccountClassification.CURRENT_ASSET && 
    (a.name.toLowerCase().includes('cash') || a.name.toLowerCase().includes('bank'))
  );

  const liabilityAccounts = accounts.filter(a => 
    !a.isArchived &&
    (a.classification === AccountClassification.CURRENT_LIABILITY || 
     a.classification === AccountClassification.LONG_TERM_LIABILITY)
  );

  const totalCash = cashAccounts.reduce((sum, a) => sum + getBalance(a.id), 0);
  const totalLiabilities = liabilityAccounts.reduce((sum, a) => sum + getBalance(a.id), 0);

  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
  let netIncome = 0;
  isAccounts.forEach(acc => {
    const b = getBalance(acc.id);
    const start = Number(acc.startingBalance) || 0;
    const activity = b - start;
    if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
       netIncome += activity; 
    } else {
       netIncome -= activity;
    }
  });

  return (
    <div className="space-y-10">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Dashboard</h2>
        </div>
        <div className="bg-emerald-50 px-4 py-2 rounded-full border border-emerald-100">
          <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-2">
            <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
            Cloud Sync Active
          </span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow group">
          <div className="flex justify-between items-center mb-6">
            <span className="text-3xl grayscale group-hover:grayscale-0 transition-all">💰</span>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Liquid Assets</span>
          </div>
          <p className="text-sm font-bold text-slate-500 mb-1">Total Cash Position</p>
          <p className="text-3xl font-black font-mono text-emerald-600 tracking-tighter">
            ${totalCash.toLocaleString(undefined, { minimumFractionDigits: 2 })}
          </p>
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow group">
          <div className="flex justify-between items-center mb-6">
            <span className="text-3xl grayscale group-hover:grayscale-0 transition-all">💳</span>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Total Debt</span>
          </div>
          <p className="text-sm font-bold text-slate-500 mb-1">Current Liabilities</p>
          <p className="text-3xl font-black font-mono text-amber-600 tracking-tighter">
            ${totalLiabilities.toLocaleString(undefined, { minimumFractionDigits: 2 })}
          </p>
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow group">
          <div className="flex justify-between items-center mb-6">
            <span className="text-3xl grayscale group-hover:grayscale-0 transition-all">📈</span>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Performance</span>
          </div>
          <p className="text-sm font-bold text-slate-500 mb-1">Net Income (Current Cycle)</p>
          <p className={`text-3xl font-black font-mono tracking-tighter ${netIncome >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
            ${netIncome.toLocaleString(undefined, { minimumFractionDigits: 2 })}
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
          <div className="bg-slate-50 p-6 border-b border-slate-100">
            <h3 className="text-lg font-black text-slate-800 tracking-tight flex items-center gap-2">
              <span className="w-2 h-6 bg-amber-500 rounded-full"></span>
              Credit & Liability Watchlist
            </h3>
          </div>
          <div className="p-6 space-y-4 max-h-[400px] overflow-y-auto">
            {liabilityAccounts.length === 0 ? (
              <p className="text-center py-10 text-slate-400 italic text-sm font-medium">No active cards found.</p>
            ) : (
              liabilityAccounts.map(acc => {
                const bal = getBalance(acc.id);
                return (
                  <div key={acc.id} className={`flex items-center justify-between p-4 rounded-2xl border transition-all ${bal > 0 ? 'bg-amber-50/30 border-amber-100 hover:border-amber-300' : 'bg-slate-50 border-slate-100 opacity-60 hover:opacity-100'}`}>
                    <div className="flex flex-col">
                      <span className="font-black text-slate-800">{acc.name}</span>
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{acc.classification}</span>
                    </div>
                    <div className="text-right">
                      <span className={`text-xl font-mono font-black ${bal > 0 ? 'text-amber-600' : 'text-slate-500'}`}>
                        ${bal.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </span>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
          <div className="bg-slate-50 p-6 border-b border-slate-100">
            <h3 className="text-lg font-black text-slate-800 tracking-tight flex items-center gap-2">
              <span className="w-2 h-6 bg-emerald-500 rounded-full"></span>
              Bank & Cash Breakdown
            </h3>
          </div>
          <div className="p-6 space-y-4 max-h-[400px] overflow-y-auto">
            {cashAccounts.length === 0 ? (
              <p className="text-center py-10 text-slate-400 italic text-sm font-medium">No cash accounts configured.</p>
            ) : (
              cashAccounts.map(acc => {
                const bal = getBalance(acc.id);
                return (
                  <div key={acc.id} className={`flex items-center justify-between p-4 rounded-2xl border transition-all ${bal > 0 ? 'bg-emerald-50/30 border-emerald-100 hover:border-emerald-300' : 'bg-slate-50 border-slate-100 opacity-60 hover:opacity-100'}`}>
                    <div className="flex flex-col">
                      <span className="font-black text-slate-800">{acc.name}</span>
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{acc.classification}</span>
                    </div>
                    <div className="text-right">
                      <span className={`text-xl font-mono font-black ${bal > 0 ? 'text-emerald-600' : 'text-slate-500'}`}>
                        ${bal.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </span>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 bg-slate-900 p-8 rounded-3xl text-white space-y-6">
          <h3 className="text-xl font-black tracking-tight">System Controls</h3>
          <div className="grid grid-cols-1 gap-3">
            <button onClick={() => onNavigate('Transaction Recorder')} className="w-full bg-emerald-600 hover:bg-emerald-500 p-4 rounded-2xl font-bold text-sm transition-all shadow-lg shadow-emerald-900/40 text-left flex items-center justify-between">
              Record Entry
              <span>→</span>
            </button>
            <button onClick={() => onNavigate('BS')} className="w-full bg-slate-800 hover:bg-slate-700 p-4 rounded-2xl font-bold text-sm transition-all text-left flex items-center justify-between">
              Balance Sheet
              <span>→</span>
            </button>
            <button onClick={() => onNavigate('IS')} className="w-full bg-slate-800 hover:bg-slate-700 p-4 rounded-2xl font-bold text-sm transition-all text-left flex items-center justify-between">
              Income Statement
              <span>→</span>
            </button>
          </div>
        </div>

        <div className="lg:col-span-2 bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
          <h3 className="text-xl font-black text-slate-800 tracking-tight mb-6 flex items-center gap-3">
            <span className="text-blue-500">📄</span>
            Recent Transactions
          </h3>
          <div className="space-y-3">
            {transactions.slice(-5).reverse().map(t => (
              <div key={t.id} className="group bg-slate-50 p-4 rounded-2xl border border-slate-100 flex justify-between items-center transition-all hover:border-blue-200">
                <div className="flex items-center gap-4">
                  <span className="w-10 h-10 bg-white rounded-xl flex items-center justify-center font-black text-slate-400 text-xs border border-slate-100 group-hover:border-blue-100">#{t.id}</span>
                  <div className="flex flex-col">
                    <span className="font-black text-slate-700 text-sm">{t.date}</span>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{t.method}</span>
                  </div>
                </div>
                <div className="font-mono font-black text-slate-900 text-lg">
                  ${t.lines.filter(l => l.debit > 0).reduce((s,l) => s + l.debit, 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </div>
              </div>
            ))}
            {transactions.length === 0 && (
              <div className="text-center py-12">
                <p className="text-slate-300 italic font-black uppercase tracking-widest text-xs">No ledger activity found</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';
import { STATEMENTS, STATEMENT_CLASSIFICATION_MAP } from '../constants';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onUpdateAccount: (id: string, updatedFields: Partial<Account>) => void;
  onDeleteAccount: (id: string) => void;
  onDeleteTransaction: (id: number) => void;
}

type LedgerSubTab = FinancialStatement;

const Ledgers: React.FC<Props> = ({ transactions, accounts = [], onUpdateAccount, onDeleteAccount, onDeleteTransaction }) => {
  const [activeSubTab, setActiveSubTab] = useState<LedgerSubTab>(FinancialStatement.BALANCE_SHEET);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState<Account | null>(null);

  const categorizedAccounts = useMemo(() => {
    const filtered = accounts.filter(acc => acc.financialStatement === activeSubTab);

    const classificationOrder: Record<string, number> = {
      [AccountClassification.CURRENT_ASSET]: 1,
      [AccountClassification.LONG_TERM_ASSET]: 2,
      [AccountClassification.CURRENT_LIABILITY]: 3,
      [AccountClassification.LONG_TERM_LIABILITY]: 4,
      [AccountClassification.EQUITY]: 5,
      [AccountClassification.REVENUE]: 6,
      [AccountClassification.COGS]: 7,
      [AccountClassification.OPERATING_EXPENSE]: 8,
      [AccountClassification.OTHER_INCOME_EXPENSE]: 9,
      [AccountClassification.CLEARING_ACCOUNT]: 10,
      [AccountClassification.TEMPORARY_ACCOUNT]: 11,
    };

    const grouped: Record<string, Account[]> = {};
    filtered.forEach(acc => {
      if (!grouped[acc.classification]) grouped[acc.classification] = [];
      grouped[acc.classification].push(acc);
    });

    return Object.entries(grouped).sort((a, b) => 
      (classificationOrder[a[0]] || 99) - (classificationOrder[b[0]] || 99)
    );
  }, [accounts, activeSubTab]);

  const startEditing = (account: Account) => {
    setEditingId(account.id);
    setEditDraft({ ...account });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const saveEdit = () => {
    if (editingId && editDraft) {
      onUpdateAccount(editingId, {
        name: editDraft.name.trim(),
        classification: editDraft.classification,
        naturalBalance: editDraft.naturalBalance,
        financialStatement: editDraft.financialStatement,
        startingBalance: Number(editDraft.startingBalance) || 0
      });
      cancelEditing();
    }
  };

  const updateDraft = (field: keyof Account, value: any) => {
    if (!editDraft) return;
    const newDraft = { ...editDraft, [field]: value };
    if (field === 'financialStatement') {
      const validClassifications = STATEMENT_CLASSIFICATION_MAP[value as FinancialStatement];
      if (!validClassifications.includes(newDraft.classification)) {
        newDraft.classification = validClassifications[0];
      }
    }
    setEditDraft(newDraft);
  };

  const handleDeleteAccount = (account: Account) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === account.id));
    const confirmMsg = hasData 
      ? `This account has transaction history. It will be "Archived" and hidden from new entry pickers, but preserved in ledgers. Proceed?`
      : `Are you sure you want to permanently delete the account "${account.name}"?`;

    if (window.confirm(confirmMsg)) {
      onDeleteAccount(account.id);
    }
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b pb-6">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Account Ledgers</h2>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200 shadow-sm">
          {STATEMENTS.map(statement => (
            <button
              key={statement}
              onClick={() => {
                setActiveSubTab(statement);
                cancelEditing();
              }}
              className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-tighter transition-all ${
                activeSubTab === statement 
                  ? 'bg-white text-emerald-600 shadow-sm border border-slate-200' 
                  : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              {statement}
            </button>
          ))}
        </div>
      </div>

      {categorizedAccounts.length === 0 ? (
        <div className="py-20 text-center bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
          <p className="text-slate-400 font-bold italic">No accounts configured for this category yet.</p>
        </div>
      ) : (
        <div className="space-y-12">
          {categorizedAccounts.map(([classification, accs]) => (
            <div key={classification} className="space-y-6">
              <div className="flex items-center gap-4">
                <h3 className="text-[10px] font-black uppercase tracking-[0.4em] text-slate-400 whitespace-nowrap">
                  {classification} Groups
                </h3>
                <div className="h-[1px] bg-slate-200 flex-1"></div>
              </div>

              <div className="space-y-6">
                {accs.sort((a,b) => a.name.localeCompare(b.name)).map(account => {
                  const startBal = Number(account.startingBalance) || 0;
                  const accountLines = (transactions || []).flatMap(t => 
                    t.lines
                      .filter(l => l.accountId === account.id)
                      .map(l => ({ ...l, date: t.date, txId: t.id, method: t.method }))
                  ).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

                  let runningBalance = startBal;
                  const isEditing = editingId === account.id;

                  return (
                    <div key={account.id} className={`border rounded-xl shadow-sm overflow-hidden transition-all ${account.isArchived ? 'opacity-40 grayscale' : 'hover:shadow-md'} ${account.financialStatement === FinancialStatement.OFF_STATEMENT ? 'border-amber-100' : 'border-slate-200'}`}>
                      <div className={`${isEditing ? 'bg-slate-900' : account.isArchived ? 'bg-slate-400' : account.financialStatement === FinancialStatement.OFF_STATEMENT ? 'bg-slate-700' : 'bg-slate-800'} text-white p-4 flex flex-wrap items-center justify-between gap-4 transition-colors`}>
                        <div className="flex items-center gap-4 group">
                          {isEditing && editDraft ? (
                            <div className="flex flex-wrap items-center gap-3">
                              <div className="flex flex-col">
                                <label className="text-[9px] text-emerald-400 font-black uppercase">Account Name</label>
                                <input type="text" value={editDraft.name} onChange={(e) => updateDraft('name', e.target.value)} className="bg-slate-800 text-white px-3 py-1.5 rounded border border-slate-600 text-sm font-bold w-48" />
                              </div>
                              <div className="flex flex-col">
                                <label className="text-[9px] text-emerald-400 font-black uppercase">Natural Balance</label>
                                <div className="flex bg-slate-800 border border-slate-600 rounded overflow-hidden mt-[2px]">
                                  <button onClick={() => updateDraft('naturalBalance', NaturalBalance.DEBIT)} className={`px-3 py-1 text-[10px] font-bold ${editDraft.naturalBalance === NaturalBalance.DEBIT ? 'bg-emerald-600 text-white' : 'text-slate-400 hover:text-white'}`}>DR</button>
                                  <button onClick={() => updateDraft('naturalBalance', NaturalBalance.CREDIT)} className={`px-3 py-1 text-[10px] font-bold ${editDraft.naturalBalance === NaturalBalance.CREDIT ? 'bg-amber-600 text-white' : 'text-slate-400 hover:text-white'}`}>CR</button>
                                </div>
                              </div>
                              <div className="flex flex-col">
                                <label className="text-[9px] text-emerald-400 font-black uppercase">Report Type</label>
                                <select value={editDraft.financialStatement} onChange={(e) => updateDraft('financialStatement', e.target.value as FinancialStatement)} className="bg-slate-800 text-xs font-bold border border-slate-600 px-2 py-1.5 rounded h-[34px] mt-[2px]">
                                  {STATEMENTS.map(s => <option key={s} value={s}>{s}</option>)}
                                </select>
                              </div>
                              <div className="flex flex-col">
                                <label className="text-[9px] text-emerald-400 font-black uppercase">Classification</label>
                                <select value={editDraft.classification} onChange={(e) => updateDraft('classification', e.target.value as AccountClassification)} className="bg-slate-800 text-xs font-bold border border-slate-600 px-2 py-1.5 rounded h-[34px] mt-[2px]">
                                  {STATEMENT_CLASSIFICATION_MAP[editDraft.financialStatement].map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                              </div>
                              <div className="flex flex-col">
                                <label className="text-[9px] text-emerald-400 font-black uppercase">Dictate Start Bal</label>
                                <input type="number" step="0.01" value={editDraft.startingBalance} onChange={(e) => updateDraft('startingBalance', e.target.value)} className="bg-slate-800 text-white px-2 py-1.5 rounded border border-slate-600 text-sm font-mono w-28" />
                              </div>
                              <div className="flex gap-2 ml-4 self-end pb-1">
                                <button onClick={saveEdit} className="bg-emerald-600 hover:bg-emerald-500 px-4 py-1.5 rounded text-xs font-bold shadow-lg transition-all">Save</button>
                                <button onClick={cancelEditing} className="bg-slate-700 hover:bg-slate-600 px-4 py-1.5 rounded text-xs font-bold transition-all">Cancel</button>
                              </div>
                            </div>
                          ) : (
                            <>
                              <div className="flex flex-col">
                                <h3 className="font-bold text-lg flex items-center gap-2">
                                  {account.name}
                                  {account.isArchived && <span className="text-[9px] bg-red-500/20 text-red-300 px-1.5 py-0.5 rounded uppercase tracking-widest font-black">Archived</span>}
                                </h3>
                                <div className="flex gap-2 items-center mt-0.5">
                                  <span className="text-[9px] font-black uppercase text-slate-400 bg-slate-400/10 px-1 rounded inline-block">ID: {account.id.slice(0, 4)}</span>
                                </div>
                              </div>
                              <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button onClick={() => startEditing(account)} className="text-slate-400 hover:text-white transition-all bg-white/10 p-1.5 rounded-md" title="Edit Account">
                                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" strokeWidth="2"></path></svg>
                                </button>
                                <button onClick={() => handleDeleteAccount(account)} className="text-red-400 hover:text-red-300 transition-all bg-red-500/10 p-1.5 rounded-md" title="Delete Account">
                                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                                </button>
                              </div>
                            </>
                          )}
                        </div>

                        {!isEditing && (
                          <div className="flex items-center gap-4 text-[10px] font-bold uppercase tracking-tighter">
                            <div className="flex flex-col items-end">
                              <span className="opacity-50">Opening Position</span>
                              <span className="text-sm font-mono">${startBal.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
                            </div>
                            <div className={`px-2 py-2 rounded border ${account.naturalBalance === NaturalBalance.DEBIT ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-amber-500/20 text-amber-400 border-amber-500/30'}`}>{account.naturalBalance}</div>
                          </div>
                        )}
                      </div>

                      <div className="overflow-x-auto">
                        <table className="w-full text-xs text-left border-collapse">
                          <thead className="bg-slate-50 border-b">
                            <tr>
                              <th className="p-3 border-r w-16 text-slate-500 font-black uppercase text-[9px]">TX ID</th>
                              <th className="p-3 border-r w-24 text-slate-500 font-black uppercase text-[9px]">Date</th>
                              <th className="p-3 border-r text-slate-500 font-black uppercase text-[9px]">Reference</th>
                              <th className="p-3 border-r text-right w-28 text-slate-500 font-black uppercase text-[9px]">Debit</th>
                              <th className="p-3 border-r text-right w-28 text-slate-500 font-black uppercase text-[9px]">Credit</th>
                              <th className="p-3 border-r text-right w-36 text-slate-500 font-black uppercase text-[9px]">Running Balance</th>
                              <th className="p-3 text-slate-500 font-black uppercase text-[9px]">Memo</th>
                              <th className="p-3 w-10"></th>
                            </tr>
                          </thead>
                          <tbody className="divide-y divide-slate-100">
                            <tr className="bg-slate-50/30 italic">
                              <td className="p-3 border-r text-slate-300 font-mono">-</td>
                              <td className="p-3 border-r text-slate-400">Opening</td>
                              <td className="p-3 border-r text-slate-400 uppercase text-[9px] font-bold tracking-widest italic opacity-60">Balance Brought Forward</td>
                              <td className="p-3 border-r text-right font-mono text-slate-300">-</td>
                              <td className="p-3 border-r text-right font-mono text-slate-300">-</td>
                              <td className="p-3 border-r text-right font-mono font-black text-slate-400 bg-slate-50">
                                {startBal.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                              </td>
                              <td colSpan={2} className="p-3 text-slate-400">Initial recorded position</td>
                            </tr>

                            {accountLines.length === 0 && (
                              <tr>
                                <td colSpan={8} className="p-8 text-center text-slate-400 italic font-medium">No ledger activity recorded for this account.</td>
                              </tr>
                            )}

                            {accountLines.map((line, idx) => {
                              const netChange = account.naturalBalance === NaturalBalance.DEBIT ? (line.debit - line.credit) : (line.credit - line.debit);
                              runningBalance += netChange;
                              return (
                                <tr key={`${line.txId}-${idx}`} className="group hover:bg-emerald-50/20 transition-colors">
                                  <td className="p-3 border-r font-mono text-slate-400">{line.txId}</td>
                                  <td className="p-3 border-r font-medium text-slate-700">{line.date}</td>
                                  <td className="p-3 border-r text-slate-600 truncate max-w-[120px]">{line.method || '-'}</td>
                                  <td className="p-3 border-r text-right font-mono font-bold text-emerald-600">{line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}</td>
                                  <td className="p-3 border-r text-right font-mono font-bold text-amber-600">{line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'}</td>
                                  <td className={`p-3 border-r text-right font-mono font-black bg-slate-50/30 ${runningBalance < 0 ? 'text-red-500' : 'text-slate-900'}`}>{runningBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                                  <td className="p-3 text-slate-500 italic truncate max-w-[200px]">{line.description}</td>
                                  <td className="p-3 text-center">
                                    <button onClick={() => onDeleteTransaction(line.txId)} className="opacity-0 group-hover:opacity-100 text-red-300 hover:text-red-600 transition-all font-bold">✕</button>
                                  </td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                      <div className="bg-slate-50 p-3 text-[10px] text-right text-slate-500 font-bold uppercase tracking-widest border-t flex justify-end gap-6">
                        <span className="opacity-60">Calculated Activity: {(runningBalance - startBal).toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
                        <span className="text-slate-900 bg-white px-3 py-1 rounded shadow-sm border border-slate-200">Current Balance: {runningBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Ledgers;

import React, { useState } from 'react';
import { JournalEntry, Account, JournalEntryLine } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onDelete: (id: number) => void;
  onUpdate: (entry: JournalEntry) => void;
}

const GeneralJournal: React.FC<Props> = ({ transactions, accounts, onDelete, onUpdate }) => {
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editDraft, setEditDraft] = useState<JournalEntry | null>(null);

  const accountMap = new Map<string, Account>(accounts.map(a => [a.id, a]));
  const activeAccounts = accounts.filter(a => !a.isArchived).sort((a,b) => a.name.localeCompare(b.name));
  const sortedTransactions = [...transactions].sort((a, b) => b.id - a.id);

  const startEditing = (entry: JournalEntry) => {
    setEditingId(entry.id);
    setEditDraft(JSON.parse(JSON.stringify(entry))); // Deep copy
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const updateDraftLine = (lineId: string, field: keyof JournalEntryLine, value: any) => {
    if (!editDraft) return;
    const updatedLines = editDraft.lines.map(l => l.id === lineId ? { ...l, [field]: value } : l);
    setEditDraft({ ...editDraft, lines: updatedLines });
  };

  const handleSave = () => {
    if (!editDraft) return;

    const totalDr = editDraft.lines.reduce((sum, l) => sum + (Number(l.debit) || 0), 0);
    const totalCr = editDraft.lines.reduce((sum, l) => sum + (Number(l.credit) || 0), 0);

    if (Math.abs(totalDr - totalCr) > 0.01) {
      alert(`Entry must be balanced! Difference: $${Math.abs(totalDr - totalCr).toFixed(2)}`);
      return;
    }

    onUpdate(editDraft);
    cancelEditing();
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6 border-b pb-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">General Journal</h2>
        </div>
        <div className="text-xs font-bold text-slate-400 uppercase tracking-widest">
          {transactions.length} Total Entries
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b">
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider w-16">ID</th>
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider w-32">Date</th>
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider">Account</th>
              <th className="p-4 text-right font-bold text-slate-500 uppercase tracking-wider w-32">Debit</th>
              <th className="p-4 text-right font-bold text-slate-500 uppercase tracking-wider w-32">Credit</th>
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider">Memo / Ref</th>
              <th className="p-4 w-24"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sortedTransactions.length === 0 && (
              <tr>
                <td colSpan={7} className="p-12 text-center text-slate-400 italic font-medium">No recorded journal entries found.</td>
              </tr>
            )}
            {sortedTransactions.map((entry) => {
              const isEditing = editingId === entry.id;
              const displayEntry = isEditing && editDraft ? editDraft : entry;

              return (
                <React.Fragment key={entry.id}>
                  {displayEntry.lines.map((line, idx) => {
                    const account = accountMap.get(line.accountId);
                    return (
                      <tr key={line.id} className={`group ${idx === 0 ? 'bg-slate-50/30' : 'bg-white'} ${isEditing ? 'bg-emerald-50/20' : 'hover:bg-emerald-50/30'} transition-colors`}>
                        <td className="p-4 align-top font-mono text-xs text-slate-400">
                          {idx === 0 ? entry.id : ''}
                        </td>
                        <td className="p-4 align-top text-slate-600 font-medium whitespace-nowrap">
                          {idx === 0 ? (
                            isEditing ? (
                              <input 
                                type="date" 
                                value={displayEntry.date} 
                                onChange={(e) => setEditDraft({...editDraft!, date: e.target.value})}
                                className="border rounded px-2 py-1 text-xs w-full bg-white"
                              />
                            ) : entry.date
                          ) : ''}
                        </td>
                        <td className={`p-4 font-semibold ${line.credit > 0 ? 'pl-12 text-slate-700' : 'text-slate-900'}`}>
                          {isEditing ? (
                            <select
                              value={line.accountId}
                              onChange={(e) => updateDraftLine(line.id, 'accountId', e.target.value)}
                              className="w-full border rounded px-2 py-1 text-xs font-semibold bg-white outline-none focus:ring-1 focus:ring-emerald-500"
                            >
                              <option value="">Select Account...</option>
                              {activeAccounts.map(acc => (
                                <option key={acc.id} value={acc.id}>{acc.name}</option>
                              ))}
                            </select>
                          ) : (
                            account?.name || 'Unknown Account'
                          )}
                        </td>
                        <td className="p-4 text-right font-mono font-bold text-emerald-700">
                          {isEditing ? (
                            <input 
                              type="number" 
                              step="0.01"
                              value={line.debit || ''} 
                              onChange={(e) => updateDraftLine(line.id, 'debit', parseFloat(e.target.value) || 0)}
                              className="border rounded px-2 py-1 text-xs w-full text-right bg-white"
                            />
                          ) : (
                            line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'
                          )}
                        </td>
                        <td className="p-4 text-right font-mono font-bold text-amber-700">
                          {isEditing ? (
                            <input 
                              type="number" 
                              step="0.01"
                              value={line.credit || ''} 
                              onChange={(e) => updateDraftLine(line.id, 'credit', parseFloat(e.target.value) || 0)}
                              className="border rounded px-2 py-1 text-xs w-full text-right bg-white"
                            />
                          ) : (
                            line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'
                          )}
                        </td>
                        <td className="p-4 text-slate-500 italic max-w-xs truncate">
                          {isEditing ? (
                            <input 
                              type="text" 
                              value={line.description} 
                              onChange={(e) => updateDraftLine(line.id, 'description', e.target.value)}
                              className="border rounded px-2 py-1 text-xs w-full bg-white"
                              placeholder="Memo..."
                            />
                          ) : (
                            line.description
                          )}
                          {idx === 0 && entry.method && !isEditing && (
                            <span className="not-italic text-[10px] bg-slate-100 px-1.5 py-0.5 rounded ml-2 font-bold text-slate-400 uppercase tracking-tighter">
                              {entry.method}
                            </span>
                          )}
                        </td>
                        <td className="p-4 text-right">
                          {idx === 0 && (
                            <div className="flex justify-end gap-2">
                              {isEditing ? (
                                <>
                                  <button onClick={handleSave} className="text-emerald-600 hover:text-emerald-700 transition-all font-black text-[10px] uppercase tracking-tighter bg-emerald-50 px-2 py-1 rounded border border-emerald-100 shadow-sm">Save</button>
                                  <button onClick={cancelEditing} className="text-slate-400 hover:text-slate-600 transition-all font-black text-[10px] uppercase tracking-tighter">Cancel</button>
                                </>
                              ) : (
                                <>
                                  <button 
                                    onClick={() => startEditing(entry)}
                                    className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-slate-600 transition-all p-1"
                                    title="Edit Transaction"
                                  >
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                                  </button>
                                  <button 
                                    onClick={() => onDelete(entry.id)}
                                    className="opacity-0 group-hover:opacity-100 text-red-200 hover:text-red-500 transition-all p-1"
                                    title="Delete Transaction"
                                  >
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                                  </button>
                                </>
                              )}
                            </div>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default GeneralJournal;

import React, { useMemo } from 'react';
import { JournalEntry, Account, NaturalBalance, AccountClassification, FinancialStatement } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  companyName: string;
}

const BalanceSheet: React.FC<Props> = ({ transactions = [], accounts = [], companyName }) => {
  const sortedPeriods = useMemo(() => {
    const periods = new Set<string>();
    transactions.forEach(tx => {
      const date = new Date(tx.date);
      if (!isNaN(date.getTime())) {
        periods.add(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`);
      }
    });
    return ["Opening", ...Array.from(periods).sort((a, b) => a.localeCompare(b))];
  }, [transactions]);

  const getCumulativeBalance = (accountId: string, upToPeriod: string) => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;

    let balance = Number(account.startingBalance) || 0;
    if (upToPeriod === "Opening") return balance;

    const [year, month] = upToPeriod.split('-').map(Number);
    const cutoffDate = new Date(year, month, 0, 23, 59, 59);

    transactions.forEach(tx => {
      const txDate = new Date(tx.date);
      if (txDate <= cutoffDate) {
        tx.lines.forEach(l => {
          if (l.accountId === accountId) {
            if (account.naturalBalance === NaturalBalance.DEBIT) balance += (l.debit - l.credit);
            else balance += (l.credit - l.debit);
          }
        });
      }
    });
    return balance;
  };

  const getNetIncomeForSpecificPeriod = (period: string) => {
    if (period === "Opening") return 0;

    const [year, month] = period.split('-').map(Number);
    const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);

    let periodNet = 0;
    transactions.forEach(tx => {
      const txDate = new Date(tx.date);
      if (txDate.getFullYear() === year && (txDate.getMonth() + 1) === month) {
        tx.lines.forEach(l => {
          const acc = isAccounts.find(a => a.id === l.accountId);
          if (acc) {
            if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
              periodNet += (l.credit - l.debit);
            } else {
              periodNet -= (l.debit - l.credit);
            }
          }
        });
      }
    });
    return periodNet;
  };

  const bsAccounts = accounts.filter(a => 
    a.financialStatement === FinancialStatement.BALANCE_SHEET && 
    !a.name.toLowerCase().includes('retained earnings')
  );

  const calculateClassTotal = (classification: AccountClassification, upToPeriod: string) => {
    return bsAccounts
      .filter(a => a.classification === classification)
      .reduce((sum, a) => {
        const bal = getCumulativeBalance(a.id, upToPeriod);
        if (classification === AccountClassification.EQUITY || 
            classification === AccountClassification.CURRENT_LIABILITY || 
            classification === AccountClassification.LONG_TERM_LIABILITY) {
          return sum + (a.naturalBalance === NaturalBalance.CREDIT ? bal : -bal);
        }
        return sum + bal;
      }, 0);
  };

  const partnerGroups = useMemo(() => {
    const equityAccounts = bsAccounts.filter(a => a.classification === AccountClassification.EQUITY);
    const groups: Record<string, Account[]> = {};
    const ungrouped: Account[] = [];

    equityAccounts.forEach(acc => {
      const parts = acc.name.split(/ - |,/);
      if (parts.length > 1) {
        const partnerName = parts[0].trim();
        if (!groups[partnerName]) groups[partnerName] = [];
        groups[partnerName].push(acc);
      } else {
        ungrouped.push(acc);
      }
    });
    return { groups, ungrouped };
  }, [bsAccounts]);

  if (sortedPeriods.length <= 1 && transactions.length === 0) {
    return (
      <div className="p-20 text-center text-slate-400 italic bg-slate-50 rounded-xl border-2 border-dashed border-slate-200">
        <p className="text-lg font-bold mb-2 text-slate-700 tracking-tight">Audit Pending</p>
        <p className="text-sm">Record capital contributions or expenses to generate the balance sheet.</p>
      </div>
    );
  }

  return (
    <div className="w-full">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-900">{companyName}</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">Balance Sheet</p>
      </div>

      <div className="overflow-x-auto border rounded-2xl shadow-xl bg-white">
        <table className="w-full border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-900 text-white">
              <th className="p-4 text-left w-64 border-r border-slate-800 text-[10px] font-black uppercase tracking-widest">Account Classification</th>
              {sortedPeriods.map(p => (
                <th key={p} className={`p-4 text-right text-[10px] uppercase font-black tracking-widest border-r border-slate-800 ${p === 'Opening' ? 'bg-slate-800' : ''}`}>
                  {p === 'Opening' ? 'Opening' : new Date(p + "-02").toLocaleString('default', { month: 'short', year: 'numeric' })}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            <tr className="bg-slate-50"><td colSpan={sortedPeriods.length + 1} className="p-3 font-black text-slate-900 text-[10px] tracking-widest uppercase border-b">1. ASSETS</td></tr>
            {[AccountClassification.CURRENT_ASSET, AccountClassification.LONG_TERM_ASSET].map(cls => (
              <React.Fragment key={cls}>
                <tr className="bg-white"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">{cls}s</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
                {bsAccounts.filter(a => a.classification === cls).map(acc => (
                  <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                    <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                    {sortedPeriods.map(p => (
                      <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 ${p === 'Opening' ? 'text-slate-400 italic' : ''}`}>
                        {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                ))}
              </React.Fragment>
            ))}
            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">TOTAL ASSETS</td>
              {sortedPeriods.map(p => {
                const total = calculateClassTotal(AccountClassification.CURRENT_ASSET, p) + calculateClassTotal(AccountClassification.LONG_TERM_ASSET, p);
                return <td key={p} className="p-4 text-right font-mono text-sm border-r border-slate-700">${total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>

            <tr className="h-10"></tr>

            <tr className="bg-slate-50"><td colSpan={sortedPeriods.length + 1} className="p-3 font-black text-slate-900 text-[10px] tracking-widest uppercase border-b">2. LIABILITIES & EQUITY</td></tr>
            <tr className="bg-white"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Liabilities</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>
            {[AccountClassification.CURRENT_LIABILITY, AccountClassification.LONG_TERM_LIABILITY].map(cls => (
              bsAccounts.filter(a => a.classification === cls).map(acc => (
                <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                  <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                  {sortedPeriods.map(p => (
                    <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                      {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>
                  ))}
                </tr>
              ))
            ))}

            <tr className="bg-white border-t border-slate-100"><td className="p-2 pl-4 font-bold text-slate-400 uppercase text-[9px] tracking-widest border-r">Partnership Equity</td>{sortedPeriods.map(p => <td key={p} className="border-r border-slate-100"></td>)}</tr>

            {(Object.entries(partnerGroups.groups) as [string, Account[]][]).map(([partner, accs]) => (
              <React.Fragment key={partner}>
                {accs.map(acc => (
                  <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                    <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                    {sortedPeriods.map(p => (
                      <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                        {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                      </td>
                    ))}
                  </tr>
                ))}
                <tr className="bg-slate-50/50 font-black border-b border-slate-200">
                  <td className="p-2.5 pl-6 text-[10px] uppercase text-slate-900 border-r border-slate-100">Total {partner} Capital</td>
                  {sortedPeriods.map(p => {
                    const groupSum = accs.reduce((sum, a) => {
                      const bal = getCumulativeBalance(a.id, p);
                      return sum + (a.naturalBalance === NaturalBalance.CREDIT ? bal : -bal);
                    }, 0);
                    return <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100 text-blue-700 bg-blue-50/20">${groupSum.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                  })}
                </tr>
              </React.Fragment>
            ))}

            {partnerGroups.ungrouped.map(acc => (
              <tr key={acc.id} className="border-b hover:bg-slate-50/50">
                <td className="p-2.5 pl-8 text-xs font-medium text-slate-600 border-r border-slate-100">{acc.name}</td>
                {sortedPeriods.map(p => (
                  <td key={p} className="p-2.5 text-right font-mono text-xs border-r border-slate-100">
                    {getCumulativeBalance(acc.id, p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                  </td>
                ))}
              </tr>
            ))}

            <tr className="border-b bg-emerald-50/10">
              <td className="p-2.5 pl-8 text-xs font-black text-emerald-800 italic border-r border-slate-100">Current period earnings</td>
              {sortedPeriods.map(p => (
                <td key={p} className={`p-2.5 text-right font-mono text-xs border-r border-slate-100 font-black ${p === 'Opening' ? 'text-slate-300' : 'text-emerald-600'}`}>
                  {getNetIncomeForSpecificPeriod(p).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
              ))}
            </tr>

            <tr className="bg-slate-900 text-white font-bold border-y-2 border-slate-900">
              <td className="p-4 text-xs uppercase tracking-[0.2em] border-r border-slate-700">TOTAL LIABILITIES & EQUITY</td>
              {sortedPeriods.map(p => {
                const totalL = calculateClassTotal(AccountClassification.CURRENT_LIABILITY, p) + calculateClassTotal(AccountClassification.LONG_TERM_LIABILITY, p);
                const totalE = calculateClassTotal(AccountClassification.EQUITY, p);
                const periodIncome = getNetIncomeForSpecificPeriod(p);
                return <td key={p} className="p-4 text-right font-mono text-sm border-r border-slate-700">${(totalL + totalE + periodIncome).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
              })}
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

