import React from 'react';
import { JournalEntry, Account, NaturalBalance, FinancialStatement, AccountClassification } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  companyName: string;
}

const CashFlowStatement: React.FC<Props> = ({ transactions, accounts, companyName }) => {
  const getAccountBalance = (id: string) => {
    const acc = accounts.find(a => a.id === id);
    if (!acc) return 0;
    let bal = 0;
    transactions.forEach(t => t.lines.forEach(l => {
      if (l.accountId === id) {
        if (acc.naturalBalance === NaturalBalance.DEBIT) bal += (l.debit - l.credit);
        else bal += (l.credit - l.debit);
      }
    }));
    return bal;
  };

  const isAccounts = accounts.filter(a => a.financialStatement === FinancialStatement.INCOME_STATEMENT);
  let netIncome = 0;
  isAccounts.forEach(acc => {
    const b = getAccountBalance(acc.id);
    if (acc.classification === AccountClassification.REVENUE || acc.classification === AccountClassification.OTHER_INCOME_EXPENSE) {
       netIncome += b; 
    } else {
       netIncome -= b;
    }
  });

  const depExp = accounts.find(a => a.name.toLowerCase().includes('depreciation') && a.financialStatement === FinancialStatement.INCOME_STATEMENT);
  const depAmount = depExp ? getAccountBalance(depExp.id) : 0;

  const otherCurrentAssets = accounts.filter(a => a.classification === AccountClassification.CURRENT_ASSET && a.name !== 'Cash');
  const currentLiabilities = accounts.filter(a => a.classification === AccountClassification.CURRENT_LIABILITY);

  const assetChange = otherCurrentAssets.reduce((sum, a) => sum - getAccountBalance(a.id), 0);
  const liabChange = currentLiabilities.reduce((sum, a) => sum + getAccountBalance(a.id), 0);

  const cfOps = netIncome + depAmount + assetChange + liabChange;

  const longTermAssets = accounts.filter(a => a.classification === AccountClassification.LONG_TERM_ASSET);
  const cfInvest = longTermAssets.reduce((sum, a) => sum - getAccountBalance(a.id), 0);

  const equityAccounts = accounts.filter(a => a.classification === AccountClassification.EQUITY);
  const cfFinance = equityAccounts.reduce((sum, a) => sum + getAccountBalance(a.id), 0);

  const netChangeInCash = cfOps + cfInvest + cfFinance;
  const cashAcc = accounts.find(a => a.name === 'Cash');
  const currentCash = cashAcc ? getAccountBalance(cashAcc.id) : 0;

  return (
    <div className="max-w-2xl mx-auto">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-900">{companyName}</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">Statement of Cash Flows</p>
      </div>

      <div className="space-y-6">
        <section>
          <h3 className="font-bold border-b-2 border-slate-800 pb-1 mb-2 text-[10px] uppercase tracking-widest text-slate-500">Operating Activities</h3>
          <div className="flex justify-between py-1 text-sm"><span className="pl-4 italic">Net Income / (Loss)</span> <span className="font-mono">{netIncome.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span></div>
          <div className="flex justify-between py-1 text-sm"><span className="pl-4">Add: Non-cash items (Depreciation)</span> <span className="font-mono">{depAmount.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span></div>
          <div className="flex justify-between py-1 text-sm"><span className="pl-4">Changes in Current Assets (excl. Cash)</span> <span className="font-mono">{assetChange.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span></div>
          <div className="flex justify-between py-1 text-sm"><span className="pl-4">Changes in Current Liabilities</span> <span className="font-mono">{liabChange.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span></div>
          <div className="flex justify-between py-1 font-bold border-t"><span className="">Net Cash from Operating Activities</span> <span className="font-mono">{cfOps.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span></div>
        </section>

        <section>
          <h3 className="font-bold border-b-2 border-slate-800 pb-1 mb-2 text-[10px] uppercase tracking-widest text-slate-500">Investing Activities</h3>
          <div className="flex justify-between py-1 text-sm"><span className="pl-4">Capital Expenditures / Asset Purchase</span> <span className="font-mono">{cfInvest.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span></div>
          <div className="flex justify-between py-1 font-bold border-t"><span>Net Cash from Investing Activities</span> <span className="font-mono">{cfInvest.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span></div>
        </section>

        <section>
          <h3 className="font-bold border-b-2 border-slate-800 pb-1 mb-2 text-[10px] uppercase tracking-widest text-slate-500">Financing Activities</h3>
          <div className="flex justify-between py-1 text-sm"><span className="pl-4">Owner Contributions / Financing</span> <span className="font-mono">{cfFinance.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span></div>
          <div className="flex justify-between py-1 font-bold border-t"><span>Net Cash from Financing Activities</span> <span className="font-mono">{cfFinance.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span></div>
        </section>

        <section className="bg-slate-800 text-white p-6 rounded-3xl">
          <div className="flex justify-between text-lg font-black">
            <span>NET CHANGE IN CASH</span>
            <span className="font-mono">${netChangeInCash.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
          </div>
          <div className="flex justify-between text-xs opacity-60 mt-2 font-bold uppercase tracking-widest">
            <span>Ending Cash Balance</span>
            <span className="font-mono">${currentCash.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
          </div>
        </section>
      </div>
    </div>
  );
};

