                  <table className="w-full text-xs text-left border-collapse bg-white">
                    <thead>
                      <tr className="bg-slate-900 text-white border-b">
                        <th className="p-4 font-black uppercase tracking-widest text-[10px]">Summary Item</th>
                        {periods.map(p => <th key={p} className="p-4 font-black uppercase text-right">{p}</th>)}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      <tr>
                        <td className="p-4 font-black text-slate-800">Net Amazon Transfer (Impact on Cash)</td>
                        {periods.map(p => {
                           const impact = Object.values(AMAZON_CATEGORIES).filter(c=>c!=='COGS' && c!=='COGS reversal' && c!=='Transfer').reduce((s,c)=>s+getMonthTotal(c as AmazonCategory, p), 0);
                           return <td key={p} className="p-4 text-right font-mono font-black text-emerald-600">${impact.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
