import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType, PaymentMethod, AmazonAnalysisRecord, SkuDataMap } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import AmazonAnalysis from './components/AmazonAnalysis';
import CogsManager from './components/CogsManager';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([{ name: 'JE', accountId: '' }]);
  const [companyName, setCompanyName] = useState('Vista Shore Products, LLC');
  const [amazonRecords, setAmazonRecords] = useState<AmazonAnalysisRecord[]>([]);
  const [skuData, setSkuData] = useState<SkuDataMap>({});
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
        if (parsed.paymentMethods) setPaymentMethods(parsed.paymentMethods);
        if (parsed.companyName) setCompanyName(parsed.companyName);
        if (parsed.amazonRecords) setAmazonRecords(parsed.amazonRecords);
        if (parsed.skuData) setSkuData(parsed.skuData);
      } catch (e) {}
    }

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
        if (data.paymentMethods) setPaymentMethods(data.paymentMethods);
        if (data.companyName) setCompanyName(data.companyName);
        if (data.amazonRecords) setAmazonRecords(data.amazonRecords);
        if (data.skuData) setSkuData(data.skuData);

        localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify({
          accounts: data.accounts,
          transactions: data.transactions,
          closedPeriods: data.closedPeriods || [],
          paymentMethods: data.paymentMethods || [{ name: 'JE', accountId: '' }],
          companyName: data.companyName || 'Vista Shore Products, LLC',
          amazonRecords: data.amazonRecords || [],
          skuData: data.skuData || {}
        }));
      } else {
        setDoc(userDocRef, { 
          accounts: INITIAL_ACCOUNTS, 
          transactions: [], 
          closedPeriods: [], 
          paymentMethods: [{ name: 'JE', accountId: '' }],
          companyName: 'Vista Shore Products, LLC',
          amazonRecords: [],
          skuData: {}
        }).catch(err => console.error("Seeding failed:", err));
      }
      setDataLoading(false);
    }, (error) => {
      setDataLoading(false);
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = async (
    newAccs: Account[], 
    newTxs: JournalEntry[], 
    newPeriods: string[], 
    newMethods: PaymentMethod[], 
    newName: string,
    newAmazon: AmazonAnalysisRecord[],
    newSku: SkuDataMap
  ) => {
    if (!user) return;
    const packet = {
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods,
      paymentMethods: newMethods,
      companyName: newName,
      amazonRecords: newAmazon,
      skuData: newSku
    };
    localStorage.setItem(`vista_data_${user.uid}`, JSON.stringify(packet));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        ...packet,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Save error:", err);
    }
  };

  const updateCompanyName = (name: string) => {
    setCompanyName(name);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, name, amazonRecords, skuData);
  };

  const updateAmazonRecords = (recs: AmazonAnalysisRecord[]) => {
    setAmazonRecords(recs);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, recs, skuData);
  };

  const updateSkuData = (data: SkuDataMap) => {
    setSkuData(data);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, data);
  };

  const resetSystem = (full: boolean) => {
    const defaultMethods = [{ name: 'JE', accountId: '' }];
    if (full) {
      setAccounts(INITIAL_ACCOUNTS);
      setTransactions([]);
      setClosedPeriods([]);
      setPaymentMethods(defaultMethods);
      setCompanyName('Vista Shore Products, LLC');
      setAmazonRecords([]);
      setSkuData({});
      saveToFirestore(INITIAL_ACCOUNTS, [], [], defaultMethods, 'Vista Shore Products, LLC', [], {});
    } else {
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(accounts, [], [], paymentMethods, companyName, amazonRecords, skuData);
    }
    setActiveTab('Dashboard');
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Permanently delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const addPaymentMethod = (method: string, accountId: string) => {
    const updated = [...paymentMethods, { name: method, accountId }];
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  const removePaymentMethod = (methodName: string) => {
    const updated = paymentMethods.filter(m => m.name !== methodName);
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const updatedAccs = [...accounts, ...newAccounts];
    const updatedTxs = [...transactions, ...newTransactions];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Amazon Analysis', 'COGS Manager', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}
      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <h1 className="text-xl font-bold tracking-tighter">VISTA SHORE</h1>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-emerald-500 transition-colors">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm text-slate-300 hover:text-white transition-colors">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto bg-slate-50">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} paymentMethods={paymentMethods} companyName={companyName} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} paymentMethods={paymentMethods} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Amazon Analysis' && <AmazonAnalysis skuData={skuData} records={amazonRecords} onUpdateRecords={updateAmazonRecords} companyName={companyName} />}
            {activeTab === 'COGS Manager' && <CogsManager skuData={skuData} onUpdateSkuData={updateSkuData} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={importData} onReset={resetSystem} paymentMethods={paymentMethods} onAddMethod={addPaymentMethod} onRemoveMethod={removePaymentMethod} companyName={companyName} onUpdateCompanyName={updateCompanyName} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import React, { useRef } from 'react';
import { SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  onUpdateSkuData: (data: SkuDataMap) => void;
}

const CogsManager: React.FC<Props> = ({ skuData, onUpdateSkuData }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const downloadTemplate = () => {
    const csv = "sku,item_name,unit_cogs\nSKU-123,Product Example,5.50\n";
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = "cogs_template.csv";
    a.click();
  };

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const csv = ev.target?.result as string;
      const lines = csv.split('\n');
      const newData: SkuDataMap = { ...skuData };

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const [sku, name, cost] = line.split(',').map(v => v.replace(/"/g, '').trim());
        if (sku) {
          newData[sku] = { name: name || sku, cost: parseFloat(cost) || 0 };
        }
      }
      onUpdateSkuData(newData);
      if (fileInputRef.current) fileInputRef.current.value = '';
      alert("SKU data updated successfully!");
    };
    reader.readAsText(file);
  };

  const sortedSkus = Object.keys(skuData).sort();

  return (
    <div className="space-y-8">
      <div className="flex justify-between items-end border-b pb-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">COGS Manager</h2>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Weighted Average Product Costs</p>
        </div>
        <div className="flex gap-3">
          <button onClick={downloadTemplate} className="bg-slate-100 text-slate-600 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-200 transition-all border border-slate-200">
            Get Template
          </button>
          <input type="file" ref={fileInputRef} onChange={handleUpload} accept=".csv" className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="bg-slate-900 text-white px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-slate-800 shadow-lg shadow-slate-200 transition-all active:scale-95">
            Upload CSV
          </button>
        </div>
      </div>

      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
        <table className="w-full text-sm border-collapse">
          <thead className="bg-slate-50 border-b">
            <tr>
              <th className="p-4 text-left font-black uppercase text-[10px] text-slate-400 w-1/4">SKU Code</th>
              <th className="p-4 text-left font-black uppercase text-[10px] text-slate-400">Item Name</th>
              <th className="p-4 text-right font-black uppercase text-[10px] text-slate-400 w-32">Unit Cost</th>
              <th className="p-4 w-16"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sortedSkus.length === 0 && (
              <tr>
                <td colSpan={4} className="p-12 text-center text-slate-400 italic">No SKU data configured. Upload a CSV or use the analysis tab to detect SKUs.</td>
              </tr>
            )}
            {sortedSkus.map(sku => (
              <tr key={sku} className="group hover:bg-slate-50 transition-colors">
                <td className="p-4 font-mono font-bold text-slate-900">{sku}</td>
                <td className="p-4">
                  <input 
                    type="text" value={skuData[sku].name} 
                    onChange={(e) => onUpdateSkuData({ ...skuData, [sku]: { ...skuData[sku], name: e.target.value } })}
                    className="w-full bg-transparent border-b border-transparent group-hover:border-slate-200 focus:border-emerald-500 focus:ring-0 outline-none font-medium"
                  />
                </td>
                <td className="p-4 text-right">
                  <div className="relative inline-block">
                    <span className="absolute left-2 top-2 text-xs text-slate-400">$</span>
                    <input 
                      type="number" step="0.01" value={skuData[sku].cost || ''} 
                      onChange={(e) => onUpdateSkuData({ ...skuData, [sku]: { ...skuData[sku], cost: parseFloat(e.target.value) || 0 } })}
                      className="w-24 bg-transparent border-b border-transparent group-hover:border-slate-200 focus:border-emerald-500 focus:ring-0 outline-none text-right font-mono font-bold"
                    />
                  </div>
                </td>
                <td className="p-4 text-right">
                  <button 
                    onClick={() => {
                      const next = { ...skuData };
                      delete next[sku];
                      onUpdateSkuData(next);
                    }}
                    className="text-red-300 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-all font-bold"
                  >✕</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default CogsManager;

import React, { useMemo } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  companyName: string;
}

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, companyName }) => {

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const processed: AmazonAnalysisRecord[] = [];

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line, idx) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku');
      const orderId = getVal('order id');
      const description = getVal('description');
      const qty = parseInt(getVal('quantity')) || 0;

      const parseNum = (val: string) => parseFloat(val.replace(/,/g, '').replace(/\$/g, '')) || 0;

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCredits = parseNum(getVal('shipping credits'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const giftwrapCredits = parseNum(getVal('gift wrap credits'));
      const promotionalRebates = parseNum(getVal('promotional rebates'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));

      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const other = parseNum(getVal('other'));
      const total = parseNum(getVal('total'));

      const baseInfo = { date: dateStr, sku, orderId, type, description, quantity: qty };

      const add = (cat: AmazonCategory, amt: number, q: number = 0) => {
        if (Math.abs(amt) > 0.001) {
          processed.push({ id: `rec-${Date.now()}-${idx}-${cat}-${Math.random()}`, ...baseInfo, category: cat, amount: amt, quantity: q });
        }
      };

      // ATOMIZATION LOGIC
      if (type === 'Order') {
        add('Revenue', productSales);
        add('Selling fees', sellingFees);
        add('FBA fees', fbaFees);
        // Map other transaction fees in orders often to specific labels or generic other
        if (description.toLowerCase().includes('shipping')) add('FBM shipping fees', otherTrans);
        else add('Other fees', otherTrans);

        // Handle tax logic: if it nets out to zero, we ignore it, otherwise it's 'Other'
        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) add('Other', netTax);
      } 
      else if (type === 'Refund') {
        add('Revenue', productSales); // Usually negative
        add('Selling fees', sellingFees); // Credit back
        add('FBA fees', fbaFees);
        add('Return fees', otherTrans);
      }
      else if (type === 'Adjustment') {
        if (description.toLowerCase().includes('reimbursement')) add('FBA reimbursement', total);
        else add('Other', total);
      }
      else if (type === 'Service Fee') {
        if (description.toLowerCase().includes('subscription')) add('Account subscription', total);
        else if (description.toLowerCase().includes('advertising')) add('Advertising fees', total);
        else add('Other', total);
      }
      else if (type === 'FBA Transaction fees') {
        if (description.toLowerCase().includes('storage')) add('FBA storage fees', total);
        else if (description.toLowerCase().includes('awd')) add('AWD fees', total);
        else if (description.toLowerCase().includes('disposal')) add('FBA disposal fees', total);
        else if (description.toLowerCase().includes('inbound') || description.toLowerCase().includes('transportation')) add('Inbound shipping fees', total);
        else add('FBA fees other', total);
      }
      else if (type === 'Transfer') {
        add('Transfer', total);
      }
      else if (type === 'Shipping Services') {
        add('FBM shipping fees', total);
      }
      else {
        add('Other', total);
      }
    });

    // Merge with existing records
    const merged = [...records, ...processed];
    onUpdateRecords(merged);
  };

  // HELPERS FOR PERIODS & PIVOTING
  const periods = useMemo(() => {
    const pSet = new Set<string>();
    records.forEach(r => {
      const d = new Date(r.date);
      if (!isNaN(d.getTime())) {
        const key = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;
        pSet.add(key);
      }
    });
    return Array.from(pSet).sort((a, b) => {
      const parse = (s: string) => {
        const m = s.slice(0, 3);
        const y = parseInt(s.slice(3));
        const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
        return new Date(2000 + y, months[m]).getTime();
      };
      return parse(a) - parse(b);
    });
  }, [records]);

  const allUniqueSkus = useMemo(() => {
    const set = new Set<string>();
    records.forEach(r => { if (r.sku) set.add(r.sku); });
    return Array.from(set).sort();
  }, [records]);

  const getFilteredTotal = (period: string, cat?: AmazonCategory, sku?: string, type?: string) => {
    return records.filter(r => {
      const d = new Date(r.date);
      const key = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;
      if (key !== period) return false;
      if (cat && r.category !== cat) return false;
      if (sku && r.sku !== sku) return false;
      if (type && r.type !== type) return false;
      return true;
    }).reduce((s, r) => s + r.amount, 0);
  };

  const getQtyTotal = (period: string, sku: string, type: string) => {
    return records.filter(r => {
      const d = new Date(r.date);
      const key = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;
      return key === period && r.sku === sku && r.type === type;
    }).reduce((s, r) => s + r.quantity, 0);
  };

  const clearData = () => {
    if (window.confirm("Permanently wipe all Amazon analysis data?")) {
      onUpdateRecords([]);
    }
  };

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mt-2">Multi-Month Amazon Analysis & Reconciliation</p>
        </div>
        <div className="flex gap-4">
          <button onClick={clearData} className="bg-red-50 text-red-600 px-6 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest border border-red-100 hover:bg-red-100 transition-all">Clear All Analysis</button>
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" />
          <label htmlFor="amz-upload" className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-800 shadow-xl transition-all cursor-pointer flex items-center">
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the schedules.</p>
        </div>
      ) : (
        <div className="space-y-20">

          {/* SCHEDULE 1: REVENUE BY PRODUCT */}
          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {allUniqueSkus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {periods.map(p => {
                        const val = getFilteredTotal(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">{val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}</td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {periods.map(p => <td key={p} className="p-4 text-right font-mono">${getFilteredTotal(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          {/* SCHEDULE 2: RECON REVENUE */}
          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue (Gross Orders)</td>
                    {periods.map(p => <td key={p} className="p-4 text-right font-mono">{getFilteredTotal(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {periods.map(p => {
                      const val = getFilteredTotal(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {periods.map(p => <td key={p} className="p-4 text-right font-mono">${getFilteredTotal(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          {/* SCHEDULE 3: AMAZON FEES */}
          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {[
                    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
                    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
                    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
                    'Settlement expense'
                  ].map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {periods.map(p => {
                        const val = getFilteredTotal(p, fee as AmazonCategory);
                        // FBA reimbursement and refunds are often credits in this context
                        const isCredit = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isCredit && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>{val !== 0 ? Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}</td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Amazon Fees</td>
                    {periods.map(p => {
                      const list = ['Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees', 'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other', 'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees', 'Settlement expense'];
                      const feeSum = list.reduce((s, f) => s + getFilteredTotal(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          {/* SCHEDULE 4: CONSOLIDATED RECON & COGS */}
          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-slate-900 pl-3">Net Amazon Settlement & Inventory Drain</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white border-b">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Consolidated Impact Item</th>
                    {periods.map(p => <th key={p} className="p-4 font-black uppercase text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-800">Net Amazon Calculated (Revenue - Fees)</td>
                    {periods.map(p => {
                       const netRev = getFilteredTotal(p, 'Revenue');
                       const list = ['Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees', 'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other', 'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees', 'Settlement expense'];
                       const feeSum = list.reduce((s, f) => s + getFilteredTotal(p, f as AmazonCategory), 0);
                       const calc = netRev + feeSum; // fees are usually negative
                       return <td key={p} className="p-4 text-right font-mono font-bold text-slate-900">${calc.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-800 italic">Net Amazon Transfer (Actual)</td>
                    {periods.map(p => {
                       const transfer = Math.abs(getFilteredTotal(p, 'Transfer'));
                       return <td key={p} className="p-4 text-right font-mono font-black text-emerald-600">${transfer.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-red-50 text-red-800">
                    <td className="p-4 font-black uppercase text-[10px]">Difference / Reconciling Factor</td>
                    {periods.map(p => {
                       const transfer = Math.abs(getFilteredTotal(p, 'Transfer'));
                       const netRev = getFilteredTotal(p, 'Revenue');
                       const list = ['Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees', 'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other', 'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees', 'Settlement expense'];
                       const feeSum = list.reduce((s, f) => s + getFilteredTotal(p, f as AmazonCategory), 0);
                       const calc = netRev + feeSum;
                       const diff = transfer - calc;
                       return <td key={p} className={`p-4 text-right font-mono font-black ${Math.abs(diff) > 1 ? 'text-red-600' : 'text-slate-400'}`}>${diff.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-blue-50/30">
                    <td className="p-4 font-bold text-blue-900">Total COGS (Inventory Drain)</td>
                    {periods.map(p => {
                      const cogs = allUniqueSkus.reduce((s, sku) => s + (getQtyTotal(p, sku, 'Order') * (skuData[sku]?.cost || 0)), 0);
                      return <td key={p} className="p-4 text-right font-mono text-blue-700">${cogs.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-blue-50/30">
                    <td className="p-4 font-bold text-blue-900">COGS Reversal (Returned Value)</td>
                    {periods.map(p => {
                      const rev = allUniqueSkus.reduce((s, sku) => s + (Math.abs(getQtyTotal(p, sku, 'Refund')) * (skuData[sku]?.cost || 0)), 0);
                      return <td key={p} className="p-4 text-right font-mono text-blue-400">${rev.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-50 border-t-2 border-slate-200">
                    <td className="p-4 font-black text-slate-900">Final Amazon Net Margin Contribution</td>
                    {periods.map(p => {
                       const transfer = Math.abs(getFilteredTotal(p, 'Transfer'));
                       const cogs = allUniqueSkus.reduce((s, sku) => s + (getQtyTotal(p, sku, 'Order') * (skuData[sku]?.cost || 0)), 0);
                       const rev = allUniqueSkus.reduce((s, sku) => s + (Math.abs(getQtyTotal(p, sku, 'Refund')) * (skuData[sku]?.cost || 0)), 0);
                       return <td key={p} className="p-4 text-right font-mono font-black text-slate-900">${(transfer - cogs + rev).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useState } from 'react';
import { JournalEntry, Account, JournalEntryLine } from '../types';

interface Props {
  transactions: JournalEntry[];
  accounts: Account[];
  onDelete: (id: number) => void;
  onUpdate: (entry: JournalEntry) => void;
}

const GeneralJournal: React.FC<Props> = ({ transactions, accounts, onDelete, onUpdate }) => {
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editDraft, setEditDraft] = useState<JournalEntry | null>(null);

  const accountMap = new Map<string, Account>(accounts.map(a => [a.id, a]));
  const activeAccounts = accounts.filter(a => !a.isArchived).sort((a,b) => a.name.localeCompare(b.name));
  const sortedTransactions = [...transactions].sort((a, b) => b.id - a.id);

  const startEditing = (entry: JournalEntry) => {
    setEditingId(entry.id);
    // Manual deep clone to avoid circular structure issues with JSON.stringify
    setEditDraft({
      ...entry,
      lines: entry.lines.map(line => ({ ...line }))
    });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditDraft(null);
  };

  const updateDraftLine = (lineId: string, field: keyof JournalEntryLine, value: any) => {
    if (!editDraft) return;
    const updatedLines = editDraft.lines.map(l => l.id === lineId ? { ...l, [field]: value } : l);
    setEditDraft({ ...editDraft, lines: updatedLines });
  };

  const handleSave = () => {
    if (!editDraft) return;

    const totalDr = editDraft.lines.reduce((sum, l) => sum + (Number(l.debit) || 0), 0);
    const totalCr = editDraft.lines.reduce((sum, l) => sum + (Number(l.credit) || 0), 0);

    if (Math.abs(totalDr - totalCr) > 0.01) {
      alert(`Entry must be balanced! Difference: $${Math.abs(totalDr - totalCr).toFixed(2)}`);
      return;
    }

    onUpdate(editDraft);
    cancelEditing();
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6 border-b pb-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">General Journal</h2>
        </div>
        <div className="text-xs font-bold text-slate-400 uppercase tracking-widest">
          {transactions.length} Total Entries
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b">
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider w-16">ID</th>
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider w-32">Date</th>
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider">Account</th>
              <th className="p-4 text-right font-bold text-slate-500 uppercase tracking-wider w-32">Debit</th>
              <th className="p-4 text-right font-bold text-slate-500 uppercase tracking-wider w-32">Credit</th>
              <th className="p-4 text-left font-bold text-slate-500 uppercase tracking-wider">Memo / Ref</th>
              <th className="p-4 w-24"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sortedTransactions.length === 0 && (
              <tr>
                <td colSpan={7} className="p-12 text-center text-slate-400 italic font-medium">No recorded journal entries found.</td>
              </tr>
            )}
            {sortedTransactions.map((entry) => {
              const isEditing = editingId === entry.id;
              const displayEntry = isEditing && editDraft ? editDraft : entry;

              return (
                <React.Fragment key={entry.id}>
                  {displayEntry.lines.map((line, idx) => {
                    const account = accountMap.get(line.accountId);
                    return (
                      <tr key={line.id} className={`group ${idx === 0 ? 'bg-slate-50/30' : 'bg-white'} ${isEditing ? 'bg-emerald-50/20' : 'hover:bg-emerald-50/30'} transition-colors`}>
                        <td className="p-4 align-top font-mono text-xs text-slate-400">
                          {idx === 0 ? entry.id : ''}
                        </td>
                        <td className="p-4 align-top text-slate-600 font-medium whitespace-nowrap">
                          {idx === 0 ? (
                            isEditing ? (
                              <input 
                                type="date" 
                                value={displayEntry.date} 
                                onChange={(e) => setEditDraft({...editDraft!, date: e.target.value})}
                                className="border rounded px-2 py-1 text-xs w-full bg-white"
                              />
                            ) : entry.date
                          ) : ''}
                        </td>
                        <td className={`p-4 font-semibold ${line.credit > 0 ? 'pl-12 text-slate-700' : 'text-slate-900'}`}>
                          {isEditing ? (
                            <select
                              value={line.accountId}
                              onChange={(e) => updateDraftLine(line.id, 'accountId', e.target.value)}
                              className="w-full border rounded px-2 py-1 text-xs font-semibold bg-white outline-none focus:ring-1 focus:ring-emerald-500"
                            >
                              <option value="">Select Account...</option>
                              {activeAccounts.map(acc => (
                                <option key={acc.id} value={acc.id}>{acc.name}</option>
                              ))}
                            </select>
                          ) : (
                            account?.name || 'Unknown Account'
                          )}
                        </td>
                        <td className="p-4 text-right font-mono font-bold text-emerald-700">
                          {isEditing ? (
                            <input 
                              type="number" 
                              step="0.01"
                              value={line.debit || ''} 
                              onChange={(e) => updateDraftLine(line.id, 'debit', parseFloat(e.target.value) || 0)}
                              className="border rounded px-2 py-1 text-xs w-full text-right bg-white"
                            />
                          ) : (
                            line.debit > 0 ? line.debit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'
                          )}
                        </td>
                        <td className="p-4 text-right font-mono font-bold text-amber-700">
                          {isEditing ? (
                            <input 
                              type="number" 
                              step="0.01"
                              value={line.credit || ''} 
                              onChange={(e) => updateDraftLine(line.id, 'credit', parseFloat(e.target.value) || 0)}
                              className="border rounded px-2 py-1 text-xs w-full text-right bg-white"
                            />
                          ) : (
                            line.credit > 0 ? line.credit.toLocaleString(undefined, { minimumFractionDigits: 2 }) : '-'
                          )}
                        </td>
                        <td className="p-4 text-slate-500 italic max-w-xs truncate">
                          {isEditing ? (
                            <input 
                              type="text" 
                              value={line.description} 
                              onChange={(e) => updateDraftLine(line.id, 'description', e.target.value)}
                              className="border rounded px-2 py-1 text-xs w-full bg-white"
                              placeholder="Memo..."
                            />
                          ) : (
                            line.description
                          )}
                          {idx === 0 && entry.method && !isEditing && (
                            <span className="not-italic text-[10px] bg-slate-100 px-1.5 py-0.5 rounded ml-2 font-bold text-slate-400 uppercase tracking-tighter">
                              {entry.method}
                            </span>
                          )}
                        </td>
                        <td className="p-4 text-right">
                          {idx === 0 && (
                            <div className="flex justify-end gap-2">
                              {isEditing ? (
                                <>
                                  <button onClick={handleSave} className="text-emerald-600 hover:text-emerald-700 transition-all font-black text-[10px] uppercase tracking-tighter bg-emerald-50 px-2 py-1 rounded border border-emerald-100 shadow-sm">Save</button>
                                  <button onClick={cancelEditing} className="text-slate-400 hover:text-slate-600 transition-all font-black text-[10px] uppercase tracking-tighter">Cancel</button>
                                </>
                              ) : (
                                <>
                                  <button 
                                    onClick={() => startEditing(entry)}
                                    className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-slate-600 transition-all p-1"
                                    title="Edit Transaction"
                                  >
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                                  </button>
                                  <button 
                                    onClick={() => onDelete(entry.id)}
                                    className="opacity-0 group-hover:opacity-100 text-red-200 hover:text-red-500 transition-all p-1"
                                    title="Delete Transaction"
                                  >
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                                  </button>
                                </>
                              )}
                            </div>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default GeneralJournal;

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType, PaymentMethod, AmazonAnalysisRecord, SkuDataMap } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import AmazonAnalysis from './components/AmazonAnalysis';
import CogsManager from './components/CogsManager';
import Login from './components/Login';

// Utility for safe JSON stringification that skips circular references
const safeStringify = (obj: any) => {
  const cache = new WeakSet();
  return JSON.stringify(obj, (key, value) => {
    if (typeof value === 'object' && value !== null) {
      if (cache.has(value)) return;
      cache.add(value);
    }
    return value;
  });
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [dataLoading, setDataLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([{ name: 'JE', accountId: '' }]);
  const [companyName, setCompanyName] = useState('Vista Shore Products, LLC');
  const [amazonRecords, setAmazonRecords] = useState<AmazonAnalysisRecord[]>([]);
  const [skuData, setSkuData] = useState<SkuDataMap>({});
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
        if (parsed.paymentMethods) setPaymentMethods(parsed.paymentMethods);
        if (parsed.companyName) setCompanyName(parsed.companyName);
        if (parsed.amazonRecords) setAmazonRecords(parsed.amazonRecords);
        if (parsed.skuData) setSkuData(parsed.skuData);
      } catch (e) {}
    }

    setDataLoading(true);
    const userDocRef = doc(db, 'users', user.uid);

    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
        if (data.paymentMethods) setPaymentMethods(data.paymentMethods);
        if (data.companyName) setCompanyName(data.companyName);
        if (data.amazonRecords) setAmazonRecords(data.amazonRecords);
        if (data.skuData) setSkuData(data.skuData);

        localStorage.setItem(`vista_data_${user.uid}`, safeStringify({
          accounts: data.accounts,
          transactions: data.transactions,
          closedPeriods: data.closedPeriods || [],
          paymentMethods: data.paymentMethods || [{ name: 'JE', accountId: '' }],
          companyName: data.companyName || 'Vista Shore Products, LLC',
          amazonRecords: data.amazonRecords || [],
          skuData: data.skuData || {}
        }));
      } else {
        setDoc(userDocRef, { 
          accounts: INITIAL_ACCOUNTS, 
          transactions: [], 
          closedPeriods: [], 
          paymentMethods: [{ name: 'JE', accountId: '' }],
          companyName: 'Vista Shore Products, LLC',
          amazonRecords: [],
          skuData: {}
        }).catch(err => console.error("Seeding failed:", err));
      }
      setDataLoading(false);
    }, (error) => {
      setDataLoading(false);
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = async (
    newAccs: Account[], 
    newTxs: JournalEntry[], 
    newPeriods: string[], 
    newMethods: PaymentMethod[], 
    newName: string,
    newAmazon: AmazonAnalysisRecord[],
    newSku: SkuDataMap
  ) => {
    if (!user) return;
    const packet = {
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods,
      paymentMethods: newMethods,
      companyName: newName,
      amazonRecords: newAmazon,
      skuData: newSku
    };
    localStorage.setItem(`vista_data_${user.uid}`, safeStringify(packet));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        ...packet,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Save error:", err);
    }
  };

  const updateCompanyName = (name: string) => {
    setCompanyName(name);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, name, amazonRecords, skuData);
  };

  const updateAmazonRecords = (recs: AmazonAnalysisRecord[]) => {
    setAmazonRecords(recs);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, recs, skuData);
  };

  const updateSkuData = (data: SkuDataMap) => {
    setSkuData(data);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, data);
  };

  const resetSystem = (full: boolean) => {
    const defaultMethods = [{ name: 'JE', accountId: '' }];
    if (full) {
      setAccounts(INITIAL_ACCOUNTS);
      setTransactions([]);
      setClosedPeriods([]);
      setPaymentMethods(defaultMethods);
      setCompanyName('Vista Shore Products, LLC');
      setAmazonRecords([]);
      setSkuData({});
      saveToFirestore(INITIAL_ACCOUNTS, [], [], defaultMethods, 'Vista Shore Products, LLC', [], {});
    } else {
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(accounts, [], [], paymentMethods, companyName, amazonRecords, skuData);
    }
    setActiveTab('Dashboard');
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Permanently delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const addPaymentMethod = (method: string, accountId: string) => {
    const updated = [...paymentMethods, { name: method, accountId }];
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  const removePaymentMethod = (methodName: string) => {
    const updated = paymentMethods.filter(m => m.name !== methodName);
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const updatedAccs = [...accounts, ...newAccounts];
    const updatedTxs = [...transactions, ...newTransactions];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Amazon Analysis', 'COGS Manager', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}
      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <h1 className="text-xl font-bold tracking-tighter">VISTA SHORE</h1>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-emerald-500 transition-colors">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm text-slate-300 hover:text-white transition-colors">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto bg-slate-50">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} paymentMethods={paymentMethods} companyName={companyName} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} paymentMethods={paymentMethods} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Amazon Analysis' && <AmazonAnalysis skuData={skuData} records={amazonRecords} onUpdateRecords={updateAmazonRecords} companyName={companyName} />}
            {activeTab === 'COGS Manager' && <CogsManager skuData={skuData} onUpdateSkuData={updateSkuData} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={importData} onReset={resetSystem} paymentMethods={paymentMethods} onAddMethod={addPaymentMethod} onRemoveMethod={removePaymentMethod} companyName={companyName} onUpdateCompanyName={updateCompanyName} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  companyName: string;
}

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, companyName }) => {

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    // Using a Map for O(1) aggregation during parsing
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description');
      const qty = parseInt(getVal('quantity')) || 0;

      // Group by MonthYear
      const d = new Date(dateStr);
      if (isNaN(d.getTime())) return;
      const periodKey = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;

      const parseNum = (val: string) => parseFloat(val.replace(/,/g, '').replace(/\$/g, '')) || 0;

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;

        // Key includes specificType for Gross/Net recon logic
        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);

        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}`,
            date: dateStr, // Used for period parsing later
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      // ATOMIZATION LOGIC (Now aggregated)
      if (type === 'Order') {
        addToSummary('Revenue', productSales);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (description.toLowerCase().includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (type === 'Refund') {
        addToSummary('Revenue', productSales);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (type === 'Adjustment') {
        if (description.toLowerCase().includes('reimbursement')) addToSummary('FBA reimbursement', total);
        else addToSummary('Other', total);
      }
      else if (type === 'Service Fee') {
        if (description.toLowerCase().includes('subscription')) addToSummary('Account subscription', total);
        else if (description.toLowerCase().includes('advertising')) addToSummary('Advertising fees', total);
        else addToSummary('Other', total);
      }
      else if (type === 'FBA Transaction fees') {
        if (description.toLowerCase().includes('storage')) addToSummary('FBA storage fees', total);
        else if (description.toLowerCase().includes('awd')) addToSummary('AWD fees', total);
        else if (description.toLowerCase().includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (description.toLowerCase().includes('inbound') || description.toLowerCase().includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (type === 'Transfer') addToSummary('Transfer', total);
      else if (type === 'Shipping Services') addToSummary('FBM shipping fees', total);
      else addToSummary('Other', total);
    });

    // Merge logic: Combine new aggregated records with old ones
    // We update values for keys that already exist in the stored state
    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const d = new Date(r.date);
      const pk = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      currentMap.set(key, r);
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  // PIVOT TABLES (Pre-calculated for O(1) rendering)
  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();

    // Primary Lookup Structure: [period][category][sku][type]
    const amountMap: any = {};
    const qtyMap: any = {};

    records.forEach(r => {
      const d = new Date(r.date);
      const pk = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;
      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!qtyMap[pk]) qtyMap[pk] = {};
      if (!qtyMap[pk][r.sku]) qtyMap[pk][r.sku] = {};
      if (!qtyMap[pk][r.sku][r.type]) qtyMap[pk][r.sku][r.type] = 0;
      qtyMap[pk][r.sku][r.type] += r.quantity;
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const parse = (s: string) => {
        const m = s.slice(0, 3);
        const y = parseInt(s.slice(3));
        const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
        return new Date(2000 + y, months[m]).getTime();
      };
      return parse(a) - parse(b);
    });

    return { 
      periods: sortedPeriods, 
      skus: Array.from(skuSet).sort(),
      amountMap,
      qtyMap
    };
  }, [records]);

  // HIGH PERFORMANCE CELL LOOKUPS
  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;
    if (!sku) return p[cat]._total;
    if (!p[cat][sku]) return 0;
    if (!type) {
      return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    }
    return p[cat][sku][type] || 0;
  };

  const getQty = (period: string, sku: string, type: string) => {
    return pivotData.qtyMap[period]?.[sku]?.[type] || 0;
  };

  const clearData = () => {
    if (window.confirm("Permanently wipe all Amazon analysis data?")) {
      onUpdateRecords([]);
    }
  };

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mt-2">Aggregated Multi-Month Amazon Reconciliation</p>
        </div>
        <div className="flex gap-4">
          <button onClick={clearData} className="bg-red-50 text-red-600 px-6 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest border border-red-100 hover:bg-red-100 transition-all">Wipe History</button>
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" />
          <label htmlFor="amz-upload" className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-800 shadow-xl transition-all cursor-pointer flex items-center">
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20">

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {pivotData.skus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">{val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}</td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue (Gross Orders)</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {FEE_LIST.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isCredit = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isCredit && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>{val !== 0 ? Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}</td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-slate-900 pl-3">Net Amazon Settlement & Inventory Drain</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white border-b">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Consolidated Impact Item</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black uppercase text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-800">Net Amazon Calculated (Revenue - Fees)</td>
                    {pivotData.periods.map(p => {
                       const netRev = getAmt(p, 'Revenue');
                       const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                       const calc = netRev + feeSum;
                       return <td key={p} className="p-4 text-right font-mono font-bold text-slate-900">${calc.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-800 italic">Net Amazon Transfer (Actual)</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       return <td key={p} className="p-4 text-right font-mono font-black text-emerald-600">${transfer.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-red-50 text-red-800">
                    <td className="p-4 font-black uppercase text-[10px]">Difference / Reconciling Factor</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       const netRev = getAmt(p, 'Revenue');
                       const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                       const diff = transfer - (netRev + feeSum);
                       return <td key={p} className={`p-4 text-right font-mono font-black ${Math.abs(diff) > 1 ? 'text-red-600' : 'text-slate-400'}`}>${diff.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-blue-50/30">
                    <td className="p-4 font-bold text-blue-900">Total COGS (Inventory Drain)</td>
                    {pivotData.periods.map(p => {
                      const cogs = pivotData.skus.reduce((s, sku) => s + (getQty(p, sku, 'Order') * (skuData[sku]?.cost || 0)), 0);
                      return <td key={p} className="p-4 text-right font-mono text-blue-700">${cogs.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-blue-50/30">
                    <td className="p-4 font-bold text-blue-900">COGS Reversal (Returned Value)</td>
                    {pivotData.periods.map(p => {
                      const rev = pivotData.skus.reduce((s, sku) => s + (Math.abs(getQty(p, sku, 'Refund')) * (skuData[sku]?.cost || 0)), 0);
                      return <td key={p} className="p-4 text-right font-mono text-blue-400">${rev.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-50 border-t-2 border-slate-200">
                    <td className="p-4 font-black text-slate-900">Final Amazon Net Margin Contribution</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       const cogs = pivotData.skus.reduce((s, sku) => s + (getQty(p, sku, 'Order') * (skuData[sku]?.cost || 0)), 0);
                       const rev = pivotData.skus.reduce((s, sku) => s + (Math.abs(getQty(p, sku, 'Refund')) * (skuData[sku]?.cost || 0)), 0);
                       return <td key={p} className="p-4 text-right font-mono font-black text-slate-900">${(transfer - cogs + rev).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;

import React, { useState, useEffect, useRef } from 'react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { doc, setDoc, onSnapshot } from 'firebase/firestore';
import { auth, db } from './firebase';
import { JournalEntry, Account, TabType, PaymentMethod, AmazonAnalysisRecord, SkuDataMap } from './types';
import { INITIAL_ACCOUNTS } from './constants';
import TransactionRecorder from './components/TransactionRecorder';
import GeneralJournal from './components/GeneralJournal';
import Ledgers from './components/Ledgers';
import BalanceSheet from './components/BalanceSheet';
import IncomeStatement from './components/IncomeStatement';
import CashFlowStatement from './components/CashFlowStatement';
import TrialBalance from './components/TrialBalance';
import AccountModal from './components/AccountModal';
import Dashboard from './components/Dashboard';
import DataManager from './components/DataManager';
import AmazonAnalysis from './components/AmazonAnalysis';
import CogsManager from './components/CogsManager';
import Login from './components/Login';

const safeStringify = (obj: any) => {
  const cache = new WeakSet();
  return JSON.stringify(obj, (key, value) => {
    if (typeof value === 'object' && value !== null) {
      if (cache.has(value)) return;
      cache.add(value);
    }
    return value;
  });
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabType>('Dashboard');
  const [accounts, setAccounts] = useState<Account[]>(INITIAL_ACCOUNTS);
  const [transactions, setTransactions] = useState<JournalEntry[]>([]);
  const [closedPeriods, setClosedPeriods] = useState<string[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([{ name: 'JE', accountId: '' }]);
  const [companyName, setCompanyName] = useState('Vista Shore Products, LLC');
  const [amazonRecords, setAmazonRecords] = useState<AmazonAnalysisRecord[]>([]);
  const [skuData, setSkuData] = useState<SkuDataMap>({});
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);

  // Use a ref to track if we are currently performing a local update to prevent sync loops
  const isUpdatingRef = useRef(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const localData = localStorage.getItem(`vista_data_${user.uid}`);
    if (localData) {
      try {
        const parsed = JSON.parse(localData);
        if (parsed.accounts) setAccounts(parsed.accounts);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.closedPeriods) setClosedPeriods(parsed.closedPeriods);
        if (parsed.paymentMethods) setPaymentMethods(parsed.paymentMethods);
        if (parsed.companyName) setCompanyName(parsed.companyName);
        if (parsed.amazonRecords) setAmazonRecords(parsed.amazonRecords);
        if (parsed.skuData) setSkuData(parsed.skuData);
      } catch (e) {}
    }

    const userDocRef = doc(db, 'users', user.uid);
    const unsubscribe = onSnapshot(userDocRef, (docSnap) => {
      // If we are currently pushing an update, ignore the incoming snapshot to prevent jitter
      if (isUpdatingRef.current) return;

      setCloudError(null);
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.closedPeriods) setClosedPeriods(data.closedPeriods);
        if (data.paymentMethods) setPaymentMethods(data.paymentMethods);
        if (data.companyName) setCompanyName(data.companyName);
        if (data.amazonRecords) setAmazonRecords(data.amazonRecords);
        if (data.skuData) setSkuData(data.skuData);

        localStorage.setItem(`vista_data_${user.uid}`, safeStringify(data));
      }
    }, (error) => {
      setCloudError(`Cloud Sync Issue: ${error.message}`);
    });

    return () => unsubscribe();
  }, [user]);

  const saveToFirestore = async (
    newAccs: Account[], 
    newTxs: JournalEntry[], 
    newPeriods: string[], 
    newMethods: PaymentMethod[], 
    newName: string,
    newAmazon: AmazonAnalysisRecord[],
    newSku: SkuDataMap
  ) => {
    if (!user) return;
    isUpdatingRef.current = true;

    const packet = {
      accounts: newAccs,
      transactions: newTxs,
      closedPeriods: newPeriods,
      paymentMethods: newMethods,
      companyName: newName,
      amazonRecords: newAmazon,
      skuData: newSku
    };

    localStorage.setItem(`vista_data_${user.uid}`, safeStringify(packet));

    try {
      await setDoc(doc(db, 'users', user.uid), {
        ...packet,
        lastUpdated: new Date().toISOString()
      }, { merge: true });
    } catch (err: any) {
      console.error("Save error:", err);
      setCloudError("Failed to save to cloud. Check your connection.");
    } finally {
      // Small delay to ensure the onSnapshot loop has settled
      setTimeout(() => { isUpdatingRef.current = false; }, 500);
    }
  };

  const updateAmazonRecords = (recs: AmazonAnalysisRecord[]) => {
    setAmazonRecords(recs);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, recs, skuData);
  };

  const updateCompanyName = (name: string) => {
    setCompanyName(name);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, name, amazonRecords, skuData);
  };

  const updateSkuData = (data: SkuDataMap) => {
    setSkuData(data);
    saveToFirestore(accounts, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, data);
  };

  const resetSystem = (full: boolean) => {
    const defaultMethods = [{ name: 'JE', accountId: '' }];
    if (full) {
      setAccounts(INITIAL_ACCOUNTS);
      setTransactions([]);
      setClosedPeriods([]);
      setPaymentMethods(defaultMethods);
      setCompanyName('Vista Shore Products, LLC');
      setAmazonRecords([]);
      setSkuData({});
      saveToFirestore(INITIAL_ACCOUNTS, [], [], defaultMethods, 'Vista Shore Products, LLC', [], {});
    } else {
      setTransactions([]);
      setClosedPeriods([]);
      saveToFirestore(accounts, [], [], paymentMethods, companyName, amazonRecords, skuData);
    }
    setActiveTab('Dashboard');
  };

  const addAccount = (newAcc: Account) => {
    const updated = [...accounts, newAcc];
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateAccount = (id: string, updatedFields: Partial<Account>) => {
    const updated = accounts.map(acc => acc.id === id ? { ...acc, ...updatedFields } : acc);
    setAccounts(updated);
    saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteAccount = (id: string) => {
    const hasData = transactions.some(t => t.lines.some(l => l.accountId === id));
    if (hasData) {
      updateAccount(id, { isArchived: true });
    } else {
      const updated = accounts.filter(acc => acc.id !== id);
      setAccounts(updated);
      saveToFirestore(updated, transactions, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const recordTransaction = (entry: JournalEntry) => {
    const updated = [...transactions, entry];
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const updateTransaction = (updatedEntry: JournalEntry) => {
    const updated = transactions.map(t => t.id === updatedEntry.id ? updatedEntry : t);
    setTransactions(updated);
    saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  const deleteTransaction = (id: number) => {
    if (window.confirm(`Permanently delete Transaction #${id}?`)) {
      const updated = transactions.filter(t => t.id !== id);
      setTransactions(updated);
      saveToFirestore(accounts, updated, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
    }
  };

  const addPaymentMethod = (method: string, accountId: string) => {
    const updated = [...paymentMethods, { name: method, accountId }];
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  const removePaymentMethod = (methodName: string) => {
    const updated = paymentMethods.filter(m => m.name !== methodName);
    setPaymentMethods(updated);
    saveToFirestore(accounts, transactions, closedPeriods, updated, companyName, amazonRecords, skuData);
  };

  const importData = (newTransactions: JournalEntry[], newAccounts: Account[]) => {
    const updatedAccs = [...accounts, ...newAccounts];
    const updatedTxs = [...transactions, ...newTransactions];
    setAccounts(updatedAccs);
    setTransactions(updatedTxs);
    saveToFirestore(updatedAccs, updatedTxs, closedPeriods, paymentMethods, companyName, amazonRecords, skuData);
  };

  if (authLoading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><div className="animate-pulse w-12 h-12 bg-emerald-500 rounded-lg"></div></div>;
  if (!user) return <Login />;

  const tabs: TabType[] = ['Dashboard', 'Transaction Recorder', 'Ledgers', 'General Journal', 'BS', 'IS', 'CF', 'Trial Balance', 'Amazon Analysis', 'COGS Manager', 'Data Manager'];

  return (
    <div className="min-h-screen flex flex-col">
      {cloudError && <div className="bg-amber-600 text-white px-4 py-2 text-[10px] font-bold text-center">{cloudError}</div>}
      <header className="bg-slate-900 text-white p-4 shadow-lg flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-lg"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2"></path></svg></div>
          <h1 className="text-xl font-bold tracking-tighter text-white">VISTA SHORE</h1>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowAccountModal(true)} className="bg-emerald-600 px-4 py-2 rounded text-sm font-bold shadow-md hover:bg-emerald-500 transition-colors text-white">+ New Account</button>
          <button onClick={() => signOut(auth)} className="bg-slate-800 px-4 py-2 rounded text-sm text-slate-300 hover:text-white transition-colors">Logout</button>
        </div>
      </header>

      <nav className="bg-white border-b flex overflow-x-auto no-scrollbar shadow-sm sticky top-[72px] z-40">
        {tabs.map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-4 text-xs font-bold whitespace-nowrap transition-all border-b-4 ${activeTab === tab ? 'border-emerald-500 text-emerald-600 bg-emerald-50/50' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>{tab}</button>
        ))}
      </nav>

      <main className="flex-1 p-6 overflow-y-auto bg-slate-50">
        <div className="max-w-7xl mx-auto">
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8 min-h-[600px]">
            {activeTab === 'Dashboard' && <Dashboard transactions={transactions} accounts={accounts} onNavigate={setActiveTab} paymentMethods={paymentMethods} companyName={companyName} />}
            {activeTab === 'Transaction Recorder' && <TransactionRecorder accounts={accounts} onRecord={recordTransaction} lastId={transactions.length > 0 ? Math.max(...transactions.map(t => t.id)) : 0} paymentMethods={paymentMethods} />}
            {activeTab === 'General Journal' && <GeneralJournal transactions={transactions} accounts={accounts} onDelete={deleteTransaction} onUpdate={updateTransaction} />}
            {activeTab === 'Ledgers' && <Ledgers transactions={transactions} accounts={accounts} onUpdateAccount={updateAccount} onDeleteAccount={deleteAccount} onDeleteTransaction={deleteTransaction} />}
            {activeTab === 'BS' && <BalanceSheet transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'IS' && <IncomeStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'CF' && <CashFlowStatement transactions={transactions} accounts={accounts} companyName={companyName} />}
            {activeTab === 'Trial Balance' && <TrialBalance transactions={transactions} accounts={accounts} />}
            {activeTab === 'Amazon Analysis' && <AmazonAnalysis skuData={skuData} records={amazonRecords} onUpdateRecords={updateAmazonRecords} companyName={companyName} />}
            {activeTab === 'COGS Manager' && <CogsManager skuData={skuData} onUpdateSkuData={updateSkuData} />}
            {activeTab === 'Data Manager' && <DataManager accounts={accounts} transactions={transactions} onImport={importData} onReset={resetSystem} paymentMethods={paymentMethods} onAddMethod={addPaymentMethod} onRemoveMethod={removePaymentMethod} companyName={companyName} onUpdateCompanyName={updateCompanyName} />}
          </div>
        </div>
      </main>
      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onSave={addAccount} />}
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { AmazonAnalysisRecord, AmazonCategory, SkuDataMap } from '../types';

interface Props {
  skuData: SkuDataMap;
  records: AmazonAnalysisRecord[];
  onUpdateRecords: (recs: AmazonAnalysisRecord[]) => void;
  companyName: string;
}

const AmazonAnalysis: React.FC<Props> = ({ skuData, records, onUpdateRecords, companyName }) => {

  const processAmazonCSV = (csv: string) => {
    const lines = csv.split('\n');
    const summaryMap = new Map<string, AmazonAnalysisRecord>();

    let headerIdx = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes('date/time') && lines[i].toLowerCase().includes('type')) {
        headerIdx = i;
        break;
      }
    }

    if (headerIdx === -1) {
      alert("Format Error: Ensure this is a raw Amazon Settlement report.");
      return;
    }

    const headers = lines[headerIdx].split(',').map(h => h.replace(/"/g, '').trim());
    const dataLines = lines.slice(headerIdx + 1);

    dataLines.forEach((line) => {
      if (!line.trim()) return;
      const values = line.match(/(".*?"|[^,]+)/g)?.map(v => v.replace(/"/g, '').trim()) || [];
      if (values.length < 5) return;

      const getVal = (name: string) => {
        const i = headers.findIndex(h => h.toLowerCase() === name.toLowerCase());
        return i !== -1 ? values[i] : '';
      };

      const dateStr = getVal('date/time');
      const type = getVal('type');
      const sku = getVal('sku') || 'NON-SKU';
      const description = getVal('description');
      const qty = parseInt(getVal('quantity')) || 0;

      const d = new Date(dateStr);
      if (isNaN(d.getTime())) return;
      const periodKey = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;

      const parseNum = (val: string) => parseFloat(val.replace(/,/g, '').replace(/\$/g, '')) || 0;

      const productSales = parseNum(getVal('product sales'));
      const productSalesTax = parseNum(getVal('product sales tax'));
      const shippingCreditsTax = parseNum(getVal('shipping credits tax'));
      const marketplaceTax = parseNum(getVal('marketplace withheld tax'));
      const sellingFees = parseNum(getVal('selling fees'));
      const fbaFees = parseNum(getVal('fba fees'));
      const otherTrans = parseNum(getVal('other transaction fees'));
      const total = parseNum(getVal('total'));

      const addToSummary = (cat: AmazonCategory, amt: number, q: number = 0, specificType?: string) => {
        if (Math.abs(amt) < 0.001 && q === 0) return;

        const key = `${periodKey}|${sku}|${cat}|${specificType || type}`;
        const existing = summaryMap.get(key);

        if (existing) {
          existing.amount += amt;
          existing.quantity += q;
        } else {
          summaryMap.set(key, {
            id: `agg-${key}-${Math.random().toString(36).substr(2, 9)}`,
            date: dateStr,
            sku,
            orderId: 'SUMMARY',
            type: specificType || type,
            description: 'Summary Entry',
            category: cat,
            amount: amt,
            quantity: q
          });
        }
      };

      if (type === 'Order') {
        addToSummary('Revenue', productSales);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        if (description.toLowerCase().includes('shipping')) addToSummary('FBM shipping fees', otherTrans);
        else addToSummary('Other fees', otherTrans);

        const netTax = productSalesTax + marketplaceTax + shippingCreditsTax;
        if (Math.abs(netTax) > 0.01) addToSummary('Other', netTax);
      } 
      else if (type === 'Refund') {
        addToSummary('Revenue', productSales);
        addToSummary('Selling fees', sellingFees);
        addToSummary('FBA fees', fbaFees);
        addToSummary('Return fees', otherTrans);
      }
      else if (type === 'Adjustment') {
        if (description.toLowerCase().includes('reimbursement')) addToSummary('FBA reimbursement', total);
        else addToSummary('Other', total);
      }
      else if (type === 'Service Fee') {
        if (description.toLowerCase().includes('subscription')) addToSummary('Account subscription', total);
        else if (description.toLowerCase().includes('advertising')) addToSummary('Advertising fees', total);
        else addToSummary('Other', total);
      }
      else if (type === 'FBA Transaction fees') {
        if (description.toLowerCase().includes('storage')) addToSummary('FBA storage fees', total);
        else if (description.toLowerCase().includes('awd')) addToSummary('AWD fees', total);
        else if (description.toLowerCase().includes('disposal')) addToSummary('FBA disposal fees', total);
        else if (description.toLowerCase().includes('inbound') || description.toLowerCase().includes('transportation')) addToSummary('Inbound shipping fees', total);
        else addToSummary('FBA fees other', total);
      }
      else if (type === 'Transfer') addToSummary('Transfer', total);
      else if (type === 'Shipping Services') addToSummary('FBM shipping fees', total);
      else addToSummary('Other', total);
    });

    const currentMap = new Map<string, AmazonAnalysisRecord>();
    records.forEach(r => {
      const d = new Date(r.date);
      const pk = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;
      const key = `${pk}|${r.sku}|${r.category}|${r.type}`;
      // Clone existing records to ensure they are plain objects
      currentMap.set(key, { ...r });
    });

    summaryMap.forEach((val, key) => {
      const existing = currentMap.get(key);
      if (existing) {
        existing.amount += val.amount;
        existing.quantity += val.quantity;
      } else {
        currentMap.set(key, val);
      }
    });

    onUpdateRecords(Array.from(currentMap.values()));
  };

  const pivotData = useMemo(() => {
    const periodSet = new Set<string>();
    const skuSet = new Set<string>();
    const amountMap: any = {};
    const qtyMap: any = {};

    records.forEach(r => {
      const d = new Date(r.date);
      const pk = `${d.toLocaleString('default', { month: 'short' })}${String(d.getFullYear()).slice(-2)}`;
      periodSet.add(pk);
      if (r.sku && r.sku !== 'NON-SKU') skuSet.add(r.sku);

      if (!amountMap[pk]) amountMap[pk] = {};
      if (!amountMap[pk][r.category]) amountMap[pk][r.category] = { _total: 0 };
      if (!amountMap[pk][r.category][r.sku]) amountMap[pk][r.category][r.sku] = {};
      if (!amountMap[pk][r.category][r.sku][r.type]) amountMap[pk][r.category][r.sku][r.type] = 0;

      amountMap[pk][r.category][r.sku][r.type] += r.amount;
      amountMap[pk][r.category]._total += r.amount;

      if (!qtyMap[pk]) qtyMap[pk] = {};
      if (!qtyMap[pk][r.sku]) qtyMap[pk][r.sku] = {};
      if (!qtyMap[pk][r.sku][r.type]) qtyMap[pk][r.sku][r.type] = 0;
      qtyMap[pk][r.sku][r.type] += r.quantity;
    });

    const sortedPeriods = Array.from(periodSet).sort((a, b) => {
      const parse = (s: string) => {
        const months: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
        const m = s.slice(0, 3);
        const y = parseInt(s.slice(3));
        return new Date(2000 + y, months[m]).getTime();
      };
      return parse(a) - parse(b);
    });

    return { periods: sortedPeriods, skus: Array.from(skuSet).sort(), amountMap, qtyMap };
  }, [records]);

  const getAmt = (period: string, cat: AmazonCategory, sku?: string, type?: string) => {
    const p = pivotData.amountMap[period];
    if (!p || !p[cat]) return 0;
    if (!sku) return p[cat]._total;
    if (!p[cat][sku]) return 0;
    if (!type) {
      return Object.values(p[cat][sku]).reduce((s: any, v: any) => s + v, 0);
    }
    return p[cat][sku][type] || 0;
  };

  const getQty = (period: string, sku: string, type: string) => {
    return pivotData.qtyMap[period]?.[sku]?.[type] || 0;
  };

  const clearData = () => {
    if (window.confirm("ARE YOU SURE? This will permanently wipe all previously uploaded Amazon Settlement analysis data. This cannot be undone.")) {
      onUpdateRecords([]);
      alert("Amazon settlement history has been wiped.");
    }
  };

  const FEE_LIST: AmazonCategory[] = [
    'Selling fees', 'FBA fees', 'FBA reimbursement', 'FBM shipping fees', 'Advertising fees',
    'FBA shipping fees', 'Inbound shipping fees', 'Account subscription', 'FBA fees other',
    'FBA storage fees', 'Return fees', 'Other fees', 'Other', 'AWD fees', 'FBA disposal fees',
    'Settlement expense'
  ];

  return (
    <div className="space-y-12 pb-24">
      <div className="flex justify-between items-center border-b-2 border-slate-900 pb-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{companyName}</h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mt-2">Aggregated Multi-Month Amazon Reconciliation</p>
        </div>
        <div className="flex gap-4">
          <button 
            onClick={clearData} 
            className="bg-red-50 text-red-600 px-6 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest border border-red-100 hover:bg-red-100 transition-all active:scale-95"
          >
            Wipe History
          </button>
          <input type="file" onChange={(e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => processAmazonCSV(ev.target?.result as string);
            reader.readAsText(file);
          }} accept=".csv" className="hidden" id="amz-upload" />
          <label htmlFor="amz-upload" className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-800 shadow-xl transition-all cursor-pointer flex items-center active:scale-95">
            Upload Settlement CSV
          </label>
        </div>
      </div>

      {records.length === 0 ? (
        <div className="bg-slate-100 rounded-3xl p-32 text-center border-2 border-dashed border-slate-200">
          <span className="text-5xl mb-6 block opacity-20">📦</span>
          <p className="text-slate-400 font-bold italic">Upload your Settlement Report CSV to populate the summaries.</p>
        </div>
      ) : (
        <div className="space-y-20 animate-in fade-in duration-500">

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-emerald-500 pl-3">Revenue by product</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">Product Description</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {pivotData.skus.map(sku => (
                    <tr key={sku} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-medium text-slate-600 truncate max-w-sm" title={sku}>{skuData[sku]?.name || sku}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, 'Revenue', sku);
                        return <td key={p} className="p-4 text-right font-mono text-slate-900">{val !== 0 ? val.toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}</td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-900 text-white font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Revenue</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-blue-500 pl-3">Gross to net revenue recon</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Revenue (Gross Orders)</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">{getAmt(p, 'Revenue', undefined, 'Order').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-700">Refunds</td>
                    {pivotData.periods.map(p => {
                      const val = getAmt(p, 'Revenue', undefined, 'Refund');
                      return <td key={p} className="p-4 text-right font-mono text-red-500">{val !== 0 ? `(${Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 })})` : '-'}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-900 text-emerald-400 font-black">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Revenue, net</td>
                    {pivotData.periods.map(p => <td key={p} className="p-4 text-right font-mono">${getAmt(p, 'Revenue').toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>)}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-amber-500 pl-3">Amazon fees</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-[11px] text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b">
                    <th className="p-4 font-black uppercase text-slate-400 w-96">$</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black text-slate-900 text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {FEE_LIST.map(fee => (
                    <tr key={fee} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-bold text-slate-700">{fee}</td>
                      {pivotData.periods.map(p => {
                        const val = getAmt(p, fee as AmazonCategory);
                        const isCredit = fee === 'FBA reimbursement';
                        return <td key={p} className={`p-4 text-right font-mono ${isCredit && val > 0 ? 'text-blue-600' : 'text-slate-900'}`}>{val !== 0 ? Math.abs(val).toLocaleString(undefined, { minimumFractionDigits: 0 }) : '-'}</td>
                      })}
                    </tr>
                  ))}
                  <tr className="bg-slate-100 font-black border-t-2 border-slate-200">
                    <td className="p-4 uppercase tracking-widest text-[10px]">Total Amazon Fees</td>
                    {pivotData.periods.map(p => {
                      const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                      return <td key={p} className="p-4 text-right font-mono">${Math.abs(feeSum).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>

          <section className="space-y-6">
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900 border-l-4 border-slate-900 pl-3">Net Amazon Settlement & Inventory Drain</h3>
            <div className="overflow-x-auto rounded-3xl border border-slate-200 shadow-sm bg-white">
              <table className="w-full text-xs text-left border-collapse">
                <thead>
                  <tr className="bg-slate-900 text-white border-b">
                    <th className="p-4 font-black uppercase tracking-widest text-[10px] w-96">Consolidated Impact Item</th>
                    {pivotData.periods.map(p => <th key={p} className="p-4 font-black uppercase text-right">{p}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  <tr>
                    <td className="p-4 font-bold text-slate-800">Net Amazon Calculated (Revenue - Fees)</td>
                    {pivotData.periods.map(p => {
                       const netRev = getAmt(p, 'Revenue');
                       const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                       const calc = netRev + feeSum;
                       return <td key={p} className="p-4 text-right font-mono font-bold text-slate-900">${calc.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr>
                    <td className="p-4 font-bold text-slate-800 italic">Net Amazon Transfer (Actual)</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       return <td key={p} className="p-4 text-right font-mono font-black text-emerald-600">${transfer.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-red-50 text-red-800">
                    <td className="p-4 font-black uppercase text-[10px]">Difference / Reconciling Factor</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       const netRev = getAmt(p, 'Revenue');
                       const feeSum = FEE_LIST.reduce((s, f) => s + getAmt(p, f as AmazonCategory), 0);
                       const diff = transfer - (netRev + feeSum);
                       return <td key={p} className={`p-4 text-right font-mono font-black ${Math.abs(diff) > 1 ? 'text-red-600' : 'text-slate-400'}`}>${diff.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-blue-50/30">
                    <td className="p-4 font-bold text-blue-900">Total COGS (Inventory Drain)</td>
                    {pivotData.periods.map(p => {
                      const cogs = pivotData.skus.reduce((s, sku) => s + (getQty(p, sku, 'Order') * (skuData[sku]?.cost || 0)), 0);
                      return <td key={p} className="p-4 text-right font-mono text-blue-700">${cogs.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-blue-50/30">
                    <td className="p-4 font-bold text-blue-900">COGS Reversal (Returned Value)</td>
                    {pivotData.periods.map(p => {
                      const rev = pivotData.skus.reduce((s, sku) => s + (Math.abs(getQty(p, sku, 'Refund')) * (skuData[sku]?.cost || 0)), 0);
                      return <td key={p} className="p-4 text-right font-mono text-blue-400">${rev.toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                  <tr className="bg-slate-50 border-t-2 border-slate-200">
                    <td className="p-4 font-black text-slate-900">Final Amazon Net Margin Contribution</td>
                    {pivotData.periods.map(p => {
                       const transfer = Math.abs(getAmt(p, 'Transfer'));
                       const cogs = pivotData.skus.reduce((s, sku) => s + (getQty(p, sku, 'Order') * (skuData[sku]?.cost || 0)), 0);
                       const rev = pivotData.skus.reduce((s, sku) => s + (Math.abs(getQty(p, sku, 'Refund')) * (skuData[sku]?.cost || 0)), 0);
                       return <td key={p} className="p-4 text-right font-mono font-black text-slate-900">${(transfer - cogs + rev).toLocaleString(undefined, { minimumFractionDigits: 0 })}</td>
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </section>
        </div>
      )}
    </div>
  );
};

export default AmazonAnalysis;
